INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e090f03c9b0', 'en', 'US', 'Beef Empanadas', 'Recipe video above. This dough is easy to work with and comes together in seconds using a good processor. While I really encourage you to make the dough, you''ll still get an excellent empanada fix making this with store-bought puff pastry or shortcrust pastry.Empanada dough adapted from Kevin Is Cooking and the filling is based on the New York Times Cooking Beef Empanadas recipe (I found the flavour a bit mild and too dry, so I tweaked).', 'https://www.recipetineats.com/tachyon/2023/04/Beef-empanadas_7.jpg', 45, 50, 95, 10, '[{"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chorizo", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 150.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_empanada_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_other_options", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 cups plain/all-purpose flour","175g/ 12 tbsp cold unsalted butter (, cut into 1 cm / 1/2\" cubes)","1 tsp cooking/kosher salt","1 egg yolk","1/2 cup warm milk (, full fat (30 sec microwave))"],"purpose":"Empanada shortcrust pastry:"},{"ingredients":["1 1/2 tbsp olive oil","1/2 onion (, finely chopped)","1 garlic cloves (, minced)","300g/10 oz beef mince (ground beef)","120g/4 oz chorizo","2 tsp tomato paste","1 tsp fresh thyme (, finely chopped)","1/2 tsp EACH dried oregano, cumin, paprika","1/4 tsp cayenne pepper","1/4 tsp cooking/kosher salt","3/4 cup chicken stock/broth (, low sodium)","1/2 cup tomato passata (sub US tomato sauce or crushed tomato)","150g/5oz potato (, peeled, cut into 8mm/ 1/3\" cubes (~1 cup))","1/3 cup green onion (, finely sliced)"],"purpose":"Empanada Filling:"},{"ingredients":["2 hard boiled eggs (9 minutes using this method)","1/4 cup green olives (, roughly chopped)","2 eggs (, separated, yolks whisked (for sealing and brushing pastry))"],"purpose":"Other:"},{"ingredients":["Empanada sauce","Other options (- ketchup, ketchup + sriracha, pink sauce, taco sauce, salsa dip)"],"purpose":"Dipping sauces:"}]', '[{"description":"Empanada Filling:","images":[],"step":1},{"title":"Blitz chorizo","description":"Roughly chop chorizo into 1.5cm / 1/2\" pieces. Blitz using a stick blender until it becomes a paste (Note 1)","images":[],"step":2},{"title":"Sauté aromatics","description":"Heat oil in a large non stick pan over high heat. Cook onion and garlic for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Cook meat","description":"Add chorizo and cook for 2 minutes. Add beef and cook until you no longer see raw beef. Add tomato paste and cook for 1 minute. Then add everything else except green onion, then stir.","duration":2,"images":[],"step":4},{"title":"Cook 15 min","description":"Bring to a simmer then lower heat so it''s simmering gently. Cook for 15 minutes, stirring every now and then. Goal - juicy but not watery filling, with cooked potato.","duration":15,"images":[],"step":5},{"title":"Cool","description":"Stir through green onion. Transfer to bowl and fully cool before using (~ 2 hours).","images":[],"step":6},{"description":"Empanada shortcrust pastry:","images":[],"step":7},{"title":"Blitz dough","description":"Whisk milk and yolk in a small jug. Pulse flour, salt and butter in a food processor until the butter becomes fine crumbs - largest lumps no bigger than peas (~ 4 to 6 times). Add egg-milk mixture, then blitz on low until it comes together into a ball of dough - about 10 seconds. (Note 2 for hand method)","images":[],"step":8},{"title":"Chill 30 min","description":"Turn out onto a lightly floured work surface, then bring together into a smooth log ~20cm/8\" long. Cut in half, shape into 2cm / 0/8\" thick round discs. Wrap in cling wrap then refrigerate 30 minutes (or overnight - Note 3).","images":[],"step":9},{"title":"Cut rounds","description":"Place one chilled disc on a lightly floured work surface. Roll out to 3 mm / 0.1\" thickness. Cut 15 cm/6\" rounds (I use a bowl), or other size as desired (Note 3). Keep covered in the fridge, stacked on paper, as you continue to roll and cut. You should get 10 or 11 rounds.","images":[],"step":10},{"description":"Make empanadas:","images":[],"step":11},{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":12},{"title":"Filling","description":"Filling should be cold but spreadable (Note 4). Place 3 tablespoons (55g) of filling on the top half of a round of pastry. Spread flat in a half-moon shape, leaving a 1.5cm / 0.6\" border. Sprinkle with olive and egg.","images":[],"step":13},{"title":"Seal","description":"Brush edge with egg white, fold to enclose, pressing out air and sealing the edge. Optional: Do empanada pleats - see step photos in post or video at 3 min 30 sec. Alternatively, crimp with fork or leave plain.","images":[],"step":14},{"title":"Bake 20 min","description":"Place empanadas on 2 baking trays. Brush with egg yolk. Bake 20 minutes or until golden brown all over and crispy on the base.","images":[],"step":15},{"title":"Serve hot with dipping sauce of choice","description":"my favourite is the homemade Empanada Sauce!","images":[],"step":16}]', '["egg","gluten","milk"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Brazilian","South American"],"categories":["iconic-dishes","quiches-tart-and-pie-recipes","snacks","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c52c7aca968a', 'en', 'US', 'Toad in the hole', 'Recipe video above. The great British classic! Sausages nestled in a giant Yorkshire pudding, in all its puffed up glory, with delightfully crispy edges. The trick for stability is a dab of mayonnaise! Taught to me by an English chef, learned from his days working in pubs and restaurants in the UK. (See note 4)Some recipes will have you just bake the sausages from raw, but your gravy will be much tastier if you start with sausage drippings. So sear your sausages first!', 'https://www.recipetineats.com/tachyon/2023/02/Toad-in-the-hole_4.jpg', 15, 40, 55, 4, '[{"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 20.833, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["700g/1.4lb pork sausages, or other sausage (8 x 85g/3oz, Note 1)","10g / 2 tsp beef drippings OR canola/veg oil (Note 4)"]},{"ingredients":["250 ml / 1 cup eggs (, lightly whisked (4-5 large eggs, yes, I need you to measure! Note 2))","1 cup plain flour (all-purpose flour)","3/4 cup milk (, full fat)","1/4 cup water","1 tbsp mayonnaise (, full-fat (secret ingredient! See Note 3))","1/2 tsp cooking salt (kosher salt)","Pinch white pepper","50g (1/4 cup) beef drippings OR canola/veg oil (Note 4)"],"purpose":"Yorkshire pudding Batter:"},{"ingredients":["30g / 2 tbsp beef drippings OR unsalted butter (Note 4)","2 onions (, halved, cut into 7 mm / 1/4\" wedges)","1 garlic clove (, finely minced)","3 tbsp plain flour (all-purpose flour)","2 cups beef stock (broth) (, low sodium)","1/2 tsp Worcestershire sauce","1/2 tsp black pepper","1/4 tsp cooking salt (kosher salt)"],"purpose":"Onion gravy:"}]', '[{"title":"Batter","description":"Whisk eggs in a bowl, then whisk in flour until lump free. Whisk in water, milk, mayonnaise, salt and pepper. Place in the fridge until required.","images":[],"step":1},{"description":"Preheat oven to 220°C/425°F (200°C fan). Put the 1/4 cup beef drippings in a 23 x 33cm metal pan (9 x 13\"). Place in the oven for 15 minutes to melt and become very hot.","duration":15,"images":[],"step":2},{"title":"Brown sausages","description":"Heat the 2 tsp (10g) of drippings in a pan over medium high heat. Brown the sausages all over, but keep one side just lightly browned (this side will brown more in the oven). Keep them raw inside. Remove onto a plate.","images":[],"step":3},{"title":"Assemble","description":"Take batter out of fridge and whisk. Working quickly, take the hot pan out of oven. Spread sausages in the pan, lightly browned side up, keeping clear of the pan walls (Note 5 for arranging tip). Pour the batter in around the sausages.","images":[],"step":4},{"title":"Bake","description":"Bake 25 minutes on the top shelf until the sides puff up and is golden brown. The top of the edges should be nice and crispy!","images":[],"step":5},{"description":"Serve immediately with onion gravy! Expect some deflation - though far less than typical recipes thanks to the mayo.","images":[],"step":6},{"description":"Onion gravy (Note 6):","images":[],"step":7},{"title":"Brown onion","description":"Add beef drippings into the pan used for browning the sausages. Melt over high heat. Add onions and cook, stirring constantly, until nicely browned (~5 minutes). Add garlic and stir 30 seconds. Add flour and stir for 1 minute so it''s well mixed through the onions (= lump-free gravy!).","duration":1,"images":[],"step":8},{"title":"Add stock","description":"Slowly pour in beef stock, stirring as you go. Add Worcestershire sauce, salt and pepper.","images":[],"step":9},{"title":"Thicken","description":"Bring to a simmer, stirring, for 2 minutes until thickens into a gravy. Keep warm until ready to use!","duration":2,"images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["iconic-dishes","news","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cea89452d5df', 'en', 'US', 'Borek', 'Recipe video above. If you think this Borek looks amazing, just wait until you taste it!! A spiced lamb filling littered with pine nuts and currants encased in layers up on layers of flaky filo pastry arranged in a dramatic spiral, this pastry goes by various names incuding burek, bourekas, and byrek.It''s an excellent return on effort, looking so much more difficult than it actually is to make!Vegetarian version - Use the spinach feta filling from Spanakopita!', 'https://www.recipetineats.com/tachyon/2021/07/Borek_40.jpg', 30, 60, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_currants", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.06, "unit": "tub of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_sheets_phyllo_pastry", "quantity": {"value": 12.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely diced (1 small or 1/2 a large))","2 garlic cloves (, finely minced)","600g / 1.2 lb lamb mince (ie. ground lamb, or substitute beef)","1 1/2 tsp ground cumin","3/4 tsp each of ground coriander, cinnamon, paprika (plain or sweet paprika)","1/2 tsp allspice (sub mixed spice or similar spice mix)","1/2 tsp cayenne pepper or Turkish red pepper flakes (reduce for less spicy)","1/2 tsp black pepper","1 1/4 tsp salt (cooking / kosher salt, OR 1 tsp table salt)","1/3 cup currants (or raisins or sultanas, roughly chopped)","1/3 cup pine nuts (, toasted (Note 1))","1 cup tomato passata (tomato puree in US, Note 2)","1/4 cup water"],"purpose":"Lamb Filling:"},{"ingredients":["1 egg","2 tbsp plain yogurt","30g / 2 tbsp unsalted butter (, melted)"],"purpose":"Yogurt wash for filo (stops cracking):"},{"ingredients":["12 sheets phyllo pastry (Note 3)","25g / 1 1/2 tbsp unsalted butter (, melted and cooled)","White sesame seeds (optional)"],"purpose":"Pastry:"},{"ingredients":["1 cup plain yogurt","1/4 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","Pinch of salt"],"purpose":"Lemon Yogurt Sauce:"}]', '[{"title":"Cook onion and garlic","description":"Heat oil on high in a large skillet. Cook onion and garlic for 2 to 3 minutes until softened.","duration":2.5,"images":[],"step":1},{"title":"Cook lamb and spices","description":"Add lamb and cook lamb, breaking it up as you go, until mostly changes from pink to brown. Then add all the spices and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Simmer","description":"Add tomato passata and water, mix. Then add currants and pine nuts. Bring to simmer, turn heat down to medium low and cook until liquid reduces so the mixture is moist but not watery.","images":[],"step":3},{"title":"Cool","description":"Remove from stove and allow to fully cool before using.","images":[],"step":4},{"description":"Lemon Yogurt Sauce:","images":[],"step":5},{"description":"Mix ingredients in a small bowl. Set aside for at least 20 minutes.","images":[],"step":6},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":7},{"title":"Yogurt Wash (Note 4)","description":"Mix ingredients until combined.","images":[],"step":8},{"title":"Prepare filo","description":"Open the filo pastry packet and unroll the pastry. Peel one layer off and place on a piece of baking / parchment paper. Cover the remainder with a lightweight damp tea towel to stop them from drying out.","images":[],"step":9},{"title":"Brush with yogurt wash","description":"Drizzle / flick yogurt wash across filo using a pastry brush. Then lightly brush across surface in a thin layer. You don''t need to cover every inch, just mostly cover the surface.","images":[],"step":10},{"title":"Layer filo","description":"Top with another filo pastry sheet, and brush this too with yogurt wash. Then repeat so you have 4 layers in total, but do not brush the last (4th) filo with yogurt wash once laid.","images":[],"step":11},{"title":"Fill and roll","description":"Place 1/3 of the Lamb filling along the bottom edge. Using the aid of a long kitchen knife to get it started, roll up into a log. Doesn''t need to be tight and don''t try, as the pastry is delicate.","images":[],"step":12},{"title":"Make 3 logs","description":"Repeat to make 3 logs, using all the Filling.","images":[],"step":13},{"description":"Shape into spiral and bake:","images":[],"step":14},{"title":"Spiral","description":"Take one log and place on a piece of baking / parchment paper. Coil into a spiral. Join a second log to the first by stuffing the ends inside each other, using yogurt wash to adhere. Continue forming the spiral. Log sides should be in contact but not tightly squished.","images":[],"step":15},{"title":"Transfer to baking vessel","description":"Brush a 26cm / 10.5″ cast iron skillet (Note 5) with melted butter. Then use the paper to transfer the borek into the skillet, and slide the paper out.","images":[],"step":16},{"title":"Brush with butter","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":17},{"description":"Bake for 40 minutes or until pastry is golden.","duration":40,"images":[],"step":18},{"description":"Serve! Remove from oven. Cut wedges like pie. Serve with Lemon Yogurt Sauce!","images":[],"step":19}]', '["egg","milk","sesame"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Turkish"],"categories":["iconic-dishes","lamb-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3ec20059fd3', 'en', 'US', 'Easy slow cooker BBQ pulled pork', 'Recipe video above. This may well be the juiciest, most flavourful pulled pork you ever have in your life! Homemade BBQ Sauce totally makes it. And there''s no denying that using a slow cooker yields the juiciest pulled pork with very little effort. BIG BATCH recipe, 100% perfect for freezing, ideal for entertaining!Love this recipe? One day, try my ultimate Pulled Pork recipe.', 'https://www.recipetineats.com/tachyon/2019/11/Close-up-of-pulled-pork-with-BBQ-Sauce.jpg', 15, 600, 615, 12, '[{"id": "ing_pork_shoulder", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.0, "unit": "bottle of 330ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.037, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.08, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["3.5-4.5kg/ 5-7lb pork butt / pork shoulder (, bone in, fat cap on (Note 1))","1 cup beer (, apple cider or apple juice (Note 2))"]},{"ingredients":["3 tbsp brown sugar","1 tbsp paprika powder","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","1 tbsp salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","1 cup water (or use remaining beer!)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, for spiciness))"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix the Rub together, then rub all over the pork.","images":[],"step":1},{"description":"Place in a slow cooker, pour over beer. Slow cook on low for 10 hours. Pork should be tender enough to easily shred.","images":[],"step":2},{"description":"Browning in oven (optional, recommended):","images":[],"step":3},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":4},{"description":"Transfer from slow cooker into a roasting pan (reserve liquid).","images":[],"step":5},{"description":"Scoop fat off surface of juices in slow cooker and drizzle over pork (about 1/3 cup), then roast pork for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven, cut thick layer of fat off top and discard. Spoon over 1/4 cup fat from slow cooker juices, then roast 15 minutes.","images":[],"step":7},{"description":"Shred pork using 2 forks. Pour over BBQ sauce, toss gently.","images":[],"step":8},{"description":"Serve stuffed in sliders with Coleslaw, or make a Southern dinner plate with Coleslaw, Mac and Cheese, Corn bread, steamed corn & green beans tossed in butter, with Margaritas to quench your thirst!","images":[],"step":9},{"description":"Barbecue Sauce:","images":[],"step":10},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":11},{"title":"Add 3/4","description":"1 cup of juices from slow cooker until sauce is syrup consistency.","images":[],"step":12},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use per recipe.","images":[],"step":13}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["iconic-dishes","pork-recipes","sandwiches-and-sliders","sauces","slow-cooked-fall-apart","slow-cooker-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_032482eb232b', 'en', 'US', 'Reuben Sandwich recipe!', 'Recipe VIDEO above. The iconic Reuben Sandwich made famous by Katz''s Deli in New York, made at home! Hands down still one of the best sandwiches I have ever had in my life, the most incredible combination of ingredients, the star of which is warm fall-apart tender homemade pastrami!', 'https://www.recipetineats.com/tachyon/2019/04/Reuben-Sandwich_8-copy.jpg', 20, 15, 35, 5, '[{"id": "ing_homemade_pastrami", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 10.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_grapes", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cabbage", "quantity": {"value": 350.0, "unit": "head"}}, {"id": "ing_vinegar", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_dill_pickle_gherkin", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.007, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_horseradish_to_taste", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 kg / 2 lb homemade pastrami (1 quantity, easy!) (Note 1)","10 slices light rye bread","10 slices Swiss cheese","Butter (, for spreading)"]},{"ingredients":["1 tbsp grapeseed oil","1/2 onion (, thinly sliced)","350g/ 12 oz white cabbage (, thinly shredded (1/4 large head, 6 - 8 big handfuls))","1 1/4 cups (300ml) cider vinegar","1/3 cup (85 ml) water","1 tsp salt","2 tsp sugar","1 tsp caraway seeds (, optional (Note 2))"],"purpose":"Quick Sauerkraut:"},{"ingredients":["1 tbsp onion (, finely minced)","1 tbsp dill pickle/gherkin (, finely minced)","3/4 cup mayonnaise","1/4 cup sour cream (can sub more mayo)","2.5 tbsp sriracha, spicy ketchup or Chili Sauce (or 1/4 cup ketchup + 2 tsp tabasco) (Note 3)","3 tsp horseradish (jar), to taste (spicy/tang)","1 tsp Worcestershire sauce","1/4 tsp sweet paprika"],"purpose":"Russian Dressing:"}]', '[{"description":"Russian Dressing:","images":[],"step":1},{"description":"Mix ingredients, refrigerate 20 minutes+ (keeps 2 weeks).","images":[],"step":2},{"description":"Quick Sauerkraut:","images":[],"step":3},{"description":"Dissolve sugar and salt in vinegar.","images":[],"step":4},{"description":"Heat oil in a large pot over medium heat. Add onion and cook for 2 minutes to soften, don''t let it brown.","duration":2,"images":[],"step":5},{"description":"Add cabbage, vinegar, water and caraway seeds, give it a toss.","images":[],"step":6},{"description":"Cover, cook on low for 15 minutes, mixing once at 10 minutes.","duration":15,"images":[],"step":7},{"description":"Transfer to container (including liquid), cool until just warm. Keeps 2 weeks in the fridge.","images":[],"step":8},{"description":"Prepare Pastrami:","images":[],"step":9},{"description":"Thinly slice still cold pastrami (Note 1). Place in a container with a couple of tablespoons of pastrami liquid (reserved from cooking, see pastrami recipe).","images":[],"step":10},{"description":"Microwave to warm through (or use other method of choice etc cover with foil and place in oven).","images":[],"step":11},{"description":"Assemble Reuben:","images":[],"step":12},{"description":"Preheat grill/broiler to medium high with shelf about 25cm/10\" from heat source.","images":[],"step":13},{"description":"Toast bread. Spread with butter, then 1 tbsp Russian Dressing on each piece.","images":[],"step":14},{"description":"Pick up pastrami and let excess juices drip away, then place on bread.","images":[],"step":15},{"description":"Do same for sauerkraut, pile onto pastrami, then top with cheese.","images":[],"step":16},{"description":"Also place cheese on other slice of bread (ie with just Russian Dressing).","images":[],"step":17},{"description":"Place under grill until cheese is just melted. Sandwich together and devour while hot!","images":[],"step":18}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["American","Jewish"],"categories":["iconic-dishes","sandwiches-and-sliders","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca6f84ac8c5d', 'en', 'US', 'Gozleme!!', 'Recipe video above. Crispy Turkish flatbreads stuffed with juicy fillings! Choose ONE Filling - either Spinach and Feta, or spiced Lamb OR Beef with spinach and peppers. Can stretch to 5 gozlemes. Works with GLUTEN FREE flour too!', 'https://www.recipetineats.com/tachyon/2019/03/Spinach-Feta-Gozleme.jpg', 30, 20, 50, 4, '[{"id": "ing_flour", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 390.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 420.0, "unit": "block of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 3.2, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.034, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.019, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["2.5 cups (375g) flour (, plain/all purpose (GF Note 4))","1/3 cup (85ml) extra virgin olive oil","3/4 cup (185ml) water","1/2 tsp salt"],"purpose":"Gozleme pastry:"},{"ingredients":["300g / 10oz baby spinach","2 garlic cloves (, minced)","2 eggs","1 tsp black pepper","300g / 10 oz Danish feta (soft feta, Note 2)","2 cups (200g) shredded mozzarella cheese (Note 3)"],"purpose":"Spinach & Feta:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef or lamb mince (ground)","1 capsicum / bell pepper (, chopped)","90g / 3 oz baby spinach","1.5 tsp cumin powder","1 tsp paprika","1/2 tsp cayenne (adjust spiciness to taste)","3/4 tsp each salt and pepper","1 tbsp water","120g / 4 oz Danish feta (Note 2)"],"purpose":"Spiced Lamb or Beef:"},{"ingredients":["1 - 1.5 tbsp olive oil (, per gozleme)","Lemon wedges (optional)"],"purpose":"Cooking / Serving:"}]', '[{"description":"Fit stand mixer with dough hook. Combine flour, oil, salt and water in the stand mixer bowl. Mix for 2.5 minutes on medium high speed 7 until smooth (see video for before & after). (Note 4) Dough should be a pliable, smooth ball, not sticky.","images":[],"step":1},{"description":"Cover and rest for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Sprinkle work surface with flour. Cut dough into 4 pieces.","images":[],"step":3},{"description":"Roll out into 35cm/14\" x 20cm/8\" rectangle.","images":[],"step":4},{"description":"Make EITHER the lamb / beef Filling, or Spinach & Feta (or make 1/2 batch of both!).","images":[],"step":5},{"description":"Lamb or Beef Filling:","images":[],"step":6},{"description":"Heat oil in large skillet over high heat.","images":[],"step":7},{"description":"Cook garlic and onion for 1 minute. Add capsicum, cook for 2 minutes.","duration":1,"images":[],"step":8},{"description":"Add beef and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":9},{"description":"Add cumin, paprika, cayenne (if using), salt, pepper and water. Cook for 2 minutes.","duration":2,"images":[],"step":10},{"description":"Add spinach, stir until wilted.","images":[],"step":11},{"description":"Cool before using.","images":[],"step":12},{"description":"Spinach Feta Filling:","images":[],"step":13},{"description":"Place spinach, garlic, egg and pepper in a bowl. Scrunch with hands to reduce volume and make spinach \"floppy\".","images":[],"step":14},{"description":"Add feta and stir through.","images":[],"step":15},{"description":"Making Gozleme:","images":[],"step":16},{"description":"Spread Filling on half the pastry, pushing to the edge. Sprinkle Lamb/Beef Filling with crumbled feta. Sprinkle Spinach Feta with mozzarella cheese, if using.","images":[],"step":17},{"description":"Fold other side of pastry over to cover Filling. Press down edges, pressing out excess air pockets trapped inside as you go. Use water if needed to seal well.","images":[],"step":18},{"description":"Sprinkle flour on a round pizza paddle (or similar). Slide gozleme onto paddle.","images":[],"step":19},{"description":"Cooking:","images":[],"step":20},{"description":"Heat 1.5 tbsp oil in a large skillet over medium high heat. (I usually get 2 pans going)","images":[],"step":21},{"description":"Slide gozleme into skillet. Cook, lightly pressing down (including edges), until deep golden and crispy - about 3 minutes. Flip and cook, pressing down lightly, until crispy.","images":[],"step":22},{"description":"Transfer to cutting board. Cut into 6 or 8 pieces.","images":[],"step":23},{"description":"Serve immediately with lemon wedges, if desired.","images":[],"step":24}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Turkish"],"categories":["iconic-dishes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0151e07f93dd', 'en', 'US', 'Mexican Fiesta Menu', 'Round up the amigos for a Mexican Fiesta! The suggested menu plan below is a great low-effort one with wow factor. Plenty for making ahead and the Carnitas freeze perfectly! See recipes linked to each dish, or where not linked, directions are below. Cook time includes slow cooking time for Carnitas.', 'https://www.recipetineats.com/tachyon/2018/05/Mexican-Fiesta.jpg', 60, 600, 660, 8, '[{"id": "ing_pork", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_restaurant_style_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_authentic_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_queso_dip", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_pig_out_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_refried_beans", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_churros", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["Pork Carnitas","Restaurant style salsa (doubles as taco sauce + dip)","Authentic Guacamole","Pickled red cabbage (Note 1)","Warmed tortillas","Homemade tortilla chips (see below)","Grilled corn (See below)","Sour Cream","Chopped white onions (Note 2)","Coriander/cilantro leaves (whole or chopped)","Lime wedges"],"purpose":"Mexican Fiesta menu plan (as pictured in post):"},{"ingredients":["Marinated Chicken for tacos","Lime marinated chicken","Chicken Fajitas","Mexican Shredded Chicken","Beef Fajitas","Mexican Shredded Beef","Fish Tacos","Prawn/shrimp Tacos"],"purpose":"Other Protein options:"},{"ingredients":["Pico de Gallo","Queso Dip (stays silky when cool!)","Mexican Corn Salad","Avocado Corn Salad","Mexican Grilled Corn with Chipotle Adobo Sauce","Pig Out Salsa (Chorizo and Corn)","Mexican Red Rice","Refried Beans (Note 3)","Shredded Cheeses","Avocado Slices (instead of guac)","Hot Sauces","Sliced Jalapeno"],"purpose":"Other Side options:"},{"ingredients":["Churros (quick, and great for make ahead)"],"purpose":"To Finish:"}]', '[{"description":"Choose one or two proteins, then sides of choice. See linked recipes for directions (except tortilla chips and grilled corn, see below).","images":[],"step":1},{"title":"Main Taco Filling Selection","description":"The most convenient big batch protein is Pork Carnitas because it freezes great and only requires a quick pan fry to freshen up, and stays good for several hours (tips are in Carnitas recipe notes). The Shredded Chicken and Beef are almost as good (pork is slightly juicier) and stored similarly. The next simplest is Fish Tacos because it''s very quick to cook, then just put them in a serving dish and break into chunks with fork. If you want to use one of the chicken recipes to make ahead, use boneless thigh fillets, cook, then keep whole, cover and cool, reserve every drop of leached juice. Before serving, chop/slice, cover and microwave reheat.","images":[],"step":2},{"title":"Taco Fixings","description":"I like to have at least one fresh thing to stuff in tacos (pickled cabbage is my choice in this Fiesta), + a sauce (the Restaurant Style Salsa,) + avocado in some form (guac or slices or in Pico de Gallo) + coriander/cilantro. Chopped white onion is very common in Mexico, and Tex Mex fans such as myself will almost always have sour cream and shredded cheese too!","images":[],"step":3},{"title":"Other Sides","description":"Tortillas + things to stuff in tortillas usually makes for a satisfying meal in itself, but to round things out I usually provide a salad or vegetables of some form. Plain grilled corn is very on theme!","images":[],"step":4},{"description":"Directions (for items listed above without recipe link):","images":[],"step":5},{"title":"Homemade Tortillas Chips","description":"Chop corn tortillas to desired shape, fry in oil until crisp and light golden. Transfer for paper towel, sprinkle with salt while hot.","images":[],"step":6},{"title":"Grilled Corn","description":"Grill corn on BBQ over high heat until nicely charred. Brush with melted salted butter and sprinkle with chipotle powder (or chilli or cayenne, to taste)","images":[],"step":7}]', '["fish","milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["iconic-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6881b7104693', 'en', 'US', 'Vegetable Samosa Pie', 'Recipe video above. Take everything you know about samosas - the curried mashed potato filling, the crispy pastry - put it in giant pie form, add a stack of extra vegetables and voila! Vegetable Samosa Pie! This is a big, vegetarian main course dinner that''s something different yet also familiar, and wonderfully versatile - stuff with any veggies you want.Simplify SPICES: I''ve stayed true to traditional Samosa filling, so there''s a fairly lengthy list of spices. It can be drastically simplified - see Notes 1 to 3.SPICINESS: Very mild - just a slight warmth. Dial it up if you want, or omit it!Blind baking / Crispy Base: See Note 5.Those who tried the South Indian Eggplant Curry I shared last week will love the common ingredients in this!', 'https://www.recipetineats.com/tachyon/2020/08/Vegetable-Samosa-Pie__2.jpg', 15, 100, 115, 6, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_curry_leaves", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.03, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4lb potato (, cut into 2cm / 4/5\" pieces)"]},{"ingredients":["3 tbsp vegetable oil","1.5 tsp black mustard seeds (Note 1)","1 tsp cumin seeds (Note 2)","1 tsp fennel seeds (Note 2)","15 curry leaves (, fresh (Note 3))","1 tbsp garlic (, finely grated)","1 tbsp ginger (, finely grated)","1 onion (, finely chopped (brown, white, yellow))","1/2 tsp turmeric powder","2 tsp curry powder (Note 4)","1/2 tsp chilli powder (, adjust spiciness to taste (pure ground, not US Chili Spice Mi, sub cayenne)","1 tbsp tomato paste","1 tomato * (, chopped into 1.5cm / 1/2\" pieces)","1 zucchini * (, chopped into 1.5cm / 1/2\" pieces)","1 carrot * (, chopped into 1.5cm / 1/2\" pieces)","1/2 cauliflower * (small), cut/broken into small florets (~ 3 cups)","1/2 tsp black pepper","1 tsp salt","2 cups water","1 cup frozen green peas *"],"purpose":"Filling:"},{"ingredients":["2 sheets puff pastry (Note 5)","1 egg (, lightly whisked)"],"purpose":"Puff pastry crust:"},{"ingredients":["Plain yogurt","Coriander/cilantro leaves (, option (decorative only, pictured))"],"purpose":"Serving:"}]', '[{"description":"Bring a pot of water to the boil then cook potato for 12 - 15 minutes until very soft.","duration":13.5,"images":[],"step":1},{"description":"Drain, mash and set aside.","images":[],"step":2},{"title":"Sizzling spices","description":"Heat oil in a dutch oven or pot over high heat. Add black mustard seeds, cumin and fennel seeds. Let them sizzle for 15 seconds - careful, they might pop!","duration":0.25,"images":[],"step":3},{"title":"Curry leaves","description":"Then add curry leaves and stir for 15 seconds.","duration":0.25,"images":[],"step":4},{"title":"Aromatics","description":"Add garlic, ginger and onion. Cook for 4 to 5 minutes until onion is tinged with gold.","duration":4.5,"images":[],"step":5},{"title":"Tomato","description":"Add tomato paste and tomato, cook for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Spices","description":"Add curry powder, turmeric and chilli. Cook for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Most Veg","description":"Add zucchini, carrot and cauliflower. Stir well to coat in the spice paste.","images":[],"step":8},{"title":"Water","description":"Add water, salt and pepper. Stir, bring to a simmer then put the lid on and reduce heat to medium low (so it''s simmer gently).","images":[],"step":9},{"title":"Cook & reduce","description":"Cook for 15 minutes until vegetables are soft. Then remove lid and simmer for 5 minutes to reduce liquid a bit.","duration":15,"images":[],"step":10},{"title":"Add mash","description":"Remove from stove. Add peas and potato, mix through well.","images":[],"step":11},{"title":"Taste","description":"Taste and add more salt and pepper if needed.","images":[],"step":12},{"title":"Cool","description":"Place lid on and cool for at least 30 minutes (even overnight is fine).","images":[],"step":13},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":14},{"description":"Grease a large pie dish with butter, or oil spray (Note 6). Drape in a puff pastry sheet.(I don''t blind bake here - see Note 5)","images":[],"step":15},{"title":"Fill with Filling","description":"slightly mounded is fine.","images":[],"step":16},{"description":"Fold in the corners of the puff pastry sheet.","images":[],"step":17},{"title":"Top with puff pastry sheet","description":"turn 90 degrees to the base puff pastry sheet (see photo).","images":[],"step":18},{"title":"Fold the overhang puff pastry under itself","description":"no need to be neat here, this is a rustic pie!","images":[],"step":19},{"title":"Egg wash","description":"Brush with egg, cut a 2cm / 1\" cross in the middle (to let steam escape).","images":[],"step":20},{"description":"Bake 50 to 60 minutes, until the top is very deep golden and flaky.","images":[],"step":21},{"description":"Stand 5 minutes then slice to serve. A dollop of plain yogurt goes well with this!","images":[],"step":22}]', '["egg","milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["indian-recipes","main-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fc11d8b13e0d', 'en', 'US', 'Penne alla Vodka', 'Recipe video above. I think this was THE viral pasta about 5 years ago - but I totally missed the trend (not cool enough 😅). While the young probably love that it''s got vodka in it, I love it because you get to use a whole packet of pasta and a whole tub of tomato paste - no measuring, no waste!Jokes aside, vodka adds depth and almost floral-like notes into the sauce without tasting boozy, and though not a standard step, cooking off the paste really lifts the flavour and cuts the sourness. Makes regular taste just as good as the pricier double-concentrate paste!', 'https://www.recipetineats.com/tachyon/2025/08/Penne-alla-vodka_2.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.008, "unit": "carton of 250ml"}}, {"id": "ing_vodka", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb penne or ziti (rigatoni is also a fave, else any other pasta)","2 tsp cooking salt / kosher salt (, for pasta cooking water)","1 1/2 tbsp olive oil","1/2 small onion (, finely diced (smaller dice than usual is better))","2 garlic cloves (, finely minced)","1/2 cup (140g / 4.5 oz) tomato paste (UK: tomato puree)","1 1/4 cups heavy / thickened cream (UK: double cream - Note 2)","1/3 cup vodka (, or chicken stock/broth for alcohol free (Note 3))","1/2 tsp red pepper flakes ((chilli flakes), 100% optional)","3/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch black pepper","50g / 1 loosely packed cup freshly grated parmesan (, plus more for serving (Note 4))","1/2 cup+ pasta cooking water (Note 5)","2 tsp parsley (, finely chopped, for serving (optional))"]}]', '[{"description":"Sauté garlic and onion, cook off tomato paste, simmer with cream, vodka, chilli flakes, S&P 3 min, stir in parmesan at end. Toss with pasta and 1/2 cup pasta water, eat!","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water to the boil with the pasta salt. Cook pasta per the packet directions until al dente. (Meanwhile cook the sauce)","images":[],"step":2},{"title":"⭐️ Reserve pasta water","description":"Just before draining, give the pasta a big stir to agitate the starch then scoop out a cup of the water. Then drain the pasta.","images":[],"step":3},{"title":"Sauté","description":"Heat the oil in a large pot or non-stick pan over medium high heat. Cook the onion and garlic for 1 1/2 minutes until translucent. Add the tomato paste and cook, stirring constantly, for 2 minutes until it darkens in colour (lower heat if catching on base).","duration":2,"images":[],"step":4},{"title":"Make sauce","description":"Add the cream, stir well to dissolve the tomato paste. Then add the chilli flakes, salt, pepper and vodka. Simmer on low for 3 minutes, stirring regularly. Stir in the parmesan until melted, then turn off the heat until the pasta is ready.","duration":3,"images":[],"step":5},{"description":"Toss! Add the pasta and 1/2 cup of the pasta cooking water. Over medium heat on the stove, stir for 1 - 1 1/2 minutes until all the pasta is nicely coated with the rust coloured sauce, using extra pasta cooking water to loosen if needed.","images":[],"step":6},{"description":"Serve immediately in warmed pasta bowls* with a dusting of extra parmesan and pinch of parsley. Add a side of garlic bread and big Italian Salad, then finish with Tiramisu for a classic trattoria meal at home!","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_deba1e59e15a', 'en', 'US', 'Easy Ricotta Gnocchi with creamy mushroom sauce', 'Recipe video above. An easy recipe for pillowy soft gnocchi made using ricotta instead of potato. It''s real Italian food - fast! Takes a third of the time to make compared to potato gnocchi, and it''s lighter and softer so you won''t feel as weighed down. Served with a creamy mushroom sauce which is to-die-for sauce for pillowy soft gnocchi. See below recipe card for more gnocchi sauces. Serves 3 as a main, 4 to 5 as a starter.', 'https://www.recipetineats.com/tachyon/2024/06/Ricotta-Gnocchi-51183.jpg', 20, 15, 30, 3, '[{"id": "ing_ricotta", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.175, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chardonnay", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.008, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8oz ricotta (, must be full fat (Note 1))","3/4 cup (75g) freshly grated parmesan cheese (Note 2)","1 large egg (55 - 60g/2oz)","1 egg yolk (egg white use ideas here)","1/4 tsp cooking salt / kosher salt","Pinch black pepper","3/4 - 1 cup flour (plain/all-purpose), plus more for dusting (Note 3)"],"purpose":"Gnocchi"},{"ingredients":["30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced )","1/2 onion or 1 eschallot ((US: shallot), finely chopped)","2 thyme sprigs (sub 1/2 tsp dried thyme)","250g / 8oz white mushrooms (, sliced in 5mm / 0.2\" slices)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/3 cup chardonnay (or other dry white wine (skip for non alcoholic))","1/2 cup chicken stock/broth (, low sodium)","2/3 cup thickened / heavy cream (or pure cream)"],"purpose":"Creamy mushroom sauce"},{"ingredients":["Freshly grated parmesan","Fresh parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Homemade ricotta gnocchi","images":[],"step":1},{"title":"Mix","description":"Put all the gnocchi ingredients in a bowl except the flour. Use a rubber spatula or wooden spoon to mix until combined (smear up the wall if needed, to help cream the ricotta).","images":[],"step":2},{"title":"Add flour","description":"Add 3/4 cup of flour and mix until just combined so it is a very sticky dough that will hold its shape in a mound, but is not runny like a muffin batter (see video for consistency). Stickier dough = softer gnocchi! Use the remaining flour, 1 tbsp at a time, if needed, but try to stick with 3/4 cup. You can always add more flour in the next step. (Note 3)","images":[],"step":3},{"title":"Form disc","description":"Sprinkle a work surface with flour then scrape the dough out onto it. Sprinkle the top lightly with flour then use your hands to give the dough a light knead to bring it into a ball then pat it into a disc about 2.5cm/1\" thick. Cut it into 8 wedges, using a knife or dough scraper dusted with flour as needed between each cut","images":[],"step":4},{"title":"Roll and cut","description":"Roll each piece into a log 25cm/10\" long, about 1.25cm / 1/2\" wide. Cut into 1.5 cm / 3/5\" pieces (Can freeze at this point - Note 4)","images":[],"step":5},{"description":"Creamy mushroom sauce","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in a large pan over high heat. Add the onion, garlic and thyme sprigs. Cook for 1 minute. Add mushrooms, salt and pepper. Cook for 5 minutes until the mushrooms is softened.","duration":1,"images":[],"step":7},{"title":"Sauce","description":"Add the wine and simmer rapidly for 1 to 2 minutes, stirring to scrape the base of the pan, until mostly evaporated. Add the stock/broth and cream, then stir.","duration":1.5,"images":[],"step":8},{"title":"Simmer","description":"Bring to a simmer then reduce the heat to medium low and simmer gently for 5 minutes until thickened. (It''s ok if it seems a bit thin, the starch from gnocchi will thicken it quickly, have faith!).","duration":5,"images":[],"step":9},{"description":"Cook gnocchi & sauce it","images":[],"step":10},{"title":"Cook gnocchi","description":"Bring a large pot of water to the boil with 2 teaspoons of salt. Tumble the gnocchi in and cook for around 2 1/2 minutes, or until the gnocchi is floating on the surface for around 30 seconds, no longer (else they overcook!)","images":[],"step":11},{"title":"Sauce it","description":"Use a spider or large slotted spoon to scoop the gnocchi out of the water and straight into the sauce (excess water drips in the sauce are good!). Turn the heat up to medium and toss gently for 1 minute or until the sauce thickens and coats the gnocchi. If the sauce gets too thick, add a splash of the gnocchi cooking water.","duration":1,"images":[],"step":12},{"description":"Serve immediately, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_990e1b1052c7', 'en', 'US', 'Sausage ragu with pappardelle pasta', 'Recipe video above. Take your meat sauce to the next level by using sausages instead of plain beef to make an incredible Sausage Ragu! Like Shredded Beef Ragu, cooking this sausage pasta sauce long and slow gives it time to develop deep, complex flavours. Complete your Italian feast with Garlic Bread, a garden salad with Italian Dressing and a beautiful Tiramisu.', 'https://www.recipetineats.com/tachyon/2016/02/Sausage-ragu_7.jpg', 20, 135, 155, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, finely minced)","1 carrot (, peeled and grated using a box grater (Note 1))","2 celery stalks (, grated using a box grater (Note 1))","1 tsp fennel seeds","350g / 12 oz pork sausages (, meat removed from casings (Note 2))","350g / 12 oz beef sausages (, meat removed from casings (Note 2))","2 tbsp tomato paste","1 cup pinot noir red wine (sub 0% alcohol red wine or more chicken stock)","1 cup chicken stock/broth (, low sodium)","400g/14 oz can crushed tomato","3 thyme sprigs (or 1/2 tsp dried)","2 bay leaves (fresh better, else dried)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 tsp chilli flakes ( (red pepper flakes), optional (for hint of heat))"],"purpose":"Sausage ragu:"},{"ingredients":["500g/ 1 lb pappardelle pasta (, or other pasta (80g/2.8oz per serving) (Note 3))","Parmesan or parmigiano reggiano (, finely grated, for serving)","Parsley (, finely chopped, optional garnish (just a pinch))"],"purpose":"To serve:"}]', '[{"description":"Preheat oven to 180°C (160°C fan-forced).","images":[],"step":1},{"title":"Soffrito","description":"Heat the oil in a large heavy based pot (with a lid) over medium heat. Add the onion, garlic, carrot, celery and fennel seeds. Cook for 8 minutes until the carrot is soft and sweet, but not golden.","duration":8,"images":[],"step":2},{"title":"Cook sausage","description":"Turn the heat up to high and add the sausage. Cook, breaking it up as you go, as best you can. It doesn''t crumble as well as mince/ground meat but that''s ok, we will break it up more later.","images":[],"step":3},{"title":"Deglaze","description":"Once the meat is no longer pink (it doesn''t really brown), add the tomato paste. Cook for 1 minute. Add the wine and let it simmer rapidly for 2 minutes until reduced by half, stirring regularly to scrape the base of the pot clean.","duration":1,"images":[],"step":4},{"title":"Slow cook #1 (1 hr)","description":"Add the remaining ragu ingredients. Stir, bring to a simmer, put the lid on and place it in the oven for 1 hour.","images":[],"step":5},{"title":"Slow cook #2 (45 min)","description":"Remove from the oven and use a potato masher to mash the meat finer. Put the lid back on, and return to the oven for 45 minutes. The sauce will be quite thick, it gets loosened when tossed with the pasta.","duration":45,"images":[],"step":6},{"title":"Salt","description":"Taste and add more salt if desired. (Sausages vary in saltiness so I always start with less)","images":[],"step":7},{"title":"Cook pasta","description":"Cook the pappardelle according to the packet instructions. Just before draining, scoop out 1 1/2 cups of the cooking water and set it aside.","images":[],"step":8},{"title":"Toss with sauce","description":"Have the ragu pot on the stove over medium heat. Add the pasta into the pot along with 1/2 cup of the pasta cook water. Use two spatulas to toss the pasta until the ragu is tangled in the pasta strands and it is stained red from the sauce. Use extra pasta cooking water if needed to loosen it up.","images":[],"step":9},{"description":"Serve in pre-warmed bowls, garnish with parmesan and a pinch of parsley if desired. Eat immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","main-dishes","most-popular","pasta-recipes","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10d82007651a', 'en', 'US', 'Spaghetti alla Puttanesca', 'Recipe video above. Spaghetti alla Puttanesca is a traditional Italian pasta from Naples with a sauce based on pantry essentials. This plants it firmly in the (excellent) emergency-meals collection!You don''t need much salt in Puttanesca sauce because the olives, capers and anchovies provide the seasoning. Don''t skip the anchovies - sauteeing it cooks out the fishy flavour and it just dissolves in the sauce, leaving behind savoury flavour you can''t get from just plain salt. You''d have to have a finely attuned palette to even know it''s in the sauce!', 'https://www.recipetineats.com/tachyon/2021/08/Spaghetti-Puttanesca_64-SQ.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pitted_black_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other long pasta)","2 tbsp extra virgin olive oil (, plus more for drizzling)","2 garlic cloves (, finely minced (knife, not garlic press))","3 anchovy fillets (, finely minced (Note 1))","1/4 cup pitted black olives (, preferably in oil, quartered (Note 2))","1 tbsp capers (, drained (Note 3))","1/4 tsp chilli flakes (red pepper flakes)","400g / 14oz can crushed tomato (or hand crush whole canned tomatoes)","1/2 cup water","1 tsp fresh oregano (, roughly chopped (sub 1/4 tsp dried))","1/8 tsp kosher / cooking salt (or 2 pinches table salt)","1/8 tsp black pepper","1/4 tsp sugar (, if needed (depends on tomato quality, Note 4))","2 tbsp fresh basil (, roughly chopped (Note 6))"]}]', '[{"title":"Prepare","description":"Bring a large pot of water to the boil, ready for the pasta. Warm serving bowls (I microwave 1 minute).","images":[],"step":1},{"title":"Cook garlic","description":"Heat olive oil in a medium skillet over medium high heat. Add garlic and cook for 15 seconds until it starts turning golden.","duration":0.25,"images":[],"step":2},{"title":"Cook anchovies","description":"Add anchovies, capers, olives and chilli flakes. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Tomato","description":"Add tomato, then add the 1/2 cup of water into the can. Swirl around to rinse then pour into the skillet.","images":[],"step":4},{"title":"Simmer","description":"Add oregano, salt and pepper. Stir, bring to simmer, then turn down to low and cook over medium heat for 10 minutes or until the tomato has broken down and created a sauce. Turn off stove when ready if not timed with cooked pasta.","duration":10,"images":[],"step":5},{"title":"Cook pasta","description":"Meanwhile, add 2 teaspoons salt into the pot of water. Then add pasta and cook per packet directions.","images":[],"step":6},{"title":"Reserve pasta water (Note 5)","description":"Just before draining, scoop out a mugful of pasta cooking water and set aside. Then drain pasta in a colander.","images":[],"step":7},{"title":"Toss pasta","description":"Immediately add pasta into sauce. Add 1/4 cup of pasta cooking water reserved from previous step (Note 5) then use 2 wooden spoons to toss the pasta, still on a low stove, for 1 minute or until the sauce is no longer in the skillet but rather clinging to the pasta strands (but still slick and slippery). If the pasta gets too dry, add more pasta cooking water and toss.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Immediately transfer into warmed bowls. Drizzle with olive oil, sprinkle with basil. Serve immediately!","images":[],"step":9}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37bb95f22138', 'en', 'US', 'Pasta alla Norma (Eggplant pasta)', 'Recipe video above. This is a traditional Italian pasta dish from Sicily, usually begun by cooking eggplant on the stove in a hefty amount of oil. I prefer roasting the eggplant - less oil plus the eggplant holds its shape better, especially when you roast at a high temp to caramelise the surface!Finishing with a good amount of fresh basil is traditional but even if you don''t have any, there''s other alternatives to add a touch of other flavour - such as fresh thyme, or extra dried herbs in the sauce.This is an excellent and satisfyingly "meaty" vegetarian main dish that will have even card-carrying carnivores asking for seconds!', 'https://www.recipetineats.com/tachyon/2020/11/Pasta-alla-norma-eggplant-pasta_6.jpg', 10, 45, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 66.667, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["800g / 1.6 lb eggplant (, cut into 2.5cm/1\" cubes (2 medium/large ones))","2 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"]},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1/2 small onion (, very finely chopped (or 2 eschallots))","1/4 cup dry white wine (, anything not too sweet or woody (Note 1))","700g / 24 oz tomato passata (aka tomato puree, Note 2)","1/4 cup water","1 tsp dried Italian herbs (or oregano)","1/2 tsp red pepper flakes (, optional (for a hint of heat))","1/2 tsp each salt and pepper","300g / 10 oz spaghetti or other pasta, long or short (macaroni, rigatoni, penne, ziti, fettucini, bucatini)"],"purpose":"Pasta Sauce:"},{"ingredients":["1/2 cup basil leaves (, roughly chopped (Note 3))","Parmesan cheese (, grated (or ricotta salata if you have it - more traditional))"],"purpose":"Serving:"}]', '[{"description":"Roasted eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with baking / parchment paper.","images":[],"step":2},{"description":"Toss eggplant with oil, salt and pepper. Spread on the tray and roast for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Flip, then roast for a further 5 minutes. Cool on tray (this helps the eggplant hold its shape when tossing).","images":[],"step":4},{"description":"Cooking pasta:","images":[],"step":5},{"description":"Bring a large pot of salted water to the boil. Start cooking the pasta a couple of minutes after you start making the sauce (next section), until al dente or to your liking.","images":[],"step":6},{"description":"Heat oil in a very large skillet over medium heat. Add garlic, cook for 20 seconds until golden, then add onion and cook for 2 to 3 minutes until translucent and cooked through.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Increase heat to medium-high and add wine, if using. Let it simmer, scraping the base of the pan to deglaze, until the wine mostly evaporates.","images":[],"step":8},{"description":"Add tomato passata. Now pour the water into the passata bottle, screw on the lid, shake, and pour that in too (waste nothing!)","images":[],"step":9},{"description":"Add dried herbs, red pepper flakes, salt and pepper. Stir and simmer 5 minutes.","images":[],"step":10},{"description":"Stir in eggplant, then add cooked and drained pasta. GENTLY toss until pasta is coated in the sauce (so the eggplant doesn''t turn into complete mush!).","images":[],"step":11},{"description":"Serve immediately, garnished with a good pinch of fresh basil and parmesan.","images":[],"step":12}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b53a0875c54', 'en', 'US', 'Creamy Garlic Prawn Pasta', 'Recipe VIDEO above. Pasta tossed with a garlic infused creamy sauce and plump, juicy prawns! (Shrimp) This pasta version of Creamy Garlic Prawns is a quick meal you''ll get on the table in 20 minutes, this is luscious but it''s not too rich. The key is to emulsify the sauce (i.e. thicken it) by tossing the pasta in the sauce just before serving - this is the proper Italian way to make pasta. Serves 4.', 'https://www.recipetineats.com/tachyon/2017/11/Creamy-Garlic-Prawn-Pasta-4.jpg', 5, 20, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 12.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 0.008, "unit": "carton of 250ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["12 oz / 350g fettuccine (, or other long strand pasta of choice)","50 g / 3 tbsp unsalted butter (, separated)","500 g / 1 lb small or medium peeled prawns / shrimp (, raw or 1kg / 2 lb whole unpeeled (Note 1))","4 garlic cloves (, finely minced with a knife)","1/2 cup Chardonnay or other dry white wine (Note 2 for sub)","1 1/4 cups heavy / thickened cream (or regular cream, pouring cream etc, full fat (Note 3))","1/2 cup chicken broth ((or fish or vegetable broth), preferably low sodium)","3/4 cup (75 g) finely grated parmesan cheese (freshly grated) (Note 4)","2 tbsp finely chopped parsley (, optional)","Black pepper","Parmesan (, for serving)"]}]', '[{"title":"Cook pasta","description":"Bring to boil a large pot of water. Add a big pinch of salt and the pasta, then cook per packet MINUS 1 minute - it will finish cooking in the sauce later so we want it slightly under. (Note 5).","images":[],"step":1},{"title":"Reserve water","description":"Just before draining, scoop out 1 cup of pasta cooking water and set aside, we need this to thicken the sauce later. Drain pasta.","images":[],"step":2},{"title":"Lightly cook prawns in 2 batches","description":"Meanwhile, melt about 1/3 of the butter in a large non stick skillet over medium high heat. Add half the prawns, spread out, and cook for 1 1/2 minutes, then turn and toss using 2 spatulas for another 1 - 1 1/2 minutes until just barely cooked (the prawns will cook more in the sauce). Remove prawns into a bowl. Repeat - add half the remaining butter, cook the remaining prawns then remove.","images":[],"step":3},{"title":"Sauté garlic","description":"In the same skillet, add the remaining butter. Once melted, add the garlic and stir for 20 seconds until fragrant (don''t let it burn, lower heat it needed).","duration":0.3333333333333333,"images":[],"step":4},{"title":"Deglaze","description":"Add wine and stir. Simmer rapidly for 2 minutes, scraping the pan to dissolve any bits stuck to it into the liquid, until wine mostly evaporates (see video).","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add cream, broth and parmesan. Stir until the parmesan is melted, then leave to simmer for 1 1/2 minutes until it thickens slightly - it will still be quite watery though which is fine, it will thicken more in next step.","images":[],"step":6},{"title":"Toss & thicken sauce","description":"Add prawns, pasta plus about 1/4 cup of reserved pasta water. Toss pasta energetically (still on stove on medium high) and in 1 to 2 minutes, the sauce will thicken and start clinging to the pasta. It will seem like nothing is happening at first but trust the process, it will happen! If you take it too far and the sauce gets too thick, add a small splash of remaining reserved pasta cooking water to loosen and toss again (you can do this repeatedly as needed).","images":[],"step":7},{"title":"Finish","description":"Add most of the parsley and a grind of black pepper, taste and check if you need salt (I don''t need more), then give it a quick toss.","images":[],"step":8},{"description":"Serve immediately, garnished with remaining parsley and parmesan if desired.","images":[],"step":9}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8833556f0dfa', 'en', 'US', '$2 Homemade Frozen Pizzas', 'VIDEO above. Stock your freezer with these quick homemade frozen pizzas! Made with store bought flatbreads, these thin and crispy pizzas are baked from frozen. Terrific economical standby meal, feel free to use your toppings of choice. Makes 10 pizzas, 25cm / 10" diameter.', 'https://www.recipetineats.com/tachyon/2017/10/Homemade-Frozen-Pizza_2.jpg', 20, 40, 60, 10, '[{"id": "ing_bread", "quantity": {"value": 10.0, "unit": "loaf"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 3.2, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 325.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["10 Greek pita bread (thick round flatbreads, 25cm / 10\" diameter) (Note 1)","250 g / 8 oz salami sliced (, chopped)","3/4 cup / 100 g sliced black olives (, drained)","1 large green capsicum / bell pepper (, sliced)","1 large red onion (, chopped)","15 medium mushrooms (, sliced (~golf ball size))","400 g / 14 oz / 4 cups shredded mozzarella cheese","300 - 350 g / 10 - 12 oz / 3.5 cups shredded Monterey Jack"]},{"ingredients":["1/4 cup / 65 ml extra virgin olive oil","3 garlic cloves (, minced)","800 g / 28 oz crushed canned tomato","2 tbsp tomato paste","1/2 cup / 125 ml water","1 tsp dried oregano","1 tsp dried thyme","1 tsp red chilli flakes (adjust to taste)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Easy Homemade Pizza Sauce (Note 3):"}]', '[{"description":"Heat olive oil in a large saucepan over medium heat. Add garlic and cook for 1 minute until fragrant. Add remaining ingredients, stir, and adjust heat so it is simmering gently (about medium heat). Cook down for 40 minutes, then puree with a stick (or cool a bit then transfer to blender).","duration":1,"images":[],"step":1},{"description":"COOL before using (hot sauce = soggy base). (Note 4)","images":[],"step":2},{"description":"Top a flatbread with 2.5 tbsp of Sauce. Sprinkle a tiny amount of cheese over the base, avoiding the very edges (glue for toppings - see video).","images":[],"step":3},{"description":"Sprinkle over onion, capsicum, salami, olives, mushrooms then cheese. Repeat with remaining flatbreads.","images":[],"step":4},{"description":"Stack them using paper in between each pizza. Wrap in groups of 3 or so (whatever you are comfortable handling). Transfer to a large airtight container or ziplock bag and freeze.","images":[],"step":5},{"description":"Remove oven shelf from oven and clean.","images":[],"step":6},{"description":"Preheat oven to 240C/460F (standard) / 220C / 430F (fan/convection).","images":[],"step":7},{"description":"Place frozen (or unfrozen freshly made) pizza directly on shelf. Bake for 10 minutes or until golden on the edges and the base is crispy.","duration":10,"images":[],"step":8},{"description":"Cut and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_212bae0c1c61', 'en', 'US', 'Sausage Pasta', 'A super quick meal made using chopped Italian Sausages that end up looking like mini meatballs! The sausages are the flavour base for this sauce, so get the best quality ones you can afford. Look for sausages where you can see little white chunks of fat and seasoning. Avoid the cheap sausages that are a uniform pink colour.', 'https://www.recipetineats.com/tachyon/2017/08/Sausage-Pasta-3.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.5, "unit": "bag of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["250 g / 0.5 lb spiral pasta (Note 1)","500 g / 1 lb good Italian sausages (, or other quality sausages of choice)","1 tbsp olive oil","1 small onion (, finely chopped)","2 garlic cloves (, minced)","800 g / 28 oz crushed tomato (or tomato passata)","1 tsp chilli flakes / red pepper flakes (adjust to taste)","Salt and pepper","1 - 2 big handfuls baby spinach (optional)"]},{"ingredients":["Basil leaves (, finely sliced)","Parmesan"],"purpose":"Garnish:"}]', '[{"description":"Bring a large pot of water to the boil. Cook pasta per packet directions MINUS 1 -2 minutes.","images":[],"step":1},{"description":"Just before you drain, RESERVE 1 cup of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Use a sharp knife to cut sausages into chunks about 1.5cm/3/5\". It will get a bit smeary and the chunks will be weird shapes - don''t worry, it self fixes while cooking!","images":[],"step":3},{"description":"Heat oil in a large skillet over high heat. Add sausages and cook until quite browned on the outside, doesn''t have to be cooked through inside.","images":[],"step":4},{"description":"Add onion and garlic, cook for 2 minutes until onion is translucent and sausages are very browned.","duration":2,"images":[],"step":5},{"description":"Add tomato, chilli flakes, pinch of salt and pepper. Mix and turn heat down to medium. Lets it bubble away energetically for 8 minutes or until it is quite thickened, stirring every now and then.","duration":8,"images":[],"step":6},{"description":"Add baby spinach (if using), pasta, and about 1/2 cup pasta cooking water. Toss quickly, no longer than 1 minute (otherwise the pasta may start to break).","images":[],"step":7},{"description":"Remove from stove, and serve immediately, garnished with plenty of basil and parmesan. Enjoy!","images":[],"step":8}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","readers-choice"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8ebe6852c899', 'en', 'US', 'Easy Pumpkin Gnocchi with Sage Butter Sauce', 'VIDEO ABOVE. This is a super easy way to make gnocchi and the secret ingredient is ricotta which keeps the gnocchi soft and pillowy inside. Much easier than the classic recipe made with potato. It tastes unbelievable - soft inside, touch of sweet, golden crisp surface and finished with a classic Sage Butter Sauce! Makes 2 very generous servings or 4 as a starter.', 'https://www.recipetineats.com/tachyon/2017/06/Pumpkin-Gnocchi-a.jpg', 20, 10, 30, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_ricotta", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sage", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["300 g /10oz fresh pumpkin (, steamed or boiled then mashed or 2/3 cup canned pumpkin puree)","1/2 cup ricotta (, full fat (Note 2))","1 1/4 cup plain flour ((all purpose flour), plus more for dusting)","1/3 cup parmesan cheese (, finely grated)","1 egg","1/4 tsp salt","Black pepper"],"purpose":"Gnocchi Dough"},{"ingredients":["1 tsp olive oil","50g / 3.5 tbsp butter (Note 3)","20 fresh sage leaves"],"purpose":"Sage Butter Sauce:"},{"ingredients":["Black pepper (and salt if needed)","Parmesan"],"purpose":"To serve:"}]', '[{"description":"Line a colander with 4 sheets of paper towel. Spread the fresh mashed pumpkin or canned puree onto the paper towel (see photo in post) then leave for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Measure out 1/2 cup of pumpkin puree (scale up if you scaled recipe, Note 6).","images":[],"step":2},{"description":"Place pumpkin and remaining Gnocchi ingredients in a bowl. Use a wooden spoon to mix well - it should be a soft dough. (Note 4)","images":[],"step":3},{"description":"Dust a work surface with flour, tip dough out, sprinkle with flour then pat into log shape.","images":[],"step":4},{"description":"Cut into 6 pieces. Roll into 1.7cm / 2/3\" ropes, then cut into squares (Note 5).","images":[],"step":5},{"title":"Optional","description":"Use a fork to press down lightly on the cut side of the gnocchi.","images":[],"step":6},{"description":"Cooking","images":[],"step":7},{"description":"Bring a large pot of water to the boil.","images":[],"step":8},{"description":"Scrape gnocchi onto parchment paper, then tip into water. Cook for 1 minute or until all the gnocchi rises to the surface (means it is cooked), then drain.","duration":1,"images":[],"step":9},{"description":"Meanwhile, melt about 1 teaspoon of the butter plus oil in a large skillet over medium high heat. Add gnocchi and cook, shaking the pan, until the gnocchi is just starting to turn brown (about 1 1/2 minutes).","images":[],"step":10},{"description":"Add remaining butter, once it melts, add sage leaves. Stir and cook for 2 1/2 minutes or until gnocchi is golden, sage is crisp and butter is slightly browned. Add salt if you used unsalted butter.","images":[],"step":11},{"description":"Serve immediately, garnished with parmesan and pepper.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian","Western"],"categories":["italian-recipes","pasta-recipes","pumpkin","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1fb717cccf92', 'en', 'US', 'Pan Fried Gnocchi with Pumpkin & Spinach', '{See video below} Soft fluffy gnocchi, pan fried in butter to create a beautiful golden crust then tossed with roasted pumpkin & spinach in a butter sauce. I use pumpkin to fill out this recipe because it has far less calories than gnocchi for the same weight and it adds a gorgeous flavour to this dish!', 'https://www.recipetineats.com/tachyon/2017/02/Gnocchi-with-Roasted-Pumpkin-Spinach.jpg', 15, 20, 35, 2, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_gnocchi", "quantity": {"value": 0.7, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_baby_spinach", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1lb pumpkin, cut into 2cm / 4/5\" pieces","1 tbsp olive oil","350g/12oz gnocchi, store bought (Note 1)","45g / 3 tbsp butter, salted (unsalted also ok, just add more salt)","1 garlic clove (large), minced","80g / 2.5oz baby spinach leaves","1/2 tsp fresh sage, finely sliced","Salt & pepper","Parmesan cheese, freshly grated"]}]', '[{"description":"Preheat oven to 200C/390F. Place pumpkin in a large bowl, drizzle with oil, sprinkle with salt and pepper. Toss to coat, spread out on tray and bake for 20 - 25 minutes, turning once, until golden and soft inside. Set aside.","duration":22.5,"images":[],"step":1},{"description":"Bring a large pot of water to the boil, add a good pinch of salt. Cook gnocchi according to packet directions, or until gnocchi pops to the surface of the water (see video). SCOOP OUT a large mug of cooking water, then drain gnocchi.","images":[],"step":2},{"description":"Place butter in a skillet then put on the stove over medium high heat. Once it foams, add gnocchi immediately. Stir, turn up the heat to high, then leave to cook for about 30 seconds.","images":[],"step":3},{"description":"Add garlic and sage, then stir / toss for no longer than 1 1/2 minutes (i.e. 2 minutes in total - see note 2) until gnocchi is golden on both sides.","images":[],"step":4},{"description":"Add about 3/4 cup of gnocchi cooking water and toss - the water will evaporate quickly and transform into a sauce.","images":[],"step":5},{"description":"Then add the pumpkin, spinach and about 1/4 cup of cooking water. Stir quickly , then season with salt and pepper. Toss then serve immediately with freshly grated parmesan.","images":[],"step":6}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","pumpkin","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfb38911c291', 'en', 'US', 'Poulet Rôti - French Roast Chicken', 'Recipe video above. You''ve been asking for a simple but delicious roast chicken? Say no more! You must try this French roast chicken. With a herbes de Provence butter tucked under its skin and cooked over potato chunks and whole cloves of garlic, this pot roast chicken will be the juiciest piece of meat you''ve had for a long time. So now it''s time to treat yourself! Say "Oui, oui!" to juicy chicken fragrant with herbs, confit garlic and melt in your mouth potatoes! Please make sure you don''t cut the potatoes too small else they will turn to mush before the chicken is cooked. Cut to the size I specify.', 'https://www.recipetineats.com/tachyon/2026/04/Poulet-Roti_6.jpg', 40, 70, 110, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4lb whole chicken (Note 1)","1 1/2 tsp herbes de Provence (, buy or make your own (Note 2))","3 thyme sprigs (, optional)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1 tbsp extra virgin olive oil"]},{"ingredients":["100g / 1 stick unsalted butter (, softened)","2 garlic cloves (, finely grated)","3 tsp herbes de Provence (Note 2)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)"],"purpose":"Herbs Butter"},{"ingredients":["750g / 1.65lb starchy potatoes","8 garlic cloves (, whole, unpeeled)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil"],"purpose":"Potatoes"}]', '[{"description":"Spread Herb Butter under chicken skin. Rub chicken with oil, salt inside and skin. Roast on potatoes and garlic – covered 30 minutes at 210°C / 410°F (190°C fan-forced), then 40 minutes uncovered, basting 3 times, or until the internal temperature reaches 72°C. Rest upright 15 minutes.","images":[],"step":1},{"description":"Preheat oven to 210°C / 410°F (190°C fan-forced). Place a 28cm cast-iron pot (no lid) in the oven to heat up.","images":[],"step":2},{"title":"Bring chicken to room temp","description":"Remove the chicken from the fridge and its packaging. Place it on a plate and let it sit on the counter while you prepare everything else. (Note 4)","images":[],"step":3},{"title":"Make herb butter","description":"In a small bowl, mix the softened butter with herbes de Provence, salt and finely grated garlic until well combined. Set aside.","images":[],"step":4},{"description":"Prepare Chicken and Potatoes","images":[],"step":5},{"description":"Pat the chicken completely dry with paper towels, including the skin and inside the cavity.","images":[],"step":6},{"title":"Loosen the skin","description":"From the tail end, gently slide an upside down spoon (not too large, dessert size is ideal for this) between the skin and the breast meat using slow sweeping motions to break membrane connecting them. After the breasts, use the same technique for the thighs and drumsticks. (Note 5)","images":[],"step":7},{"title":"Add butter under the skin","description":"Start with the breast, spoon 2/3 of the butter directly onto the meat under the skin and gently press on the outside of the skin with your hands to flatten and spread it all over evenly. Then divide the remaining butter between the two legs and spread it the same way. (Note 6)","images":[],"step":8},{"title":"Season and finish the chicken","description":"Season inside the cavity with 1/4 tsp salt, Herbs de Provence and thyme sprigs. Tie the drumsticks tightly together. Rub the whole chicken with olive oil and season the outside evenly with the remaining salt. Tuck the wings under and set aside on the counter.","images":[],"step":9},{"title":"Prepare potatoes","description":"Place potatoes, whole garlic cloves, salt, pepper and olive oil in a mixing bowl. Toss well to coat, then set aside.","images":[],"step":10},{"title":"Roast covered","description":"Carefully remove the hot pot from the oven. Place the potatoes at the bottom, then place the chicken on top. Cover loosely with foil and roast for 30 minutes. (Note 7)","duration":30,"images":[],"step":11},{"title":"Baste and continue roasting","description":"Remove the pot from the oven and take off the foil. Baste the chicken with the juices in the pot, moving the potatoes aside if needed to access the liquid (a spoon works fine, though a baster is perfect for this). Return to the oven and roast uncovered for 40 minutes, basting twice more until the internal temperature at the thigh joint reaches 72°C / 162°F (if slightly over, don’t stress, this one is very forgiving). (Note 8)","duration":40,"images":[],"step":12},{"title":"Rest (very important!)","description":"Lift and rest the chicken on its side in the pot, legs up, breast side down. Baste once more with the juices, then rest for 15 minutes. (Note 9)","duration":15,"images":[],"step":13},{"title":"Serve","description":"Carve the chicken (See video. Don''t forget the oysters, the small, very tender pieces of meat on the back near the thigh. There are only two, and they are the best bites. Easy to miss, so don’t forget them!) and serve with the potatoes, all the pan juices and a sprinkle of fresh thyme leaves. Enjoy! (Note 10)","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["jbs-recipes","main-dishes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_529970970327', 'en', 'US', 'Coquillettes au Jambon - French Macaroni and Cheese with Ham', 'Recipe Video above. A stovetop mac & cheese, that''s what this is really! Without the hassle of baking it! This dish was a big part of my childhood diet and even now but somehow never got sick of it. Who wouldn''t? Pasta, cheese sauce and ham. A great comfort meal, done fast and done right. Enjoy!', 'https://www.recipetineats.com/tachyon/2026/04/Coquilettes-au-jambon_0.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ham", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["500g / 1 lb elbow pasta / macaroni (, but any similar size pasta would work )","1 tsp cooking salt / kosher salt (, for pasta water, half for table salt)","200g / 7 oz ham slices (I use ham off-the-bone), diced 1cm / 0.4\" (Note 1)"]},{"ingredients":["75g / 5tbsp tbsp unsalted butter","1/2 cup plain flour / all-purpose flour","3 cups milk (, HOT, full fat preferred, but work with lite milk too)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","3/4 tsp black pepper","1/4 tsp ground nutmeg (, (Note 2))","1 1/2 cups Gruyère cheese, grated (, shredded using a standard box grater (tightly packed if using cups) (Note 3))","1/2 cup pasta cooking water"],"purpose":"CHEESE SAUCE (MORNAY SAUCE)"}]', '[{"description":"Cook pasta per packet directions, scoop out 1 cup of water just before draining. In the same pot, melt butter, cook flour 2 min. Whisk in milk. Add salt, pepper and nutmeg, stir in cheese until melted. Stir in ham, then 1/2 cup pasta cooking water. Toss with pasta until coated, serve.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water and salt to the boil. Cook pasta according to packet instructions. I always like to give a few stirs at the beginning so they don''t stick to each other.","images":[],"step":2},{"description":"Reserve 1 cup pasta cooking water, then drain and give the pasta brief rinse under cold water. Set aside and keep the pot for the sauce.","images":[],"step":3},{"title":"Make roux","description":"Using the pasta pot, melt the butter over medium heat. Add flour and whisk for 2 minutes. At first it will look like thick and pasty then it will loosen to become a smooth, glossy paste. Make sure to use the whisk to get into the corners of the pot and don’t let it brown, reduce heat if needed.","duration":2,"images":[],"step":4},{"title":"Adding milk","description":"Add half of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Once smooth, slowly pour in the remaining milk while continuing to whisk. Keep whisking for 30 seconds to 1 minute until the sauce is smooth, with no lumps. It should be thick enough that you can draw a path with a spatula through the middle, holding its shape briefly before slowly sinking back. (Note 4)","duration":0.5,"images":[],"step":5},{"title":"Season","description":"Add salt, pepper and nutmeg. Stir to combine.","images":[],"step":6},{"title":"Add cheese and ham","description":"Stir in Gruyère cheese and whisk until fully melted. You just made a Mornay sauce! Then stir in the ham with a wooden spoon.","images":[],"step":7},{"title":"Finish sauce","description":"Pour in 1/2 cup of the reserved pasta cooking water and stir until silky. Bring back to a simmer. It will be quite runny, it will thicken when the pasta is added.","images":[],"step":8},{"title":"Combine","description":"Add drained pasta and stir well until fully coated, the sauce will thicken slightly and cling to the macaroni. Add more pasta water if the sauce gets too thick.","images":[],"step":9},{"description":"Serve immediately while hot and creamy. I like to grind extra black pepper on top just before eating. Enjoy!","images":[],"step":10}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["jbs-recipes","main-dishes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c6b1fa7c0de', 'en', 'US', 'JB''s Mushroom Tart', 'Recipe video above. This is a simple mushroom tart that I used to make for my family back in France. Called "Tarte Fine aux Champignons" in French, buttery puff pastry is topped with melted Gruyère, sautéed mushrooms and baked until crispy and golden. It''s simple but delicious as a light meal with a fresh salad on the side.You''ll probably be surprised by the volume of mushrooms once sliced but it will reduce significantly as it cooks and bakes to an even layer on the puff.', 'https://www.recipetineats.com/tachyon/2026/03/JB-Mushroom-Tart_1.jpg', 20, 30, 50, 4, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["1 square sheet butter puff pastry (25cm / 10″ square), barely thawed (Note 1)","1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","400g / 14oz Swiss brown mushrooms (, sliced 0.5cm (Note 3))","1/2 tsp cooking salt / kosher salt (, use half for table salt)","1/4 tsp black pepper","1 1/2 cups (tightly packed) Gruyère cheese (, grated (Note 2))","2 tsp (10g) unsalted butter (, melted (for brushing))"]},{"ingredients":["1 1/2 tsp fresh thyme leaves","1 pinch sea salt flakes","truffle oil or good extra virgin olive oil (, to drizzle (optional) (Note 4))"],"purpose":"Toppings"}]', '[{"description":"Sauté mushrooms 5 minutes. Place puff pastry on baking paper, fold a 1 cm / 0.4\" border, brush edges with butter, top with Gruyère and mushrooms. Bake on the preheated tray for 30 minutes. Finish with fresh thyme, salt flakes and truffle oil.","duration":30,"images":[],"step":1},{"title":"Hot tray","description":"Place a baking tray in the oven. Turn the oven on and preheat to 210°C / 410°F (190°C fan).","images":[],"step":2},{"title":"Cook the mushrooms","description":"Heat the olive oil and butter in a frying pan over medium-high heat. Add mushrooms, salt and pepper. Cook for 5 minutes, stirring regularly, until soft. Transfer mushrooms to a colander over a bowl to drain in case of excess liquid.","duration":5,"images":[],"step":3},{"title":"Prepare the base","description":"Place a sheet of baking paper / parchment paper on the bench. Put the puff pastry on top. Fold the edges inwards to create a 1 cm / 0.4″ border and brush them with melted butter.","images":[],"step":4},{"title":"Assemble","description":"Spread the grated Gruyère evenly over the pastry. Top with the mushrooms, spreading them evenly too.","images":[],"step":5},{"title":"Bake","description":"Lift the baking paper and tart onto the hot tray in the oven. Bake for 30 minutes, until the pastry is golden and crisp (sides and underneath).","duration":30,"images":[],"step":6},{"title":"Finish and serve","description":"Sprinkle with fresh thyme leaves and salt flakes. Drizzle with truffle oil or a good virgin olive oil (optional but highly recommended). Cut and serve hot.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch","dinner","snack"],"cuisine":["French"],"categories":["jbs-recipes","mushroom-recipes","mushrooms","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7a064c388856', 'en', 'US', 'JB''s French Pork Schnitzel', 'People say adding “French” to something doesn’t mean it’s better. But my passport would like to disagree! These schnitzels get a French flair with Herbes de Provence in the breadcrumbs. Now they''re French Pork Schnitzels - escalope de porc panées. Let’s go!', 'https://www.recipetineats.com/tachyon/2026/03/French-pork-schnitzel-1.jpg', 25, 10, 35, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_marjoram", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["4 pork steaks or chops (125g to 150g / 4.4oz to 5.3oz each) (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper"]},{"ingredients":["1/3 cup plain flour / all-purpose flour","2 eggs, lightly whisked (, from large eggs (55g / 2oz each in shell))","1 1/2 cup panko breadcrumbs (Note 2)","3 tbsp herbes de Provence (Note 3)","1/2 cup vegetable oil (, or any other neutral flavoured oil)"],"purpose":"CRUMBING AND COOKING:"},{"ingredients":["1 lemon, cut into wedges","sea salt flakes"],"purpose":"TO FINISH:"},{"ingredients":["4 tsp dried thyme","3 tsp dried rosemary (Note 4)","1 1/4 tsp dried marjoram or savory (, sub with more thyme or rosemary)","3/4 tsp dried oregano"],"purpose":"HERBES DE PROVENCE:"}]', '[{"description":"Pound pork to 0.5cm / 0.2″, season with salt and pepper. Coat in flour, egg, then panko mixed with herbes de Provence. Fry over medium-high heat 2 minutes per side until golden.","images":[],"step":1},{"description":"Preheat the oven to 70°C / 160°F (all ovens).","images":[],"step":2},{"title":"Pound the pork","description":"Place the pork between two sheets of baking paper / parchment paper or freezer bags. (Note 5) Pound with a meat mallet until evenly 0.5 cm / 0.2 inch thick. (Note 6)","images":[],"step":3},{"title":"Season","description":"Season both sides with salt and pepper. Set aside.","images":[],"step":4},{"title":"Prepare the crumbing station","description":"Place flour, eggs, and panko mixed with herbes de Provence in three separate bowls. (Note 7)","images":[],"step":5},{"title":"Crumb","description":"Coat pork in flour and shake off excess. Dip in egg and let excess drip off. Press into the breadcrumb mixture so it sticks well. Transfer on a tray and repeat with remaining pork.","images":[],"step":6},{"title":"Cook the schnitzels","description":"Heat the oil in a frying pan over medium-high heat, it should be 0.4cm / 0.15\" deep. When hot, add 2 schnitzels. Cook 2 minutes until golden. Flip and cook the other side 2 minutes. Transfer to a rack over a tray and place in the warm oven. Repeat with the remaining two schnitzels. (Note 8)","images":[],"step":7},{"title":"Rest and Serve","description":"Let the schnitzels rest on the rack outside of the oven for 2 minutes before serving with a wedge of lemon and a sprinkle of salt flakes.","duration":2,"images":[],"step":8}]', '["egg","gluten"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","French influence"],"categories":["jbs-recipes","mains","pork","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea459fbbf11b', 'en', 'US', 'Lamb tagine', 'Recipe video above. My favourite of all tagines! The ras el hanout spice mix is sheer perfection with lamb, and slow cooking works wonders to develop rich flavours in the sauce and make the lamb fork tender. Serve over couscous for a stunning Moroccan meal. Your house will smell amazing!-> Also see Chicken and Vegetable Tagine.', 'https://www.recipetineats.com/tachyon/2023/08/Lamb-tagine_4.jpg', 15, 120, 135, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.18, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_apricots", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.5, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.025, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 1.0, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_batches_couscous", "quantity": {"value": 1.5, "unit": "pack"}}]', '[{"ingredients":["1.6 kg/ 3.2lb boneless lamb shoulder, trim the fat, then ( cut in 3.5cm / 1.5\" cubes (1kg/2lb after trimming))","1 kg / 2 lb lamb stewing meat or shoulder, already trimmed of fat (cut in 3.5cm / 1.5\" cubes)"],"purpose":"Use one of these lambs (Note 1):"},{"ingredients":["1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tbsp canola oil","3 garlic cloves (, finely minced)","2 brown onions (, diced (1cm / 0.3\" cubes))","1 1/2 tbsp tomato paste","2 tsp grated ginger","2 cinnamon sticks","2 1/2 cups chicken stock/broth (, low sodium)","1 cup dried apricots (, whole (Note 2 for olives option))","2 - 3 tsp lemon zest (just use 1 whole lemon, Note 3 for preserved lemon)"],"purpose":"Tagine:"},{"ingredients":["1 tbsp ground coriander","1 tbsp ground cumin","2 tsp ground cardamom","2 tsp turmeric powder","1 1/2 tsp fennel powder","1 tsp cayenne pepper (can reduce for less spicy - Note 4)","1/4 tsp ground cloves","1/4 tsp ground ginger","1/2 tsp cooking/kosher salt"],"purpose":"Ras el hanout (Note 4):"},{"ingredients":["1/2 cup slivered almonds (, toasted (Note 5))","1/2 cup coriander/cilantro leaves roughly chopped","1 1/2 batches couscous (I just use plain, but you can add the fruit and nuts if you want)"],"purpose":"For serving:"}]', '[{"description":"Preheat oven to 180°F/350°F (160°C fan). (Note 6 re: other cook methods)","images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a bowl then set aside.","images":[],"step":2},{"title":"Brown lamb","description":"Toss lamb with the salt and pepper. Heat the oil in a large oven-proof dutch oven (with a lid) over high heat. Brown the lamb in 3 batches, turning to colour the pieces all over, about 3 minutes. Remove into a bowl, then repeat with remaining lamb. Set aside.","images":[],"step":3},{"title":"Aromatics","description":"Turn heat down to medium high. Add onion and garlic, cook for 3 minutes until soft. Add tomato paste, ginger, cinnamon and spice mix. Cook for 1 1/2 minutes, stirring constantly.","duration":3,"images":[],"step":4},{"title":"Sauce","description":"Add chicken stock and water, stir, then return the lamb into the pot.","images":[],"step":5},{"title":"Slow cook 1 hr 45 min","description":"Bring to a simmer, cover with a lid then cook in the oven for 45 minutes. Add apricots, put the lid back on and cook for another 1 hour, checking halfway to ensure the sauce hasn''t reduced all the way (if you''re concerned, add 1/2 cup water).","duration":45,"images":[],"step":6},{"title":"Lemon finish","description":"Lamb should be tender - check! Gently stir in lemon zest.","images":[],"step":7},{"description":"Serve over plain couscous, sprinkled with almonds and coriander.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Moroccan","North African"],"categories":["lamb","lamb-recipes","mains","moroccan","slow-cooked-fall-apart","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce03cd624a01', 'en', 'US', 'Persian Lamb Shanks', 'Recipe video above. A traditional Persian dish - fall apart lamb shanks with a well seasoned, delicately flavoured broth. Pair this with the iconic Persian Tachin (baked saffron rice), a Persian chopped salad and finish with a Persian Love Cake to complete your Persian feast!', 'https://www.recipetineats.com/tachyon/2018/09/Persian-Lamb-Shanks_6.jpg', 10, 180, 190, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 6.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 500.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_saffron_threads", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["4 lamb shanks (, about 300g/10oz each (Note 1))","Salt and pepper","1 - 2 tbsp vegetable oil (or canola)","1 large onion (, sliced (yellow, brown))","6 cloves garlic (, chopped)","1 litre / 4 cups water","500 ml / 2 cups chicken broth","2 medium tomatoes (, chopped)"]},{"ingredients":["1 tsp turmeric","3/4 tsp salt","1/4 tsp + 1/8 tsp nutmeg","1/4 tsp + 1/8 tsp cardamom powder","1/2 tsp cinnamon","1/8 tsp extra cinnamon (, extra for later)","1/4 tsp saffron threads (Note 2)"],"purpose":"Spices:"}]', '[{"description":"Sprinkle shanks with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Brown shanks all over, 2 at a time. Remove from pot.","images":[],"step":2},{"description":"Discard excess oil, clean pot if it''s very dirty.","images":[],"step":3},{"description":"Add 1 tbsp oil. Cook onion and garlic for 2 minutes until translucent.","duration":2,"images":[],"step":4},{"description":"Stir in the turmeric, cinnamon, tomatoes, and salt.","images":[],"step":5},{"description":"Add chicken broth and stir well.","images":[],"step":6},{"description":"Place shanks in pot, then add water as needed so the shanks are 3/4 or fully covered, but no more than 1L/4 cups water. (Note 2)","images":[],"step":7},{"description":"If shanks not fully submerged, make a cartouche (baking paper lid, Note 3).","images":[],"step":8},{"description":"Bring up to the boil. Place the cartouche snugly on surface (if using), cover pot leaving a little crack (to ensure it doesn''t boil over).","images":[],"step":9},{"description":"Turn heat down so simmering very gently. Cook 1.5 hours, turning every 30 minutes.","images":[],"step":10},{"description":"Add cardamom and nutmeg into liquid.","images":[],"step":11},{"description":"Cook for another 1 hour until meat is very tender and falling off the bone.","images":[],"step":12},{"description":"Carefully remove meat from liquid into a bowl and cover with foil.","images":[],"step":13},{"title":"Simmer broth rapidly 30","description":"45 min until reduced by half.","images":[],"step":14},{"description":"Add saffron and remaining 1/8 tsp cinnamon.","images":[],"step":15},{"title":"Simmer further 10","description":"15 min until reduced to 500 ml / 2 cups. Should taste like a very well seasoned, intensely savoury but lightly spiced broth.","images":[],"step":16},{"description":"Return meat to pot to gently reheat for a few minutes, turning and basting the meat with the liquid to keep it moist.","images":[],"step":17},{"description":"Serve shanks with the braising liquid as a sauce. Pictured garnished with pomegranate seeds (leftover from salad, see Notes) or mint leaves, for visual only.","images":[],"step":18}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Persian"],"categories":["lamb","lamb-recipes","lamb-shanks","main-dishes","mains","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c94806c67199', 'en', 'US', 'Shepherd''s Pie', 'Recipe video above. Shepherd’s Pie is one of those foods that brings a smile to everyone’s face – especially when you get seconds! While it''s traditionally made with lamb, this is equally delicious made with beef (and makes it a Cottage Pie!) Terrific make ahead! GF option in Note 4.', 'https://www.recipetineats.com/tachyon/2018/06/Shepherds-Pie_1.jpg', 10, 70, 80, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped)","1 rib celery (, finely chopped)","3/4 tsp each dried thyme and rosemary (or 2 sprigs fresh thyme + 1 sprig rosemary)","750g (1.5 lb) ground lamb (mince) OR beef","1/4 cup flour (, plain/all purpose)","1/4 cup tomato paste","2 cups beef stock / broth","1/2 cup red wine (or water)","1 beef bouillon cube (, crumbled (OXO brand crumbles easily))","1 tbsp Worcestershire sauce","2 bay leaves (, dried or fresh)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","1 cup frozen peas"]},{"ingredients":["1.2kg (2.2 lb) potatoes, peeled and cut into 2.5cm / 1\" cubes","2/3 cup milk (whole or low fat)","2 tbsp (30g) unsalted butter"],"purpose":"Mashed Potato"},{"ingredients":["2 – 3 tbsp grated parmesan (, optional)","2 tbsp (30g) unsalted butter (, melted)","Fresh thyme leaves, optional garnish"],"purpose":"Cheesy crust"}]', '[{"title":"Sauté","description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots, celery, thyme and rosemary. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"title":"Cook lamb","description":"Turn heat up to high. Add lamb and cook, breaking it up as you go, until browned.","images":[],"step":2},{"title":"Make sauce","description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce and bay leaves. Stir well.","images":[],"step":3},{"title":"Simmer and thicken","description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium. Cook for 30 minutes, stirring occasionally, until it reduces down to a thick gravy consistency (Note 1) (see video).","duration":30,"images":[],"step":4},{"title":"Cool","description":"Add salt and pepper, taste, then add more if you like. Transfer Filling to 1.5 litre / 1.5 quart pie baking dish. Stir through peas. Cover, then refrigerate to cool for 1 - 2 hours or overnight (optional, Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F (both fan and standard).","images":[],"step":6},{"title":"Boil potatoes","description":"Place the potatoes in a large pot. Add water so it’s 10cm / 4” above potatoes. Bring to a boil then cook for 15 minutes or until soft. Drain then return potatoes into the pot on the turned off stove. Allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"title":"Mash","description":"Add butter and mash until melted, then add milk, salt and pepper. Mash until it''s soft and smooth (ie spreadable, but not sloppy), adjusting with a touch more milk if required.","images":[],"step":8},{"description":"Spread mash onto pie, use a fork to draw squiggles over the surface. Sprinkle with parmesan, drizzle with butter.","images":[],"step":9},{"title":"Bake for 30","description":"40 minutes or until deep golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":35,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","British","Western"],"categories":["lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_270e2df1a054', 'en', 'US', 'Lamb Shanks in Red Wine Sauce', 'Recipe video above. A classic way to prepare shanks, these are slow cooked in a deeply flavoured red wine sauce until they are meltingly tender. You can''t taste the red wine at the end, it completely transforms into a rich sauce. Make this in the oven, on your stove or even in a slow cooker - instructions provided for all!Note: This is my original lamb shanks recipe. There is also a more involved Restaurant-style red wine lamb shanks version in my cookbook which is more "fine-dining" style and involves an overnight marinade. See Note 7 for more information!', 'https://www.recipetineats.com/tachyon/2022/07/Lamb-Shanks-Red-Wine-Sauce_2_900px.jpg', 20, 210, 230, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 0.4, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 3.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 5.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, around 13 oz / 400g each (Note 1))","1 tsp EACH cooking/kosher salt and pepper","2 - 3 tbsp olive oil (, separated)","1 onion (, finely diced (brown, yellow or white))","3 garlic cloves (, minced)","1 cup carrot (, peeled, finely diced (Note 2))","1 cup celery (, finely diced (Note 2))","2 1/2 cups red wine (full bodied (good value wine, not expensive! Note 3)","800 g / 28oz can crushed tomatoes","2 tbsp tomato paste","2 cups chicken stock (, low sodium (or water))","5 sprigs of thyme ((preferably tied together), or 2 tsp dried thyme)","2 dried bay leaves (or 4 fresh)"]},{"ingredients":["Mashed potato (, polenta or pureed cauliflower)","Fresh thyme leaves (, optional garnish)"],"purpose":"To Serve:"}]', '[{"title":"Preheat the oven to 180°C/350°F (all oven types","description":"fan and standard).","images":[],"step":1},{"title":"Season shanks","description":"Pat the lamb shanks dry and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat 2 tablespoons of olive oil in a large heavy based pot over high heat. Sear the lamb shanks in 2 batches until brown all over, about 5 minutes. Remove lamb onto a plate and drain excess fat (if any) from the pot.","images":[],"step":3},{"title":"Sauté aromatics","description":"Turn the heat down to medium low. Heat remaining 1 tablespoon of olive oil in the same pot. Add the onion and garlic, cook for 2 minutes. Add carrot and celery. Cook for 5 minutes until onion is translucent and sweet.","duration":2,"images":[],"step":4},{"title":"Braising liquid","description":"Add the red wine, chicken stock, crushed tomato, tomato paste, thyme and bay leaves. Stir to combine.","images":[],"step":5},{"title":"Add shanks","description":"Place the lamb shanks into the pot, squeezing them in to fit so they are mostly submerged. (Note 1)","images":[],"step":6},{"title":"Oven 2 hours covered","description":"Turn stove up, bring liquid to a simmer. Cover, then transfer to the oven for 2 hours (see notes for other cook methods).","images":[],"step":7},{"title":"Uncovered 30 minutes","description":"Remove lid, then return to the oven for another 30 minutes (so 2 1/2 hours in total). Check to ensure lamb meat is ultra tender - if not, cover and keep cooking. Ideal is tender meat but still just holding onto bone.","images":[],"step":8},{"description":"Remove lamb onto plate and keep warm. Pick out and discard bay leaves and thyme.","images":[],"step":9},{"title":"Sauce","description":"Strain the sauce into a bowl, pressing to extract all sauce out of the veggies (Note 5 for repurposing the veggies). Pour strained sauce back into pot. If needed, bring to a simmer over medium heat and reduce slightly to a syrupy consistency (see video) - I rarely need to. Taste then add salt and pepper to taste (Note 5 on sauce taste).","images":[],"step":10},{"description":"Serve the lamb shanks on mashed potato or cauliflower puree with plenty of sauce! Garnish with thyme leaves if desired.","images":[],"step":11}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["lamb-recipes","lamb-shanks","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fee8e66fd88d', 'en', 'US', 'Pea and Ham Soup (slow cooker or stove)', 'Recipe video above. This is a fabulous "throw it all in the slow cooker" soup. There''s no need to cook the onion separately - it "sautés" itself in the fat from the ham that rises to the surface. Thick, hearty soup broth infused with incredible flavour from the ham! Use leftover ham bone, or purchase a ham hock.', 'https://www.recipetineats.com/tachyon/2020/02/Pea-and-Ham-Soup_4.jpg', 10, 600, 610, 6, '[{"id": "ing_split_peas", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_bacon", "quantity": {"value": 1.35, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb dried split peas (Note 1)","1.2-1.5kg / 2.4-3lb ham hock (aka ham bone), bacon hock or MEATY leftover ham bone (Note 2)","1/4 tsp salt (start with less, adjust later)","3/4 tsp black pepper","2 garlic cloves (, minced)","2 bay leaves (, dried or fresh)","1 onion (, finely chopped)","1 carrot (, peeled and finely chopped)","2 celery sticks (, finely chopped)","8 cups (2 litres/qts) water"]},{"ingredients":["Parsley (, finely chopped)","Crusty bread for dunking!"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place peas in slow cooker, push ham in. Scatter all ingredients around the ham bone, then pour over water.","images":[],"step":1},{"description":"Slow cook 8 to 10 hours on LOW or 6 hours on HIGH. (Or 2.5 hours on low on stove, 1 h - 1 hr 20 min pressure cooker/Instant Pot on HIGH)","images":[],"step":2},{"description":"Remove ham bone, shred ham meat. Discard bone and fatty skin.","images":[],"step":3},{"description":"Remove bay leaves. Use a stick blender to blitz 2 or 3 times - thickens soup but doesn''t make it completely smooth (my preference, you can blend completely if you want).","images":[],"step":4},{"description":"Return ham into slow cooker, stir. Taste and add more salt if needed (soup gets lots of salt from ham).","images":[],"step":5},{"description":"Serve garnished with parsley. Serve with crusty bread for dunking - make a quick Irish Soda Bread, Garlic Bread or upgrade to Cheesy Garlic Bread!","images":[],"step":6}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["leftover-ham-recipes","slow-cooker-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a15d7af93bb', 'en', 'US', 'Bangers & Mash (Sausage with Onion Gravy)', 'Recipe video above. Everybody loves a good sausage recipe, and this is the great British classic! Affectionately known as "Bangers and Mash" to Aussies and Brits, this is so easy to make, you will never ever use a store bought gravy powder!', 'https://www.recipetineats.com/tachyon/2016/10/Bangers-and-Mash-with-Onion-Gravy_42.jpg', 5, 20, 25, 4, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 tbsp oil","8 sausages of choice (Note 1)","1 large onion (, halved and finely sliced (yellow, white or brown) (Note 2))","2 garlic cloves (, minced)","3 tbsp flour (plain)","2 cups beef stock/broth","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["Mashed potato","Peas"],"purpose":"To Serve"}]', '[{"title":"Cook sausages","description":"Heat oil in a large skillet / fry pan over medium high heat. Add sausages and cook, turning, until browned as much as possible all over and cooked through. Cook time will differ depending on sausage size - mine take around 8 minutes.","images":[],"step":1},{"description":"Remove sausages onto a plate. Turn heat down to medium.","images":[],"step":2},{"title":"2 tbsp oil remaining","description":"You need around 2 tbsp oil left in the skillet. If you have much less, add a bit of butter or oil.","images":[],"step":3},{"title":"Saute onion and garlic","description":"Add onion and garlic, cook until golden brown - around 4 minutes.","images":[],"step":4},{"title":"Cook off flour 2 minutes","description":"Add flour and mix through. Then cook, stirring constantly for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Gradually add beef stock","description":"Add about 3/4 cup of beef broth and mix into the onion so it becomes a sludge. Then add remaining beef broth and mix until combined. If it''s lumpy, use a whisk to help make it smooth.","images":[],"step":6},{"title":"Thicken gravy","description":"Simmer, stirring, for 2 to 3 minutes until the gravy thickens but is slightly thinner than you want - it will thicken more as you serve it.","duration":2.5,"images":[],"step":7},{"title":"Season","description":"Add salt and pepper. Stir, taste, then add more salt if you want.","images":[],"step":8},{"description":"Serve sausages with plenty of gravy, with mashed potato and peas on the side. (Low carb option - Creamy Cauliflower Mash)","images":[],"step":9}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Australian","British"],"categories":["dinner-tonight","main-dishes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dea186d5023f', 'en', 'US', 'Pasta with Creamy Zucchini Sauce', 'Recipe video above. This is a wonderful way to use zucchinis to make a luscious pasta dinner! It''s summery yet at the same time comforting, quick, easy and while perhaps not low fat, this makes a good dent into our daily recommended vegetable intake!', 'https://www.recipetineats.com/tachyon/2020/07/Creamy-Zucchini-Pasta-Sauce_8.jpg', 10, 15, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 4.0, "unit": "pack of 200g"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["50g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 onion (, finely sliced (brown, white, yellow))","600g / 1.2 lb zucchini ((courgette), grated using standard box grater)","1/2 tsp EACH salt and pepper","1 cup thickened/heavy cream","3/4 cup chicken or vegetable stock/broth (, low sodium)","3/4 cup parmesan (, finely grated using microplane (Note 1 for store bought))","1 cup corn (canned, drained, about 2/3 of a can, OR fresh)","300g/ 10oz spaghetti, fettucini or other long strand pasta ( (I used bucatini))"]},{"ingredients":["Parmesan","Extra finishing options: Handful of fresh basil (stir in at end), sprinkle of bacon or pangrattato"],"purpose":"Finishing & serving"}]', '[{"description":"Cook Pasta:","images":[],"step":1},{"description":"Bring a large pot of water to the boil with 1 tablespoon of salt.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 2 minutes (yes, 2 whole minutes!) - pasta should be a bit too firm in the middle.","images":[],"step":3},{"description":"Scoop out a big mug of pasta cook water, set aside (for sauce loosening, just in case), then drain.","images":[],"step":4},{"description":"Creamy zucchini sauce:","images":[],"step":5},{"description":"Melt butter in a large skillet or pot over medium high heat.","images":[],"step":6},{"title":"Garlic and onion","description":"Add garlic and onion, cook for 1 1/2 minutes until onion is slightly golden.","images":[],"step":7},{"title":"Cook Zucchini","description":"Add zucchini, cook for 1 minute. Then add salt and pepper, then stir for 2 minutes until it reduces in volume by about 1/2.","duration":1,"images":[],"step":8},{"title":"Add liquids","description":"Stir in cream, chicken stock, parmesan and corn. Bring to simmer, then reduce heat to medium and simmer for 3 minutes. It will still seem watery because water comes out of the zucchini - don''t worry, it cooks down in the next step.","duration":3,"images":[],"step":9},{"description":"Toss! Add pasta, then use two wooden spoons to toss well for 2 minutes, or until sauce reduces and is coating the pasta instead of pooling in the skillet. If it gets too thick, add a splash of reserved pasta cooking water. Pasta will finish cooking in this step.","duration":2,"images":[],"step":10},{"title":"Serve","description":"Remove from stove, serve immediately, garnished with extra parmesan.","images":[],"step":11}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["main-dishes","mains","pasta-recipes","quick-and-easy","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_744dcc5f1955', 'en', 'US', 'Crispy Baked Shrimp in Lemon Butter Sauce (Prawns)', 'Recipe video above. People call this Magic Baked Shrimp - named as such because it''s so simple to make, yet it tastes like a million bucks! Shrimp (prawns) baked in a white wine-butter reduction with lemon and garlic, with a crunchy parmesan breadcrumb topping! Don''t skip crust bread for dunking in the incredible sauce! It''s basically a crunchy version of Shrimp Scampi!', 'https://www.recipetineats.com/tachyon/2019/08/Baked-Shrimp-Prawns_6.jpg', 10, 15, 25, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 3.0, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb jumbo prawns/shrimp (, peeled and deveined (Note 1))","3/4 cup dry white wine (sub chicken broth)","75g/ 5 tbsp unsalted butter (, melted)","2 tbsp lemon juice","3 garlic cloves (, minced)","1/2 tsp salt","1/4 tsp pepper"]},{"ingredients":["3/4 cup panko breadcrumbs (Note 2)","1/4 cup parmesan (, finely shredded)","1/4 tsp salt","1.5 tbsp olive oil"],"purpose":"Crunchy Topping:"},{"ingredients":["Finely chopped parsley","Lemon"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/430°F (all oven types).","images":[],"step":1},{"description":"Pour wine and half the butter into 9 x 13\" / 22 x 33cm baking pan (see Note 3 if using glass). Place in oven for 10 minutes to reduce.","duration":10,"images":[],"step":2},{"description":"Toss prawns with remaining butter, garlic, lemon juice, salt and pepper. Butter may harden - that''s ok.","images":[],"step":3},{"description":"Mix Crunchy Topping ingredients.","images":[],"step":4},{"title":"Remove pan from oven. Add prawns","description":"spread out in single layer, but snug.","images":[],"step":5},{"description":"Top with Crunchy Topping. Bake 12 minutes.","images":[],"step":6},{"title":"Flick to broiler/grill on high, broil for 1","description":"2 minutes (max) to brown top a bit more.","duration":1.5,"images":[],"step":7},{"description":"Sprinkle with parsley. Serve immediately with lemon wedges and crusty bread to mop up the incredible sauce!","images":[],"step":8}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e061b94dd4f', 'en', 'US', 'Garlic Herb Slow Cooker Turkey Breast', 'Recipe video above. Slather your turkey breast with garlic herb butter so it bastes with flavour and keeps the breast moist as it cooks in the slow cooker. Slow cooker is the easiest, safest way too cook turkey breast without brining or marinating! See here for the roasted version of this recipe. Also see the classic spice rubbed Juicy Slow Cooker Turkey Breast.', 'https://www.recipetineats.com/tachyon/2018/11/Slow-Cooker-Garlic-Herb-Turkey-Breast.jpg', 15, 360, 375, 8, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1 1/2 tsp salt","Black pepper","1 brown onion (, halved)","1 head of garlic (, halved horizontally)","3 sprigs rosemary, 8 sprigs thyme (optional)","Oil (, for drizzling (for skin))"]},{"ingredients":["150 g / 10 tbsp unsalted butter (, softened)","1 1/2 tsp salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp EACH finely chopped fresh sage, rosemary leaves, thyme leaves and parsley (, fresh)"],"purpose":"Garlic Herb Butter (Note 2):"},{"ingredients":["Chicken broth/stock, for topping up (if required)","1/3 cup / 50g flour","1/2 tsp + dark soy sauce (or gravy colouring) (Note 3)"],"purpose":"Garlic Butter Gravy:"}]', '[{"title":"Garlic Herb Butter","description":"Mix ingredients together.","images":[],"step":1},{"title":"Loosen skin (video helpful)","description":"Pat breast dry. Use small knife to cut slit on one side to separate skin from flesh. Slide upside tablespoon between flesh and skin, all over turkey.","images":[],"step":2},{"title":"Slather","description":"Slather about 2/3 of the butter under the skin, then the remaining all over the surface including underside.","images":[],"step":3},{"title":"Season skin","description":"Sprinkle surface with 1/2 tsp salt + pepper. (Can leave overnight - 2 days at this stage)","images":[],"step":4},{"title":"Put in Slow Cooker","description":"Place garlic and onion in slow cooker (mine is 5L / 5 qt). Place turkey on top, skin side up. Top with thyme and rosemary sprigs.","images":[],"step":5},{"title":"Slow Cook","description":"Cook 6 hours on low, first checking at 4 hours to be safe, until internal temperature reads 75C/165F when inserted into the middle.","images":[],"step":6},{"title":"Rest","description":"Transfer turkey to baking tray (reserve juices). Cover loosely with foil, rest for 20 minutes.","duration":20,"images":[],"step":7},{"title":"Crisp","description":"Remove herb sprigs, drizzle turkey with oil (not butter, it burns / not as crispy). Place under a broiler/grill on high (~30cm/12\" from heat source) for 5 to 10 minutes until skin is crispy and bronzed - keep an eye on it, it''s quick.","duration":7.5,"images":[],"step":8},{"description":"Serve turkey with gravy on the side (below), or Cranberry Sauce.","images":[],"step":9},{"description":"Strain slow cooker juices into a bowl. Press juices out of onion and garlic. If you''ve got less than 2.5-3 cups (675-750ml) of liquid, top up with store bought broth/stock.","images":[],"step":10},{"description":"When liquid settles, spoon off about 1/4 cup fat/butter from surface.","images":[],"step":11},{"description":"Place in saucepan set over medium heat. When it bubbles, add flour and mix for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add all slow cooker juices into saucepan. Stir until lump free (use whisk if necessary). Simmer for 3 to 5 minutes until it thickens.","duration":4,"images":[],"step":13},{"description":"Add dark soy (if using), pepper and salt to taste. Pour into jug and serve with turkey.","images":[],"step":14}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["main-dishes","slow-cooker-recipes","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb86a7928197', 'en', 'US', 'Oven Baked Pork Chops with Potatoes', 'Recipe video above. This is a sauce made for baked pork chops. It makes them come out golden and sticky, rather than pale and bland. It''s a country-style sauce that''s savoury and a bit sweet! Potatoes are optional - or sub with other roastable veg.', 'https://www.recipetineats.com/tachyon/2016/09/Baked-Pork-Chops_2.jpg', 10, 30, 40, 4, '[{"id": "ing_worcestershire_sauce", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 0.12, "unit": "bottle of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_pork", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tsp Worcestershire Sauce","2 tbsp ketchup (Note 1)","1 tbsp soy sauce (Note 2)","2 tbsp brown sugar (or white)","1 tbsp olive oil (or vegetable or canola oil)","1 clove garlic, (minced)","2 tsp apple cider vinegar (Note 3)"],"purpose":"Rub"},{"ingredients":["4 pork chops / cutlets (, around 200-250g/7-8oz each including bone (Note 4))","800g/ 1.6 lb baby potatoes (, larger ones cut in half (Note 5))","1 tbsp olive oil","Salt & pepper"],"purpose":"Chops"}]', '[{"description":"Preheat oven to 220C / 430F (standard oven) or 200C / 390F (fan forced / convection).","images":[],"step":1},{"description":"Toss potatoes in oil, sprinkle with salt and pepper. Scatter on baking tray.","images":[],"step":2},{"description":"Place in oven for 15 minutes (giving them a head start).","duration":15,"images":[],"step":3},{"description":"Meanwhile, mix the Rub ingredients together in a small bowl.","images":[],"step":4},{"description":"Slather the pork on both sides with the Rub, reserving some Rub for basting. (See notes for marinating)","images":[],"step":5},{"description":"Take the tray out of the oven. Toss potatoes then push them to the edge.","images":[],"step":6},{"description":"Place pork on tray. Bake for 15 minutes.","duration":15,"images":[],"step":7},{"description":"Remove tray from oven, flick to broiler/grill on high (shelf about 20cm/8\" from heat source).","images":[],"step":8},{"description":"Flip pork, spoon over reserved rub and dab on sides. (Note 4). Broil 7 - 10 minutes until pretty well caramelised.","images":[],"step":9},{"description":"Remove from oven. Use a brush to get the golden juices off the tray and dab it onto the pork - this is key for flavour and colour! Pop it back under the broiler for a couple of minutes to finish off.","images":[],"step":10},{"description":"Serve, scraping the juices on the tray onto the pork, then garnish with parsley if desired.","images":[],"step":11}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","most-popular","one-pot-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d661b946f63', 'en', 'US', 'French Onion Smothered Pork Chops', 'Recipe video above. French Onion Soup meets juicy pan seared pork! A gravy made with caramelised onion that tastes like your favourite French Onion soup. For the full French Onion experience, don''t skip the cheese! Make this with any type of pork chops you want - or chicken!', 'https://www.recipetineats.com/tachyon/2018/11/French-Onion-Smothered-Pork-Chops_4.jpg', 10, 25, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 0.02, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 - 5 pork chops (, boneless (~ 150-200g/5-7oz each) (Note 1))","1/2 tsp garlic powder","Salt and pepper","2 large onions (, sliced into rings (brown, yellow or white))","2 garlic cloves (, minced)","1.5 tbsp / 25g butter (or olive oil)","1 tsp oil (, if needed)","Salt and pepper","1 cup/250ml beef broth/stock (, low sodium)","2 tbsp flour","4 slices cheese (Note 2)","Finely chopped fresh rosemary leaves"]}]', '[{"title":"Caramelise Onions","description":"Melt butter on medium (or medium low for strong stoves). Add onion and garlic, cook 15 minutes until golden brown and caramelised, stirring regularly (see video). Remove from skillet.","images":[],"step":1},{"title":"Prepare Chops","description":"Sprinkle chops with garlic, salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Add oil into skillet if needed. Turn heat up to high. Sear chops 1 minute on each side until nicely browned but not cooked inside. Remove onto plate.","images":[],"step":3},{"title":"Gravy","description":"Turn heat down to medium. Return onion into skillet, scraping in juices. Add flour, mix.","images":[],"step":4},{"description":"Add beef broth and mix until incorporated. Season sauce to taste with salt and pepper.","images":[],"step":5},{"title":"Simmer Chops in Sauce","description":"When it comes to a simmer, give it a big stir then add pork chops.","images":[],"step":6},{"description":"Top chops with cheese, cover with lid to melt and finish cooking the chops through - only 3 minutes for thin chops like I''m using. Internal temp of 160F/70C for no pink (or 155F/68C for blush of pink).","images":[],"step":7},{"title":"Garnish","description":"Remove lid, sprinkle with rosemary. Spoon over French Onion Gravy, then sprinkle with more rosemary.","images":[],"step":8},{"description":"Serve immediately, over mashed potato or similar.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e7aa882995c', 'en', 'US', 'Quesadilla (Beef, Vegetable or Chicken)', 'Recipe video above. Choose ONE Filling! The spice mix adds terrific flavour - great with vegetable, chicken, beef, pork and turkey. Freezer friendly!', 'https://www.recipetineats.com/tachyon/2018/06/Quesadillas_4.jpg', 10, 15, 25, 6, '[{"id": "ing_tortillas", "quantity": {"value": 7.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.5, "unit": "can of 400g"}}]', '[{"ingredients":["6 - 8 flour tortillas (20cm/8\")","2 cups (200g) shredded Monterey Jack cheese (or other of choice) (Note 1)","3/4 cup roughly chopped coriander/cilantro","1 cup corn kernels (frozen thawed or can drained)","ONE Filling of Choice, below (beef, chicken or vegetable)"],"purpose":"Quesadillas:"},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each cumin powder, paprika","1/4 tsp each black pepper, cayenne pepper (optional)"],"purpose":"Quesadilla Spice Mix:"},{"ingredients":["2 1/2 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1 lb ground beef / mince","1 small red capsicum/bell peppers (, diced)","2 tbsp tomato paste","1/4 cup (65 ml) water"],"purpose":"Beef Filling:"},{"ingredients":["2 1/2 tbsp olive oil","500 g/1 lb chicken thighs (, skinless boneless (Note 2))","2 garlic cloves (, minced)","1 small onion (, quartered and sliced)","1 small red capsicum/bell pepper (, diced)"],"purpose":"Chicken Filling:"},{"ingredients":["2 tbsp vegetable oil","1 onion (, diced)","2 garlic cloves (, minced)","1 can of black beans, drained (400g/14oz)","1 capsicum/bell pepper (, diced (any colour))","1 cup corn (canned drained or frozen thawed)","1/4 cup tomato paste","1/4 cup (65 ml) water"],"purpose":"Vegetable Filling:"}]', '[{"description":"Place tortilla on work surface. Sprinkle one side with a bit of cheese, top with Filling of Choice. Sprinkle with corn*, coriander and top with cheese. Fold in half.","images":[],"step":1},{"description":"Preheat non stick skillet over medium low heat (no oil, if pan is not non-stick use 2 tsp oil).","images":[],"step":2},{"description":"Place quesadilla in skillet, press down lightly, cover with lid. Cook for 3 minutes until underside is super golden brown and crispy.","duration":3,"images":[],"step":3},{"description":"Carefully flip over the folded edge (see video). Press down lightly. Cook for 3 minutes until crispy (no lid).","duration":3,"images":[],"step":4},{"description":"Transfer to cutting board, cut in half. Serve immediately!","images":[],"step":5},{"title":"Dipping Sauce options","description":"Sour cream, salsa, Avocado Sauce (pictured)","images":[],"step":6},{"description":"Spice Mix:","images":[],"step":7},{"description":"Mix ingredients in a small bowl. Use for one of the Fillings Options below.","images":[],"step":8},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":9},{"description":"Add beef and cook, breaking it up as you go. Once it changes from pink to brown, add capsicum. Cook for 1 minute.","duration":1,"images":[],"step":10},{"description":"Add tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":11},{"description":"Chicken Filling:","images":[],"step":12},{"description":"Drizzle chicken with 1 tbsp oil, toss to coat. Sprinkle over Spice Mix, toss well to coat.","images":[],"step":13},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute. Transfer to bowl, cool.","duration":2,"images":[],"step":14},{"description":"Return pan to stove, reduce to medium heat. Add remaining 1/2 tbsp oil. Add chicken and cook for 3 minutes until deep golden. Turn and cook for 3 minutes until cooked through.","duration":3,"images":[],"step":15},{"description":"Transfer chicken to cutting board, rest for 2 minutes then dice and cool. Combine with capsicum mixture.","duration":2,"images":[],"step":16},{"description":"Vegetable Filling:","images":[],"step":17},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":18},{"description":"Add beans, corn, tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":19}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["dinner-tonight","main-dishes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a74262062ffa', 'en', 'US', 'Pasta with Tomato Cream Sauce', 'Recipe video above. Pasta in a pink tomato cream sauce! You''ll love how creamy this sauce is, how there''s plenty of it and yet you don''t need gallons of cream. Slurp-worthy as it is, or use it as a base for add ins of your choice - suggestions in the recipe notes.', 'https://www.recipetineats.com/tachyon/2018/03/Creamy-Tomato-Pasta_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 3.0, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/10 oz spaghetti","2 tbsp / 30g unsalted butter","3 garlic cloves (, minced)","½ onion (, finely chopped)","1 cup / 250 ml tomato passata (/ tomato puree (Note 1))","3/4 cup / 185 ml heavy / thickened cream (Note 2 for subs)","1/2 cup / 125 ml milk (, low fat)","3/4 cup / 30g parmesan (, finely freshly grated (Note 3))","1 tsp dried basil, or other herb of choice","1 tsp chicken or vegetable stock powder (, or 1 bouillon cube, crumbled (Note 4))","Finely ground pepper + salt"]}]', '[{"description":"Cook pasta in a big pot of boiling water for time per packet MINUS 2 minutes. Just before draining, scoop out a mugful of pasta cooking water.","images":[],"step":1},{"description":"Melt butter in large skillet over medium heat. Add garlic and onion, cook until translucent - about 2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients. Stir until parmesan is melted. Turn heat up slightly and simmer for 2 minutes. Adjust salt to taste.","duration":2,"images":[],"step":3},{"description":"Add pasta. Toss for 1 to 2 minutes or until sauce thickens and is clinging to pasta instead of swimming on the base of the skillet (video shows this well). Use reserved pasta cooking water if required to thin the sauce out if it gets too thick.","duration":1.5,"images":[],"step":4},{"description":"Serve immediately, garnished with more parmesan and parsley if desired.","images":[],"step":5}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abdea3facba5', 'en', 'US', 'Slow Cooker BBQ Pulled Pork Sandwich', 'See recipe video above. Tender perfectly seasoned slow cooker pulled pork smothered in a homemade BBQ Sauce (see notes for using store bought). Add a classic coleslaw then pile it high onto buns! Great food for gatherings - easy and good value to feed a crowd. Make this in the slow cooker, oven or pressure cooker.', 'https://www.recipetineats.com/tachyon/2017/01/BBQ-Pulled-Pork-Sandwiches-1.jpg', 15, 480, 495, 6, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.015, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.85, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_quantity_coleslaw", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 7.0, "unit": "loaf"}}, {"id": "ing_pork", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 3.0, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.06, "unit": "bottle"}}]', '[{"ingredients":["2 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub"},{"ingredients":["1.5 - 2.2 kg/ 3 - 4.5 lb pork shoulder or butt (, skinless and boneless (Note 1))","3/4 cup apple cider or apple juice (Note 2)","1 quantity Coleslaw","6 - 8 bread rolls"],"purpose":"Pork"},{"ingredients":["1 cup pork juices from slow cooker, once cooked","2 1/2 cups ketchup","1/2 cup apple cider vinegar","2/3 cup brown sugar","1 1/2 tsp each black pepper, onion (or garlic powder), mustard powder","1 tbsp lemon juice","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce (Note 5)"}]', '[{"description":"Mix together Rub then rub all over the pork. Optional: Marinate for 1 hour.","images":[],"step":1},{"description":"Place in the slow cooker and pour over apple cider. Slow cook for 8 hours on low or pressure cook for 1 hr 30 minutes on high. (Note 3)","images":[],"step":2},{"description":"Remove pork from liquid into a roasting pan. Reserve liquid.","images":[],"step":3},{"title":"OPTIONAL: Roast pork for 20","description":"30 minutes at 180C/350F until browned (Note 4). Meanwhile, make BBQ Sauce.","duration":25,"images":[],"step":4},{"title":"Shred pork with forks","description":"it should be fall apart tender (see video).","images":[],"step":5},{"title":"Toss in BBQ sauce","description":"use as much as you like, the recipe makes enough to coat the pork well but not dripping in sauce, plus a bit extra on the side.","images":[],"step":6},{"description":"To make Pulled Pork Sandwiches, pile pork on warmed rolls and top with Coleslaw. I like to lay everything out for people to make their own.","images":[],"step":7},{"description":"Place all ingredients in a medium saucepan over medium heat and whisk. Bring to simmer, then turn down the heat so it simmers gently. Cook for 1 hour. Remove from stove and use per recipe.","images":[],"step":8}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["main-dishes","pork-recipes","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e335e9c8a0ac', 'en', 'US', 'Cajun Baked Turkey Breast and Dressing (Stuffing)', 'This is a genius recipe for a spectacular EASY Thanksgiving centrepiece packed full of big flavours! Avoiding dry baked turkey breast is notoriously difficult, but this recipe tackles that problem in 2 ways: a) Brining the turkey with a Cajun rub; 2) baking the turkey in the same pan as the Dressing (stuffing), it keeps the turkey moist. Plus the turkey juices gets soaked up by the Dressing. No gravy needed - the Dressing has a golden crust but is so juicy underneath, you don''t need gravy. Don''t stress if you can''t get Andouille sausages - refer to the notes. See Note 4 for adjustment for different Turkey sizes. Use Scaler by putting cursor / tap on Servings then move to your turkey weight to adjust recipe scale.', 'https://www.recipetineats.com/tachyon/2016/11/Cajun-Turkey-with-Dressing-6.jpg', 15, 240, 255, 8, '[{"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.025, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pound_bone_in_turkey_breast", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 8.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_tabasco_sauce", "quantity": {"value": 0.09, "unit": "bottle"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp kosher salt *","1 tsp each freshly cracked black pepper (, ground oregano **)","2 tsp each onion powder (, garlic powder, smoked paprika ^)","1/2 tsp cayenne pepper","1/2 tsp. each dried thyme and rosemary"],"purpose":"Cajun Rub"},{"ingredients":["8 lb / 4 kg pound bone-in turkey breast (\"crown\" or \"buffe\") (Note 1)"],"purpose":"Turkey"},{"ingredients":["4 tbsp / 50g butter","8 cloves garlic (, minced (2 tbsp))","2 large onions (, finely chopped^^ (4 cups))","2 celery ribs (, finely chopped (2 cups))","2 green peppers / capsicum (, finely chopped (2 cups))","1 1/4 lb / 650g Andouille sausages (Note 3 for subs!)","1-2 tbsp Tabasco sauce (, to taste)","2 cups chicken stock / broth","1 1/2 cups bread crumbs (panko breadcrumbs can be substituted)"],"purpose":"Dressing / Stuffing (Note 2)"}]', '[{"description":"Mix together Cajun Rub.","images":[],"step":1},{"description":"Rub turkey breast with 3 tbsp of poultry rub (Note 1). Place on a plate and refrigerate overnight, uncovered (24 - 36 hours).","images":[],"step":2},{"title":"Remove turkey from fridge","description":"leave out while making Dressing / Stuffing.","images":[],"step":3},{"description":"Use a food processor to ground the sausages, or finely chop them. If using raw substitute sausages (see Note 3), you can just squeeze the meat out of the casings.","images":[],"step":4},{"description":"Melt butter in large skillet over medium high heat. Add the garlic, half the onion, half the celery and half the capsicum. Cook for 10 minutes or until the vegetables are softened.","duration":10,"images":[],"step":5},{"description":"Transfer vegetables into a bowl. If the skillet is looking dry, add a tiny splash of oil. Add sausage and cook, breaking it up as you go.","images":[],"step":6},{"description":"Add cooked onion etc back into the skillet and add remaining onion, celery and capsicum. Stir.","images":[],"step":7},{"description":"Add tabasco (start with 1 tbsp) and chicken broth. Bring to simmer, then turn heat down to medium. Simmer for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Stir in breadcrumbs then remove from heat. It should still be very moist and a bit liquidy, but not like soup.","images":[],"step":9},{"description":"While Dressing is simmering, preheat oven to 325F / 165C (standard) or 295F / 145C (fan forced / convection).","images":[],"step":10},{"description":"Place turkey breast in a roasting pan so there is 2\"/5cm (or so) around it for the dressing.","images":[],"step":11},{"description":"Spoon dressing around the turkey.","images":[],"step":12},{"title":"Cover loosely with foil then bake for 3 1/4","description":"3 1/2 hours, then uncover and roast for an additional 30 minutes to brown and crisp the skin, or until the internal temperature of the turkey is 75C / 165F (Note 4).","images":[],"step":13},{"description":"Remove from oven then loosely cover with foil. Rest for 20 minutes before serving (Note 5).","duration":20,"images":[],"step":14}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American","Cajun"],"categories":["main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c049a72deaf2', 'en', 'US', 'Pork Tenderloin with Creamy Marsala Sauce', 'Juicy pork tenderloin smothered in a Creamy Marsala Sauce with Mushrooms. It''s like gravy - but even better because the sauce has beautiful layers of flavour in it from the Marsala. Using wine in cooking is how posh restaurants make such beautiful sauces! Use this Marsala Sauce for other proteins like chicken, veal and beef.', 'https://www.recipetineats.com/tachyon/2016/06/Pork-Tenderloin-Creamy-Marsala-Sauce_4.jpg', 5, 30, 35, 3, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_marsala", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g pork tenderloin (Note 1)"]},{"ingredients":["2 tbsp butter (salted or unsalted)","5 oz / 150g mushrooms (, sliced (I used Swiss Brown))","1/4 cup finely chopped shallots or onion","1 garlic clove (, minced)","1 1/2 tbsp flour","1/2 cup / 125 ml marsala (Note 2)","2 cups / 500 ml chicken broth (, low sodium)","5 tarragon leaves (optional) (thyme is also lovely) (Note 3)","1/4 cup / 65 ml cream"],"purpose":"Creamy Marsala Sauce"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Sprinkle pork with salt and pepper.","images":[],"step":2},{"description":"Heat oil in an ovenproof skillet over high heat. Sear on all sides until nicely browned.","images":[],"step":3},{"description":"Place in the oven for 15 minutes for the faintest blush of pink (pictured) or 18 to 20 minutes for no pink. See Note 4 for internal cook temperatures.","duration":15,"images":[],"step":4},{"description":"Remove pork from skillet onto a plate, cover with foil and set aside in a warm place while you make the sauce.","images":[],"step":5},{"description":"Creamy Marsala Sauce","images":[],"step":6},{"description":"Melt 1 tbsp butter in the same skillet over high heat. Cook mushrooms until browned, then remove.","images":[],"step":7},{"description":"Reduce heat to medium high, melt 1 tbsp butter,. Add onion and garlic, cook for 2 minutes or until onion is softened. Add flour and mix.","duration":2,"images":[],"step":8},{"description":"Add marsala, cook until mostly evaporated (about 1 minute). Add tarragon and chicken broth, whisk until dissolved. Bring to simmer and cook until the liquid reduces by half - 3 to 5 minutes.","images":[],"step":9},{"description":"Add cream and mix, then return the mushrooms and pork into the skillet as well as juices pooled on the plate. Simmer for 1 - 2 minutes until the sauce thickens into a thin gravy consistency (it will thicken more as you serve).","duration":1.5,"images":[],"step":10},{"description":"Transfer to serving platter with the gravy on the side or poured over the top. Serve with mashed potatoes of course!! (Here is my Make Ahead Mashed Potatoes recipe)","images":[],"step":11}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cdf6bb8a6a', 'en', 'US', 'Mexican Chipotle Pork and Beans', 'Recipe video above. This is a big pot of saucy, shreddable meat in a rich, spicy, chipotle sauce. Pork shoulder is slow cooked into fall-apart submission with meaty lima beans that absorbs the bold flavoured sauce. Stuff in tacos, serve over red rice, eat like stew!SPICE NOTE: This sauce is spicy. Not off-the-charts spicy, but it has a good kick! If you''re concerned, remove half the chillis from the can of chipotle in adobo (as the chillies are where the spiciness is). If you''re still worried, best to give this a miss because chipotle in adobo IS spicy!!', 'https://www.recipetineats.com/tachyon/2023/05/Mexican-Chipotle-Pork-and-Beans_6.jpg', 15, 170, 185, 6, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_chipotle_in_adobo", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1.5kg / 3lb pork shoulder (skinless, boneless), cut into 6 equal pieces (Note 1)","1 tsp cooking/kosher salt","1/2 tsp black pepper","2 tsp cumin powder"],"purpose":"Pork:"},{"ingredients":["200g / 7 oz chipotle in adobo (- the chillis + sauce (Note 2))","2 tbsp olive oil","1 onion (, finely chopped)","4 garlic cloves (, finely minced)","1/4 cup tomato paste","1 cup orange juice (real, not reconstituted sweetened stuff - Note 3)","2 cups chicken stock/broth (, low sodium)","2 bay leaves (fresh, else dried)","1 tsp cooking/kosher salt","3 x 420g / 16 oz canned butter beans / lima beans (, or other of choice (Note 4))"],"purpose":"Sauce:"},{"ingredients":["1 tbsp dried oregano","1 tsp cumin powder","1 tsp coriander powder","1/2 tsp allspice powder"],"purpose":"Dried herbs & spices"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"SPICINESS","description":"Read note above about spiciness!","images":[],"step":2},{"description":"Puree chipotle in adobo until smooth using a stick blender or similar.","images":[],"step":3},{"description":"Sprinkle pork all over with salt, pepper and cumin.","images":[],"step":4},{"title":"Brown pork","description":"Heat all the oil in a large oven-proof pot over high heat. Brown the pork all over in 2 batches, the remove onto a plate (~ 1 minute each side).","images":[],"step":5},{"title":"Sauté","description":"Cool the pot slightly then return to medium heat. If the pot looks dry, add 1 tbsp oil. Sauté onion, garlic, the herbs & spices for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Cook off tomato & chipotle","description":"Add tomato paste and cook it off for 2 minutes. Add chipotle puree and cook for 2 minutes.","duration":2,"images":[],"step":7},{"title":"Slow cook 2 hours","description":"Add remaining ingredients EXCEPT beans. Stir, then bring to simmer. Place pork in - arrange so its submerged as best as possible. Cover with lid. Place in oven for 2 hours. (Note 6 other cook methods)","images":[],"step":8},{"title":"Add beans, cook 30 min","description":"Remove lid, add beans. Return to oven for 30 minutes without lid to caramelise the surface. The pork will be fork-tender!","duration":30,"images":[],"step":9},{"description":"Serve like stew over Mexican red rice or with tortillas for dunking. Or make wickedly food tacos with finely chopped white onion, fresh coriander/cilantro, avocado slices and a squeeze of lime. More serving options above the recipe video.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mains","mexican-recipes","pork","pork-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d835d34e8e79', 'en', 'US', 'Just a great Pork Rub', 'Recipe video above. This is a real great all-rounder rub for pork chops. It gives the pork great flavour, a lovely warm red colour, and if you throw a knob of butter in at the end, you get a tasty flavoured sauce too!There''s enough spices in the rub so that if you''re missing one or two, the rub will still be tasty, see Note 1.Makes 4 tablespoons / 45g of rub which will season 4 thick-cut chops. Keeps for the shelf life of the spices you used.', 'https://www.recipetineats.com/tachyon/2021/08/Pork-Rub_06.jpg', 5, 12, 17, 4, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.007, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.015, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tbsp smoked paprika","2 1/4 tsp salt (cooking/kosher salt, Note 2)","3/4 tsp black pepper","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 tsp dried oregano","3/4 tsp mustard powder","1/2 tsp cumin powder","1/2 tsp sage powder"],"purpose":"Pork rub (subs Note 1):"},{"ingredients":["4 pork chops, any type (pictured: pork cutlets, 220g/7oz each, 2cm / 0.8\" thick) (Note 3)","1 1/2 tbsp olive oil (per batch you cook)","50g / 4 tbsp unsalted butter (for flavoured butter sauce, 15 g / 1 tbsp per chop)"],"purpose":"Pork:"}]', '[{"title":"Rub: Mix spices in a small bowl. Keeps for weeks","description":"even months! (Whatever the shelf life of the spices is you used).","images":[],"step":1},{"title":"Using pork rub","description":"Pat pork chops dry. Sprinkle then use your fingers to lightly rub the seasoning on both sides, as well as the sides. Shake off excess. Cook per below.","images":[],"step":2},{"title":"Cooking thin pork chops","description":"up to 1.75 cm / 0.7\" thick (Note 3):","images":[],"step":3},{"description":"Place a rack over a tray. (Note 4)","images":[],"step":4},{"description":"Heat oil in a heavy based skillet over medium-high heat.","images":[],"step":5},{"description":"Cook pork chops for 3 minutes on each side until deep golden. Don''t crowd the pan else the pork will stew instead of sear!","duration":3,"images":[],"step":6},{"description":"Rest on rack for 3 minutes.","duration":3,"images":[],"step":7},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":8},{"title":"Cooking THICK pork chops","description":"2cm / 0.8\"+ (Note 3):","images":[],"step":9},{"description":"Preheat oven to 200°C/390°F (180°C fan). Place a rack over a tray. (Note 4)","images":[],"step":10},{"description":"Heat oil in a heavy based skillet over medium high heat.","images":[],"step":11},{"description":"Use tongs to sear the edge of the chops (fat strip), rotating as you go, until you get nice colour all around, about 3 minutes in total (see video demo). Then sear each side for 2 minutes until golden.","duration":2,"images":[],"step":12},{"description":"Put pan into the oven and allow to finish cooking for 3 minutes or until the internal temperature reaches 65°C/149°F. Remove pork and rest 3 minutes on rack.","duration":3,"images":[],"step":13},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dfcdd73275e', 'en', 'US', 'Pork Tenderloin with Creamy Mustard Sauce', 'Recipe video above. This is one of those recipe gems that proves just few ingredients and minimal effort can still deliver a knock-out dish!It''s easy enough for a weeknight meal, but can step up as a dish elegant enough for company. A pinch of fresh tarragon adds a lovely sweet aniseed flavour, while mustard brings the oomph and thickens the sauce.Note: The cook time is affected by the size of the pork fillet so a meat thermometer is highly recommended to ensure the pork is cooked perfectly.', 'https://www.recipetineats.com/tachyon/2021/05/Pork-Tenderloin-with-Creamy-Mustard-Sauce_4.jpg', 8, 20, 33, 5, '[{"id": "ing_pork", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.12, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.022, "unit": "L"}}]', '[{"ingredients":["2 pork tenderloins (, 500g / 1lb each (Note 1))","1 tsp salt","1 tsp pepper","2 tbsp oil (vegetable, canola, or olive oil)"]},{"ingredients":["1/2 cup cream (, heavy / thickened (Note 2))","1 tbsp Dijon mustard (Note 3)","1 tbsp whole grain mustard (Note 3)","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped (Note 4))","1/2 tsp salt","1/2 tsp pepper","1 - 2 tbsp water (, as needed)"],"purpose":"Sauce:"}]', '[{"title":"Preheat oven","description":"Preheat oven to 200°C / 390°F (180°C fan). Place a rack over a tray (for resting the cooked meat).","images":[],"step":1},{"title":"Season pork","description":"Sprinkle the tenderloins all over with salt and pepper.","images":[],"step":2},{"title":"Sear pork","description":"Heat oil in a large oven-proof skillet over medium-high heat. Sear pork all over until golden. This takes around 5 minutes (I sear 4 sides).","images":[],"step":3},{"title":"Bake (Note 5)","description":"Transfer the skillet with the pork in it to the oven. Bake for 12 - 15 minutes or until an instant read thermometer reads 65°C / 149°F. This will have a blush of pink, a perfect medium for optimum juiciness. (For no pink at all, add 3 minutes cooking and target an internal temperature of 68°C / 155°F.)","duration":13.5,"images":[],"step":4},{"title":"Rest","description":"Remove pork from skillet and transfer to the resting rack for 5 minutes.","duration":5,"images":[],"step":5},{"title":"Creamy Mustard Sauce","description":"Return same skillet to the stove over medium heat. Add cream and both mustards. Mix well, scraping the bottom of the pan to dissolve any golden bits stuck to the base of the pan into the sauce (free flavour!). Once it becomes hot but not simmering, stir in salt, pepper, tarragon and parsley. If the sauce seems too thick, thin with a little water as needed. No need to simmer, the sauce is done!","images":[],"step":6},{"title":"Serve: Slice into 2","description":"2.5cm (0.8 - 2\") slices. Serve with Creamy Mustard Sauce!","images":[],"step":7}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b90880ba9f8', 'en', 'US', 'Pesto pasta salad', 'Recipe video above. Don''t skimp on pesto, and don''t be shy with olive oil. If you do, you''ll end up staring at a mound of flavour-lacking, dry pesto pasta salad, thinking "darn it, I should have just followed the recipe!".PS Just 2 tablespoons of mayo is the secret here. Just gives an edge of creaminess without weighing it down, plus significantly improves the quality of next-day leftovers - prevents it from drying out.TIP: Homemade pesto obviously rules here, but if you need to resort to store-bought, get it from the fridge rather than aisle. It''s better.', 'https://www.recipetineats.com/tachyon/2023/03/Pesto-pasta-salad_9.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pinenuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_basil", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 250.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 220.0, "unit": "unit"}}, {"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz spiral pasta (fusilli, or other of choice, 3 1/2 cups)","1 tbsp salt (, for cooking pasta)"]},{"ingredients":["2 tbsp pinenuts (, toasted (sub walnuts, cashews, almonds))","2 cups (tightly packed) basil leaves","1 small garlic clove (, minced)","1/2 cup parmesan (, finely grated)","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","7 tbsp extra virgin olive oil (or 50/50 grapeseed/olive oil)"],"purpose":"Pesto (Note 1):"},{"ingredients":["2 tbsp mayonnaise (S&W, else Hellman''s, Note 2)","250g (1 heaped cup) cherry tomatoes, cut in half","220g/ 7 oz baby bocconcini (, drained, cut in half (Note 3))","1 cup (tightly packed) baby rocket/arugula leaves (40g)","1/2 tsp cooking/kosher salt","Small basil leaves (, optional garnish)"],"purpose":"Pasta Salad:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres of water to the boil with the salt. Cook for the pasta packet time + 1 minute. Drain in a colander, rinse under cold water. Shake off excess water well, then allow to fully cool and dry.","images":[],"step":1},{"title":"Pesto","description":"Place all ingredients in a tall jug just large enough to fit the head of a stick blender. Blitz under pretty smooth. Not a green smoothie, we still want some visible green bits! but not chunks.","images":[],"step":2},{"title":"Toss","description":"Place pasta in a bowl, scrape in the pesto. Add mayonnaise then toss well. Add bocconcini and tomato, toss gently just to disperse. Add rocket/arugula and toss just to disperse.","images":[],"step":3},{"title":"Serve","description":"Transfer into a serving bowl. Scatter with basil leaves, if using. Serve!","images":[],"step":4}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","salad-recipes-main-course","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d9cee3c9bf0e', 'en', 'US', 'My Favourite Quinoa Salad', 'Recipe video above. Elevate your Quinoa Salad with two simple tricks: Toasting the quinoa in the oven to give it a gorgeous nutty flavour (great cheffy tip!), and use a wickedly good garlic/ginger dressing!It makes an excellent meal-worthy Asian-style salad, or colourful rainbow salad to take to gatherings. Don''t skip the sprinkle of Wasabi Pea dust. It''s the cherry on top!Serves: 10-12 as side, 5 as meal', 'https://www.recipetineats.com/tachyon/2021/03/My-Favourite-Quinoa-Salad-5.jpg', 20, 35, 55, 10, '[{"id": "ing_quinoa", "quantity": {"value": 0.4, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 250.0, "unit": "punnet of 250g"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 0.4, "unit": "pack"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_grapes", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.007, "unit": "jar of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_wasabi_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}]', '[{"ingredients":["1 cup quinoa (, tri-colour (or other colour, Note 1))","2 cups water"],"purpose":"Quinoa:"},{"ingredients":["1 cup cucumber (, finely diced (Note 2))","1 carrot (, medium, peeled and finely shredded (Note 3))","3 cups red cabbage (, finely shredded (~1/4 small or 1/8 large cabbage))","2 green onions (, finely sliced)","250g/ 8oz cherry tomatoes (, small ones quartered, large ones cut into 6)","1 cup shelled edamame (, cooked per packet then cooled (Note 4))","1 red capsicum/bell pepper (, finely chopped)","1/2 cup coriander/cilantro leaves (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["5 tbsp soy sauce (, light or all-purpose (Note 5))","2 tbsp mirin (Note 6)","2 tbsp rice wine vinegar (sub: cider, sherry or champagne vinegar)","2 tbsp sesame oil (, toasted (Note 7))","2 1/2 tbsp canola, vegetable or grapeseed oil","2 1/2 tbsp Kewpie mayonnaise (sub whole-egg mayo such as Hellman''s or S&W, Note 8)","2 1/2 tsp sugar (white or brown)","2 tsp ginger (, freshly grated)","1 garlic clove (, crushed using garlic press or finely grated using microplane)"],"purpose":"Dressing:"},{"ingredients":["1/3 cup wasabi peas (, crushed (Note 9))","1 tbsp sesame seeds (, toasted (Note 10))"],"purpose":"Garnishes:"}]', '[{"description":"Cook quinoa:","images":[],"step":1},{"title":"Toast for extra flavour","description":"Preheat oven to 200°C/390°F (180° fan) Spread quinoa on a tray. Bake 15 minutes, stirring halfway, until it''s lightly browned and smells nutty.","images":[],"step":2},{"title":"Rinse","description":"Transfer to fine mesh sieve or strainer. Rinse under running water for 10 seconds, shake off excess water well.","duration":0.16666666666666666,"images":[],"step":3},{"title":"Cook","description":"Scrape into a medium saucepan. Add water, place lid on. Bring to simmer on medium heat, then lower stove to low and simmer for 15 minutes (or until all water is absorbed, tilt pot to check).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from stove (lid still on) and rest for 10 minutes.","duration":10,"images":[],"step":5},{"title":"Fluff & cool","description":"Remove lid, fluff quinoa with a fork and allow to fully cool before using. (Spread on a tray if you want to speed things up).","images":[],"step":6},{"title":"Dressing","description":"Place ingredients in a jar and shake well.","images":[],"step":7},{"description":"Toss salad! Place quinoa in a large bowl. Add all salad ingredients. Pour over dressing, toss very well.","images":[],"step":8},{"title":"Garnish","description":"Either transfer to a large serving platter or individual bowls. Sprinkle generously with crushed Wasabi Peas and sesame seeds. Devour!","images":[],"step":9}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian-esque"],"categories":["salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a48e24cde0d4', 'en', 'US', 'Creamy Goat Cheese & Roasted Red Pepper Risoni (Orzo)', 'Recipe video above. Goat''s cheese and jarred fire-roasted red peppers (capsicum) makes this dish special even though it''s quick and simple! The sauce is a little bit smoky and a little bit creamy, while olives add briny freshness. Tastes like a Mediterranean risotto!Get the risoni boiling first then start on the sauce. Serve as a meal or as a side with a simple piece of cooked fish, prawns/shrimp, chicken or pork chops.', 'https://www.recipetineats.com/tachyon/2025/01/Roasted-red-pepper-goats-cheese-risoni_2.jpg', 7, 13, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.31, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250g/ 8oz risoni pasta (orzo) (, or other very small pasta (tiny stars, novelty shapes like dinosaurs, ditalini))","2 tsp cooking salt/kosher salt (, for cooking the pasta)","2 tbsp extra virgin olive oil","1 red onion (, halved then cut into 5mm / 0.2\" slices (sub regular onion))","2 garlic cloves (, finely minced)","310g/ 10oz jar chargrilled / fire-roasted sliced red capsicum/peppers","2 cups tomato passata or puree (Note 2)","1/2 cup sliced Kalamata olives ( or other briny/pickly thing (like pickles, chopped))","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper","120g/4 oz goat''s cheese (, the creamy feta type (Note 3))"]},{"ingredients":["1 tightly packed cup basil leaves","1 tbsp roughly chopped parsley (, plus extra for garnish)"],"purpose":"Finishing – CHOOSE (Note 4)"}]', '[{"title":"Boil risoni","description":"Bring a small pot or large saucepan of water to the boil. Add salt and cook risoni until just under al dente (ie still a bit firm inside) as it will cook more in the sauce. 8 minutes for me.","images":[],"step":1},{"title":"Drain & rinse","description":"Just before draining, scoop out 1/2 cup pasta cooking water and set aside. Drain, rinse briefly under the tap then leave the risoni in the colander while you finish the sauce.","images":[],"step":2},{"title":"Sauté","description":"Heat the oil in a large non stick skillet (30cm/12\") over high heat. Add onion and cook for 2 minutes until starting to soften. Add garlic and capsicum strips. Cook for 2 minutes until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Simmer","description":"Add tomato and olives. Bring to a simmer, lower heat to medium and simmer for 5 minutes, stirring every now and then.","duration":5,"images":[],"step":4},{"title":"Melt goat cheese","description":"Add cooked risoni, salt, pepper and the pasta cooking water. Stir to combine. Add most of the goat''s cheese (reserve some for garnish), stir so it melts.","images":[],"step":5},{"title":"Basil & serve","description":"Stir through basil or parsley just before serving. Divide between bowls. Crumble over reserved goat''s cheese, sprinkle with extra basil. Dig in with a spoon!","images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mediterranean vibes","Western"],"categories":["dinner-tonight","mediterranean-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdef31925f9d', 'en', 'US', 'Cheesy baked Mexican beef and beans', 'Recipe video above. A bubbly casserole of sorts, this Mexican beef and bean is like a baked version of chilli con carne with lots of melty cheese - but faster to make. Think of it like your ultimate all-purpose Mexican beef - stuff in tacos, DIY burrito wraps, dunk with corn chips - like nachos!', 'https://www.recipetineats.com/tachyon/2023/03/Cheesy-Mexican-Beef-and-Beans-Casserole_8a.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_pickled_jalape_o", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 red onion (, finely chopped)","2 garlic cloves (, finely minced)","1 green capsicum / bell pepper (, cut into 1cm / 1/2\" cubes (or other colour))","500g/ 1 lb beef mince (ground beef) (Note 1)","400g/ 14oz can red kidney beans or black beans (, drained (or other beans))","1 cup tomato passata (Note 2)","1/3 cup pickled sliced jalapeño (Note 3)","1 1/2 cups Colby cheese (, shredded (or other cheese, Note 4))"]},{"ingredients":["1 1/2 tsp cumin powder","1 1/2 tsp smoked paprika (sub normal paprika)","1 tsp garlic powder (sub onion powder)","1 tsp garlic powder (sub onion powder)","1 tsp dried oregano","1/2 tsp cayenne pepper (sub black pepper)","1 tsp cooking/kosher salt"],"purpose":"Mexican spice mix:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":1},{"title":"Sauté","description":"Heat the olive oil in a cast-iron skillet over medium high heat (or other oven-proof pan). Cook onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":2},{"title":"Cook beef & spices","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add spices, then cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Beans & tomato","description":"Add kidney beans and passata. Stir, then bring to a simmer.","images":[],"step":4},{"description":"Cheese it! Scatter the jalapeño across the surface, top with cheese.","images":[],"step":5},{"description":"Bake 15 minutes (no lid) then remove from the oven.","images":[],"step":6},{"description":"Serve! Scoop into bowls and serve with corn chips or tortillas with your favourite Mexican fixings (guacamole or avocado sauce pico de gallo or restaurant style salsa, fresh coriander/coriander, sour cream). Dunk like nachos, make DIY burritos or tacos!","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","one-pot-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_574435a6092b', 'en', 'US', 'Beef Barbacoa - Mexican Pulled Beef for Tacos and everything!', 'Recipe video above. Ultra-juicy Mexican pulled beef, tossed in a chipotle-spiced sauce! With a unique subtly spiced, tangy flavour, use this Beef Barbacoa for tacos, burritos, enchiladas, taquitos – the possibilities are endless. This is a slow cooker version that''s simple to put together. Which means ... effortless. YES!', 'https://www.recipetineats.com/tachyon/2021/03/Beef-Barbacoa_3.jpg', 10, 495, 505, 10, '[{"id": "ing_beef_cheeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_chipotle_chiles_in_adobo_sauce", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.012, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.05, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_round_clove", "quantity": {"value": 0.003, "unit": "jar"}}]', '[{"ingredients":["2kg / 4 lb beef cheeks (, or chuck beef(see Note 1))","1 tsp salt (, kosher/cooking)","1 tsp black pepper","2 tbsp vegetable oil (, for searing)","4 bay leaves"]},{"ingredients":["4 chipotle chiles in adobo sauce (Note 2)","3/4 cup dark ale (beer), or low sodium beef broth/stock ( (Note 3))","1/2 cup apple cider vinegar","4 tbsp lime juice","6 garlic cloves","4 tsp ground cumin","2 tsp oregano","1/2 tsp ground cloves"],"purpose":"Barbacoa Sauce:"}]', '[{"title":"Cut beef","description":"Cut large cheeks in half so you have around 12 - 15 pieces cheeks. If using chuck, cut into 12 or so pieces.","images":[],"step":1},{"title":"Season","description":"Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown beef","description":"Heat oil in a large pot or skillet over high heat. Sear beef in batches, browning aggressively all over. Place beef in slow cooker.","images":[],"step":3},{"title":"Blitz sauce","description":"Place Barbacoa Sauce ingredients in a blender, food processor or similar (I use a Nutribullet). Blend until smooth – it shouldn''t take long.","images":[],"step":4},{"title":"Slow cooker (see Note 4 for alt. cooking methods)","description":"Pour sauce over cheeks in slow cooker. Add bay leaves. Arrange cheeks so they are submerged as much as possible. Don''t worry, they will release juice as they cook and raise the liquid level.","images":[],"step":5},{"description":"Slow-cook for 8 hours on low. The beef should be effortless to shred when done.","images":[],"step":6},{"title":"Shred","description":"Remove cheeks from slow cooker into a pan. Shred using 2 forks.","images":[],"step":7},{"title":"Sauce","description":"Pour over 3 or 4 ladles of the sauce, then toss.","images":[],"step":8},{"title":"Serve","description":"Use in tacos with taco fixings of choice! Pictured with Mexican Red Rice, Pickled Red Cabbage for Tacos (in this Fish Tacos recipe) and Lime Crema (Note 5).","images":[],"step":9}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","slow-cooked-fall-apart","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f902cbfe2cc0', 'en', 'US', 'Prawn Tacos (Shrimp) - with Chipotle Lime Marinade', 'Recipe video above. Chipotle is the power ingredient here, adding a stack of flavour and a hit of heat to this zesty, earthy, Mexican marinade for prawns. Perfectly paired with a creamy-yet-zingy Slaw with the trademark juiciness and floppiness of traditional Coleslaw, but made lighter with no mayonnaise which is too heavy for prawns. The Pink Taco Sauce is my quick sauce of choice here, but there''s enough juiciness in the Slaw and Tacos that you could forgo it - or just add a dash of your favourite hot sauce, or just a dollop of plain sour cream.LEMON alternative - use lemon when limes are not in season. Albeit not traditional Mexican, it works perfectly!SPICE LEVEL: Medium, chipotle is a bit spicy! You can dial it down.', 'https://www.recipetineats.com/tachyon/2020/08/Prawn-tacos_shrimp__3.jpg', 15, 6, 21, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_ime_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cabbage", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.012, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.094, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 13.5, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/1 lb medium prawns/shrimp (, peeled (frozen thawed, or 1 kg / 2lb unpeeled whole))","Zest of 1 lime (or lemon)","1/4 cup lime juice (or lemon)","1 tbsp chipotle powder (MEDIUM spicy, can reduce to 2 tsp for MILD, Note 1)","2 tbsp coriander/cilantro (, finely chopped (sub chives))","2 garlic cloves (, minced)","1/4 cup olive oil","1/2 tsp each salt and pepper"],"purpose":"Prawn/shrimp taco marinade:"},{"ingredients":["8 cups green cabbage (, finely shredded (about 1/4 head))","1/2 onion (, very finely chopped (brown, yellow, white))","3/4 cup plain yogurt ((like Greek), unsweetened)","1/4 coriander/cilantro (, finely chopped (sub chives))","1/4 cup lime juice (or lemon)","1/4 cup extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Taco Slaw:"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 2))"],"purpose":"PINK TACO SAUCE:"},{"ingredients":["1 tbsp olive oil","12 - 15 small tortillas ((corn or flour), warmed or charred per packet)","Lime wedges (highly recommended)","Coriander/cilantro (, roughly chopped)"],"purpose":"TO COOK & SERVE"}]', '[{"description":"Mix Marinade ingredients in a bowl, then toss the prawns in the marinade.","images":[],"step":1},{"title":"Set aside for just 20 minutes","description":"no longer. Even 5 minutes is enough.","images":[],"step":2},{"description":"Warm a serving bowl using any method (microwave 1 minute, hot water then dry).","images":[],"step":3},{"description":"Heat 1 tablespoon oil in a large skillet over high heat. Add half the prawns and cook each side for 60 seconds (or on a BBQ on high heat, suggest double skewer for easy rotation).","duration":1,"images":[],"step":4},{"description":"Transfer to warmed bowl, loosely cover with foil. Cook the remaining prawns.","images":[],"step":5},{"description":"Serve with Slaw, Pink Taco Sauce, warmed tortillas and lime wedges.","images":[],"step":6},{"description":"Place all ingredients in a very large bowl then toss well (I use my hands!).","images":[],"step":7},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Keeps for 3 days!","images":[],"step":8},{"description":"Mix ingredients and adjust Sriracha to your taste. Mix well - sour cream becomes looser the more you mix it.","images":[],"step":9}]', '["gluten","milk","shellfish"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","prawns-shrimp","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdde56200e9e', 'en', 'US', 'Mushroom Risotto', 'Recipe video above. Creamy, comforting Mushroom Risotto fully loaded with garlicky, buttery mushrooms stirred through the risotto AND piled on top. Mouthwateringly delicious, cosy food that''s elegant enough to serve at a dinner party. It takes time to make mushrooms golden brown, but it''s worth every minute - it''s amazing!!', 'https://www.recipetineats.com/tachyon/2019/10/Mushroom-Risotto_7.jpg', 15, 35, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500g (1 lb) mushrooms (, sliced 3 mm / 1/8\" thick (Note 1))","250g (1/2 lb) mushrooms (, quartered (Note 1))","3 tbsp butter","2 tbsp olive oil","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["1 tbsp butter","1 garlic clove (, minced)","2 eschallots / French onions (, finely chopped (or 1/2 onion))","1/4 cup dry white wine (Note 2)","1 1/4 cups arborio rice (, uncooked)","5 cups chicken broth/stock (, low sodium, warm (Note 3))"],"purpose":"Risotto:"},{"ingredients":["1/2 cup cream (, optional but recommended(Note 4))","2 tbsp (30g) butter (, optional (Note 4))","1/2 cup parmesan cheese (, finely grated)","1/2 tsp salt and pepper (, each)"],"purpose":"Finishes:"},{"ingredients":["Finely chopped parsley or chives","Parmesan (, freshly grated)"],"purpose":"Serving:"}]', '[{"description":"Garlic Butter Mushrooms","images":[],"step":1},{"description":"Add 1 tbsp oil and half the butter in a large heavy based pot over high heat (Note 5). Once melted, add half the mushrooms and cook until pretty golden brown (~4 min).","images":[],"step":2},{"description":"Add 1/2 the garlic, 1/4 tsp each salt and pepper, then continue to cook until golden brown (~1.5 min). Then remove into bowl.","images":[],"step":3},{"description":"Repeat with remaining mushrooms, then remove.","images":[],"step":4},{"description":"Turn heat down to medium. In the same pot, melt butter then add garlic and onion.","images":[],"step":5},{"description":"Cook 2 minutes until onion is translucent but not golden.","images":[],"step":6},{"description":"Add wine and allow to simmer rapidly for 2 minutes, scraping the base of the pot, until mostly evaporated.","duration":2,"images":[],"step":7},{"description":"Add rice and stir for 1 minute until semi translucent.","duration":1,"images":[],"step":8},{"description":"Add about 1.5 cups of stock. Stir, then leave for 3 minutes, stirring just a few times, until mostly absorbed (~3 min).","duration":3,"images":[],"step":9},{"description":"Add about 1.5 cups stock, stir every now and then until mostly absorbed (~3 min) - no need to stir constantly. Repeat twice more until all stock used up, rice is just cooked but risotto still creamy and sloppy (~10 min, Note 6).","images":[],"step":10},{"description":"Add cream and butter, stir vigorously to make creamy.","images":[],"step":11},{"description":"Stir in parmesan, salt and pepper.","images":[],"step":12},{"description":"Stir through half the mushrooms, then taste and add more salt and pepper if needed. Consistency should be creamy, not stodgy (Note 7).","images":[],"step":13},{"description":"Reheat remaining mushrooms (I microwave).","images":[],"step":14},{"description":"Spoon risotto into bowls, then top with reserved mushrooms (including a drizzle of buttery juices pooled in bowl!)","images":[],"step":15},{"description":"Garnish with parsley if using, and extra parmesan. Serve immediately!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["American-Italian","Italian","Western"],"categories":["mushroom-recipes","pasta-recipes","rice-recipes","rice-side-dishes","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49fac396f5a9', 'en', 'US', 'Creamy Mushroom Pasta', 'Recipe video above. It''s your creamy pasta dream come true...loaded with golden buttery garlicky mushrooms! SCALING UP (slide scaler): Cook mushroom in batches, otherwise they''ll steam instead of going golden.', 'https://www.recipetineats.com/tachyon/2019/09/Creamy-Mushroom-Pasta_4.jpg', 8, 12, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160g/ 6oz fettuccine ( or linguine (Note 1))","2 tbsp (30g) unsalted butter","1/2 tbsp olive oil (Note 2)","300g/ 10 oz mushrooms (, sliced 1/3 cm / 1/8\" thick (white, cremini/swiss brown))","2 garlic cloves (, finely chopped)","1/2 cup (125 ml) white wine (, dry (or rose, sub more broth))","1/2 cup (125ml) chicken broth/stock (, low sodium (or veg))","3/4 cup (185ml) cream (, heavy / thickened (Note 3))","1/3 cup (30g) parmesan (, finely grated (Note 4))","1/2 tsp salt and pepper (, each)"]},{"ingredients":["Extra parmesan (, for serving)","Parsley (, roughly chopped (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in salted water for 1 minute less than time per packet (start this mid mushroom cook). Just before draining, scoop out 1 cup cooking water, then drain.","duration":1,"images":[],"step":1},{"description":"Melt butter and heat oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add mushrooms and cook, stirring regularly. When they start to sweat, add a pinch of salt and pepper.","images":[],"step":3},{"title":"When pretty golden (about 4","description":"5 minutes), add garlic and cook until garlic is golden and mushroom is golden.","images":[],"step":4},{"description":"Stand back and add wine (it will be steamy!!), stir, scraping the bottom of the skillet. Simmer rapidly until wine is mostly evaporated and winey smell is gone.","images":[],"step":5},{"description":"Add broth, cream, parmesan, salt and pepper. Stir to dissolve parmesan and simmer for 2 minutes, stirring regularly.","duration":2,"images":[],"step":6},{"title":"Transfer pasta into sauce, toss for 1","description":"2 minutes until sauce thickens and coats pasta. If sauce gets too thick (rather than slick, see video), add a splash of reserved pasta cooking water.","duration":1.5,"images":[],"step":7},{"description":"Garnish with parsley and serve immediately with extra parmesan!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mushroom-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f11597f213f', 'en', 'US', 'Green Ginger Rice Noodles', 'Recipe video above. Rice noodles tossed in a ginger-forward, "Asian-pesto" sauce that’s based on Hainanese Chicken’s Ginger Shallot Sauce. Crazy good, fast, and it even turns the noodles green which I’m weirdly obsessed with. I threw in some shredded chicken for protein to make it a meal. Cucumber would be so great to make this a refreshing side dish (deseeded, batons or thin half-moons).Serve it warm or cold. It’s a total win for hot days, lunch boxes, or whenever you’re doing an Asian-ish spread. I see myself making this A LOT this summer!', 'https://www.recipetineats.com/tachyon/2025/11/Green-ginger-noodles_4.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.667, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)","350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)"]},{"ingredients":["4 cups (lightly packed) green onion (, cut into ~1.25cm / 1/2\" pieces (5 - 6 BIG stems!))","1/4 cup roughly chopped ginger (, ~ 4mm / 1/6\" pieces)","2 garlic cloves (, roughly chopped)","2 tbsp rice vinegar","2 tbsp water","2 tbsp light soy sauce (, or all-purpose soy sauce (not dark soy sauce - Note 2))","1 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp white pepper (, or black)","1/3 cup grapeseed oil (, or other neutral flavoured oil (vegetable, canola etc))"],"purpose":"Ginger shallot sauce (Note 3)"},{"ingredients":["Sriracha - use as much as you dare!","1/4 cup crispy shallots (store bought)"],"purpose":"For serving:"}]', '[{"description":"Blitz (pulsing) 1/4 of the green onion with ginger, garlic, vinegar and water until ginger is pureed. Then blitz in remaining green onion and soy until pesto-like. Stir in oil and salt, set aside 10 minutes. Toss with noodles and chicken, serve with crispy shallots and sriracha!","images":[],"step":1},{"description":"Ginger shallot sauce first:","images":[],"step":2},{"title":"Blitz","description":"Put 1/4 of the green onions in a tall jug (or deep bowl), top with the ginger, garlic, vinegar and water. Blitz with a stick blender until the ginger and garlic is pureed (~ 15 seconds). Add the remaining green onions and soy sauce. Blitz until all the green onion is finely chopped but don''t let it become green smoothie, it should be a pesto-like consistency. Asian pesto! :) (Note 4 if you don''t have a stick blender)","images":[],"step":3},{"title":"Stir and set aside","description":"Stir in the oil, salt and pepper. Then set aside for 10 minutes to let the flavours meld while you rehydrate the noodles.","duration":10,"images":[],"step":4},{"description":"Toss and eat!","images":[],"step":5},{"description":"Toss the noodles with the Green Ginger Sauce first. Toss well so it coats the noodles nicely. Then add the chicken, toss well again. (If you add chicken first, too much sauce clings to it). Loosen with a touch of water if needed.","images":[],"step":6},{"title":"Warm or cold serving","description":"If serving the noodles cold, set aside for 15 minutes+ to let the noodles cool. The flavours will continue to develop. If serving warm, serve straight away.","duration":15,"images":[],"step":7},{"title":"Serve","description":"Divide between bowls, drizzled with sriracha, sprinkle with crispy shallots, eat!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["no-cook-food","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd8b34b32222', 'en', 'US', 'Italian Orzo Salad (Risoni) with Crispy Salami Bits', 'Recipe video above. The crispy salami bits are the hero here. The better bacon. Why aren''t we putting crispy salami in everything??!Tossed through a risoni/orzo salad inspired by my favourite Mega Italian Salad with lots of fresh vegetables and a good handful of cheese to keep things tasty. Excellent packed lunch, keeps well for days, love that you can eat it with a spoon. Serves 4 - 5 as a meal. Make this today, find another pasta salad for next week here!', 'https://www.recipetineats.com/tachyon/2023/07/Italian-risoni-orzo-salad_3.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tightly_packed_baby_rocket_arugula", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 400.0, "unit": "punnet of 250g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["250g / 8oz risoni / orzo pasta ( - 1 1/4 cups (Note 1))","2 tsp salt (, for cooking pasta)","2 tsp extra virgin olive oil"]},{"ingredients":["250g/ 8 oz salami slices (, chopped into 1.25 cm / 1/2\" squares (Note 2))","1 cup sliced kalamata olives (1 x 220g/7oz jar) - or other olives or briny things (Note 4)","2 tightly packed cups baby rocket / arugula (, torn by hand)","400g/ 14oz cherry tomatoes (, quartered (2 1/2 cups))","1 large green capsicum (, cut into 1.25cm / 1/2\" squares)","1/2 red onion (, finely diced)","1 1/2 cups (tightly packed) colby cheese (, shredded into short strands (Note 5))"],"purpose":"Salad add-ins (Note 2):"},{"ingredients":["1/3 cup extra virgin olive oil","3 tbsp red wine vinegar (or white wine vinegar, sub apple cider vinegar)","1 garlic clove (, crushed using garlic press or grated using microplane)","1 tsp dried basil","1/4 tsp red chilli flakes (optional)","1 tsp dried oregano","1/2 tsp sugar","1 tsp cooking/kosher salt"],"purpose":"Italian dressing:"}]', '[{"title":"Cook pasta","description":"Bring a large pot of water to the boil. Add salt and risoni/orzo, then cook per packet directions (usually ~10 minutes). Drain in colander, rinse, shake off excess water well. Transfer to large bowl. Toss with the olive oil then let cool.","images":[],"step":1},{"title":"Dressing","description":"Shake in a jar.","images":[],"step":2},{"title":"Crispy salami","description":"Put salami in cold large non-stick pan, with no oil. Turn onto medium high - as the pan heats up, the fat will melt so it cooks in its own fat. Cook for 3 - 5 minutes, stirring regularly, until light golden. Drain on paper towels. It will crisp as it cools.","duration":4,"images":[],"step":3},{"title":"Toss","description":"Set aside 1/3 of the salami for topping. Put all remaining salad ingredients in with the risoni. Toss. Pour over dressing. Toss, toss, toss!","images":[],"step":4},{"description":"Serve! Tumble into serving bowl. Sprinkle with remaining salami. Divide between bowls. Eat with spoon! Best eaten at room temp, not fridge cold (can taste flavours better).","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dfecc1db1a8c', 'en', 'US', 'Smoked Sausage and Rice - easy one pot dinner!', 'Recipe video above. The smoked sausage is the trick here to get great flavour into this quick one pot dinner. Tastes like Jambalaya, minus the cajun flavours, and much faster to make. Everybody loves this!I used kransky sausages but you can use any smoked sausages you want, including chorizo. You can even use raw sausages - see Note 1! Also feel free to use other vegetables - anything that can hold up to 20 minutes on the stove.', 'https://www.recipetineats.com/tachyon/2021/08/One-Pot-Sausage-and-Rice_74.jpg', 10, 30, 40, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.01, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.007, "unit": "jar of 40g"}}, {"id": "ing_white_rice", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","5 garlic cloves (, finely minced)","2 onions (medium), chopped (or 1 large)","1 yellow capsicum (, cut into 1.5cm / 1\" squares)","1 red capsicum (, cut into 1.5cm / 1\" squares)","400 g/ 14oz (~3) kransky or other smoked sausages (, sliced 0.5cm thick / 1/4\" thick)","3/4 tsp salt","1/2 tsp pepper","3/4 tsp smoked paprika (sub normal paprika)","1 1/2 cup long grain white rice (, uncooked (Note 2 other rices))","2 1/2 cups chicken stock/broth (, low sodium (or veg stock))","2 cups frozen peas (, thawed)","2 tbsp parsley (, chopped (optional))"]}]', '[{"title":"Cook sausage","description":"Heat 2 tbsp oil in a large heavy based pot over medium high heat. Add sausages and cook until golden. Remove with a slotted spoon.","images":[],"step":1},{"title":"Cook onion and garlic","description":"Add remaining 1 tbsp oil. Add garlic and onion, cook for 2 minutes. Add capsicum and cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":2},{"title":"Add rice and liquid","description":"Add rice, chicken stock, paprika, salt, pepper and the sausage. Stir, bring to boil, then reduce heat to low so it''s simmering very gently.","images":[],"step":3},{"title":"Cover and cook","description":"Cover with lid, cook 20 minutes.","images":[],"step":4},{"title":"Add peas and rest","description":"Remove pot from stove. Working quickly, remove lid, add peas, then quickly put the lid back on. Rest 10 minutes - the residual heat with cook the peas.","images":[],"step":5},{"title":"Fluff and serve","description":"Add parsley. Use a fork to fluff the rice. Serve immediately!","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76ee601a8aed', 'en', 'US', 'Nagi''s Big, Easy Pasta Salad', 'Recipe video above. This is the big-batch pasta salad I make when I''m short on time. The trick that puts this into guest-serving territory is to toss the hot, freshly cooked pasta in the dressing. You will be shocked how much flavour it absorbs!Do this, and it''s delicious no matter what you add in. My combination is the bare minimum that delivers everything I seek in a pasta salad. There''s no need to add a gazillion ingredients!Workflow - Chop the veg and make the dressing while the pasta is cooking. This will cut down active cook/prep time to 15 minutes.', 'https://www.recipetineats.com/tachyon/2024/08/Big-easy-pasta-salad_2.jpg', 10, 15, 65, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_feta_cheese", "quantity": {"value": 200.0, "unit": "block of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["500g/ 1 lb bow tie pasta (farfalle) (, or other short/medium pasta (Note 1))"]},{"ingredients":["2 cucumbers (, halved lengthways and finely sliced (~17cm/7\" long, sliced 2mm / 1/16\", I use a mandolin))","3 cups (500g) cherry or grape tomatoes (, halved (or chop 4 regular tomatoes))","1/3 cup roughly chopped Kalamata olives (3/4 cup whole pitted or 1/2 cup sliced, then chop)","200g/ 7oz Greek feta (, cut into 6mm / 1/4\" batons (they will crumble a bit, this is good))","1 packed cup basil leaves (, torn by hand (Note 2 for alternatives))"],"purpose":"Add-ins (7 cups \"anything\" – Note 2)"},{"ingredients":["1/2 cup extra virgin olive oil","1/3 cup apple cider vinegar (Note 3)","2 garlic cloves (, minced using garlic press or very finely minced using a knife)","2 tsp dijon mustard (can omit)","2 tsp honey (sub maple syrup or 1 tsp sugar, Note 4)","1 1/2 tsp Italian herbs mix (Note 5)","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Dressing"}]', '[{"description":"Summary directions","images":[],"step":1},{"description":"Cook pasta until soft, toss with 2/3 Dressing, cool. Toss with everything else except basil, then add basil. Serve!","images":[],"step":2},{"description":"Full directions","images":[],"step":3},{"title":"Dressing","description":"Shake the Dressing ingredients in a large jar. It should be sharp, the flavour mellows once tossed.","images":[],"step":4},{"title":"Cook pasta until soft","description":"Bring a large pot of salted water to the boil. Cook the pasta until it is very soft, about 2 - 3 minutes longer than the time on the packet but taste to check because packet directions have been known to lie! Pasta firms up when it''s cold (nobody likes hard, cold pasta!), so cook the pasta until extra soft.","images":[],"step":5},{"title":"Flavour soak","description":"Drain the pasta very well, shaking off excess water. Transfer into a large bowl. Give the Dressing a good shake then pour over about two-thirds. Toss well, then leave the pasta to soak up the dressing as it cools (~40 minutes).","images":[],"step":6},{"title":"Toss","description":"Add the tomato, cucumber, feta and olives. Pour over the remaining Dressing. Toss well. Add basil, toss again.","images":[],"step":7},{"title":"Serve","description":"Tumble into big serving bowl. Dig in!","images":[],"step":8}]', '["gluten","mustard"]', '["vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","summer","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3a487f89354', 'en', 'US', 'Pasta Primavera', 'Recipe video above. This is the Pasta Primavera recipe made famous by Le Cirque restaurant in NYC. It was first published in a magazine in the 1970''s! This is an excellent big creamy pasta fix with less guilt thanks to a ton of vegetables. The trick here is timing so that all the vegetables finish cooking to tender-crisp perfection at the same time. Don''t skip the pine nuts. It''s the signature finishing touch.Counting calories? See note 1 on how to lighten the dish.', 'https://www.recipetineats.com/tachyon/2022/10/Pasta-Primavera-recipe_9.jpg', 15, 20, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 0.075, "unit": "jar"}}]', '[{"ingredients":["300g / 10 oz linguine (fettucine, or other long and flat pasta, Note 1)"]},{"ingredients":["150g / 5oz white mushrooms (, sliced 0.4cm / 1/6\" thick (~8 pieces))","1/2 large zucchini (, cut into 0.5cm / 0.2\" rounds (100g/4 oz piece))","1 bunch broccolini","1 1/2 cup snow peas (~10 pieces, 75g/2.5oz)","1 bunch green asparagus (~8 to 10)","1 cup green peas (, defrosted)","10 cherry tomatoes (, cut in half)","2 garlic cloves (, finely minced)"],"purpose":"Vegetables (Note 2):"},{"ingredients":["5 tbsp / 75 g unsalted butter","1 cup thickened / heavy cream (Note 3)","1/2 cup Parmigiano reggiano (, finely grated (sub regular parmesan, Note 4))"],"purpose":"Cream sauce:"},{"ingredients":["3 tbsp extra virgin olive oil","1/3 cup pasta cooking water (, scoop out just before draining (Note 6))","1 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 cup fresh basil leaves (, finely sliced (Note 5))","2 tbsp pinenuts (, toasted (Note 7))"],"purpose":"Cooking:"}]', '[{"description":"Cut vegetables:","images":[],"step":1},{"title":"Broccolini","description":"Cut off florets then cut in half lengthwise. Then slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":2},{"title":"Snow peas","description":"Remove the tough string running down the \"seam\" of the pea. Stack several peas and slice on the diagonal about 1cm / 0.4\" wide.","images":[],"step":3},{"title":"Asparagus","description":"Snap the base off the asparagus, it will naturally break where the woody stem stars. Cut tips off, leave whole and set aside. Slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":4},{"description":"Melt butter in a saucepan over medium-high heat. Add cream and Parmigiano reggiano. Stir, and once the cream starts simmering gently, stir until the cheese melts then take it off the stove and set aside.","images":[],"step":5},{"description":"Bring a large pot of water to the boil over high heat. Add 1 tablespoon of salt and add the pasta. Cook for the time per the packet minus 1 minute. Meanwhile, cook vegetables.","images":[],"step":6},{"title":"Reserve pasta water","description":"Just before draining the pasta, scoop out a mug of pasta cooking water and set aside. Drain the pasta.","images":[],"step":7},{"description":"Cook:","images":[],"step":8},{"title":"Mushrooms","description":"Heat half the olive oil in a large skillet over high heat. Cook mushrooms for 4 minutes until golden, remove to a plate.","duration":4,"images":[],"step":9},{"title":"Veg","description":"Heat remaining oil in the same skillet. Cook broccolini, snow peas and asparagus for 2 minutes. Add zucchini, tomato, green peas, garlic, salt and pepper. Cook for a further 3 minutes. Add mushroom back in, toss, then remove from heat.","duration":2,"images":[],"step":10},{"description":"Toss! Return pasta into the now-empty pot. Add vegetables, cream sauce and 1/3 cup pasta water. Toss over medium heat using 2 wooden spoons until the sauce thickens and clings to the pasta strands rather than pooling in the base of the pot, about 1 to 2 minutes. (If at any stage the pasta gets too thick, add a splash more pasta water and toss on stove).","images":[],"step":11},{"title":"Basil & pine nuts","description":"Quickly toss through basil. Divide between 4 bowls. Sprinkle with pine nuts. Devour immediately!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d5ee74355d38', 'en', 'US', 'Orecchiette Sausage Pasta in Creamy Tomato Sauce', 'Recipe video above. Orecchiette has one big thing going for it that other pastas do not: its cup shape makes it the perfect vehicle to hold special pasta sauces. The creamy tomato sausage pasta sauce featured in this recipe is orecchiette worthy. Decadent? Yes. Have salad tomorrow!', 'https://www.recipetineats.com/tachyon/2020/06/Orecchiette-Sausage-in-Creamy-Tomato-Sauce_5.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.012, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_kale", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["400g / 14oz orecchiette pasta (or other pasta)","1 tbsp olive oil","2 garlic cloves (, minced)","500g / 1lb Italian pork sausages (, meat squeezed out of their casings (see video, Note 1))","1/4 cup white wine (, anything not too sweet (sub water))","1 cup tomato passata (called \"tomato puree\" in US, Note 2)","3/4 cup cream (, heavy/thickened)","3/4 cup milk (any fat %)","1/3 cup parmesan (, finely grated)","1 tsp Italian herbs (Note 3)","1/4 tsp red pepper flakes (chilli flakes)","1/4 tsp each salt and pepper","3 cups (packed) kale leaves (, torn into bite size pieces (or baby spinach, swiss chard, Tuscan kale etc))","Parmesan (, for serving)"]}]', '[{"description":"Bring a large pot of water to the boil and cook pasta according to packet directions MINUS 1 minute. Just before draining, scoop out 1 cup of pasta cooking water and set aside. (Note 4)","images":[],"step":1},{"description":"Heat oil in a very large skillet over high heat. Add garlic and cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add sausage meat and cook, breaking it up as you go, until there are some little golden bits - about 4 minutes.","images":[],"step":3},{"description":"Add wine and cook, scraping the bottom of the skillet to remove the golden bits, and allow wine to evaporate - the winey smell will disappear.","images":[],"step":4},{"description":"Add remaining ingredients except kale. Stir well, bring to simmer then turn stove down to low and simmer gently for 2 minutes to bring all the flavours together.","duration":2,"images":[],"step":5},{"description":"Add pasta and kale. Toss well for 1 minute to coat pasta well with the sauce - it will thicken. If the sauce gets too thick, use the reserved pasta cooking water to loosen it up (Note 4).","duration":1,"images":[],"step":6},{"description":"Serve immediately, garnished with freshly grated parmesan","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["pasta-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dbf6c42c0e1d', 'en', 'US', 'Pizza Capricciosa', 'Recipe video above. Topped with artichokes, ham, olives and mushrooms with a tomato pizza sauce, this is a pizza that''s almost uniquely Australian that we are VERY fond of! Though you can find it in some parts of Italy, you won''t see it in many other places around the world.I just love the combination - and that you can be generous with the toppings without overwhelming the pizza. Cook times:Classic yeast pizza dough - 5 to 6 hrs dough rising (total) | 10 min prep | 10 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 10 min cookStore bought pizza dough - 5 min prep | 10 min prep | 10 min cook** To make more than one pizza (who ever makes just one??!) slide the servings scaler **', 'https://www.recipetineats.com/tachyon/2024/05/Pizza-Capricciosa_8.jpg', 10, 10, 20, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.001, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 2.0, "unit": "pack of 125g"}}, {"id": "ing_artichokes", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_shaved_leg_ham", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought (30cm/12\")"],"purpose":"Pizza base – choose one (Note 1):"},{"ingredients":["1/4 cup tomato paste","1/4 tsp cooking salt / kosher salt","1/2 tsp white sugar","1/2 tbsp water","1/2 garlic clove (, finely minced (optional))","1/8 tsp EACH dried parsley , basil and oregano (optional)"],"purpose":"Pizza sauce"},{"ingredients":["1 1/3 cup (130 g) mozzarella cheese, freshly shredded (Note 2)","1/2 cup artichokes (from a jar, preferably oil, drained & sliced (Note 3))","3 button mushrooms (, cut into 3 mm / 1/8\" slices)","2/3 cup (70 g) shaved leg ham (, torn into pieces (thinner is better) (Note 4))","1/4 cup sliced kalamata olives (or black olives)"],"purpose":"Capricciosa topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (both fan and standard). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Pizza sauce","description":"Mix the ingredients in a small bowl then set aside.","images":[],"step":2},{"title":"Pizza base","description":"Make and stretch out your chosen pizza base (no rolling pin!), stretch onto a pizza pan or baking tray per the directions in your chosen pizza base. (Note 4 for pizza stone)","images":[],"step":3},{"title":"Top","description":"Spread the pizza sauce on the pizza, leaving a 1 cm/1/2\" border along the edge. Sprinkle with cheese first, then drape the ham randomly across the surface, sprinkle with olives, artichoke slices and mushrooms. (If using the no-yeast pizza base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, turning after 4 minutes, or until the the cheese has golden spots and the crust is crispy. Cut and eat, stat!","duration":11,"images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Italian"],"categories":["pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1221c3547c57', 'en', 'US', 'Garlic cheese pizza', 'Recipe video above. No visit to your favourite pizzeria start without garlic cheese pizza! My best garlic pizza calls for both parmesan and mozzarella cheese, and to infuse olive oil with garlic (it only takes 10 minutes). It''s outrageously good!Cook times:Classic yeast pizza dough - 5 to 6 hours dough rising (total) | 10 min prep | 8 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 8 min cookStore bought pizza dough - 5 min prep | 10 min oil steeping | 8 min cook', 'https://www.recipetineats.com/tachyon/2023/05/Garlic-cheese-pizza_9.jpg', 10, 8, 18, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.02, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought"],"purpose":"Pizza 30cm/12\" base – your choice (Note 1):"},{"ingredients":["2 tbsp extra virgin olive oil","2 tsp garlic (2 - 3 large cloves), crushed using garlic press or make paste using side of knife - Note 2)","1/8 tsp cooking salt / kosher salt (or table salt, or double qty for salt flakes)","1 cup mozzarella cheese (tightly packed cup), shredded using box grater (Note 3 on pre-shredded)","1/2 cup parmesan (tightly packed cup), shredded using box grater (Note 3)"],"purpose":"Garlic pizza topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Garlic infused oil","description":"Mix olive oil and garlic in a small bowl. Set aside to infuse with flavour for 10 minutes.","duration":10,"images":[],"step":2},{"title":"Pizza base","description":"Make and roll out chosen pizza base, stretch onto pan.","images":[],"step":3},{"title":"Top","description":"Spread oil (and all garlic) onto the base, leaving the crust baked. Sprinkle with salt, parmesan then mozzarella. (If using no-yeast base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"description":"Bake 8 minutes, turning after 4 minutes, or until the the cheese has golden spots. Cut and eat, stat!","images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian"],"categories":["pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_934f113e6576', 'en', 'US', 'Pork Tenderloin with Honey Garlic Sauce', 'Recipe VIDEO above. Tender, succulent pork fillet seasoned with a rub, seared until golden then baked in a Honey Garlic Sauce until sticky on the outside and juicy on the inside. Simply incredible! (And really, it''s SIMPLE!)', 'https://www.recipetineats.com/tachyon/2019/05/Honey-Garlic-Pork-Tenderloin_1.jpg', 10, 25, 35, 5, '[{"id": "ing_pork", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.002, "unit": "jar of 500g"}}]', '[{"ingredients":["2 pork tenderloin (pork fillet), 500g/1lb each (Note 1)","1 1/2 tbsp olive oil (or butter)","3 garlic cloves (, very finely chopped)"]},{"ingredients":["1/2 tsp garlic powder","1/2 tsp paprika","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Pork Tenderloin Rub:"},{"ingredients":["3 tbsp cider vinegar (Note 2)","1 1/2 tbsp soy sauce, light or all purpose (Note 2)","1/2 cup honey (or maple syrup)"],"purpose":"Honey Garlic Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix Sauce ingredients together.","images":[],"step":2},{"description":"Mix Rub ingredients then sprinkle over the pork.","images":[],"step":3},{"description":"Heat oil in a large oven proof skillet (Note 3) over high heat. Add pork and sear until golden all over.","images":[],"step":4},{"description":"When pork is almost seared, push to the side, add garlic and cook until golden.","images":[],"step":5},{"description":"Pour sauce in. Turn pork once, then immediately transfer to the oven.","images":[],"step":6},{"title":"Roast 15","description":"18 minutes or until the internal temperature is 68C / 155F (Note 4).","images":[],"step":7},{"description":"Remove pork onto plate, cover loosely with foil and rest 5 minutes.","images":[],"step":8},{"description":"Place skillet with sauce on stove over medium high heat, simmer rapidly for 3 minutes until liquid reduces down to thin syrup.","duration":3,"images":[],"step":9},{"description":"Remove from stove, put pork in and turn to coat in sauce.","images":[],"step":10},{"description":"Cut pork into thick slices and serve with sauce!","images":[],"step":11}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b3c76a262', 'en', 'US', 'Creamy Garlic Prawns (Shrimp)', 'Recipe video above. Creamy Garlic Prawns are your favourite garlic prawns … PLUS a creamy garlic sauce! A few simple tricks give a leg-up to the sauce for a result that''s a cut above your basic recipes: deglaze the pan with a little white wine, a splash of chicken stock and sprinkle of parmesan. Because plump, sweet prawns demand the BEST sauce!', 'https://www.recipetineats.com/tachyon/2020/09/Creamy-Garlic-Prawns_7.jpg', 5, 12, 17, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb peeled prawns/shrimp (, large/jumbo best (Note 1))","1 garlic cloves (, finely minced)","1 tbsp olive oil","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Garlic marinated prawns:"},{"ingredients":["15g / 1 tbsp unsalted butter"],"purpose":"Cooking prawns:"},{"ingredients":["2 garlic clove (, finely minced)","15g / 1 tbsp unsalted butter","1/4 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup heavy/thickened cream","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tbsp parsley (, finely chopped)"],"purpose":"Creamy garlic sauce:"}]', '[{"description":"Marinate Prawns:","images":[],"step":1},{"description":"Place prawns, garlic, oil and pepper in a bowl. Toss to coat, set aside 20 minutes if time permits (no longer).","images":[],"step":2},{"description":"Stir through salt just prior to cooking.","images":[],"step":3},{"description":"Cook prawns:","images":[],"step":4},{"description":"Melt 15g / 1 tbsp butter in a large skillet over medium high heat. Add half the prawns and cook for 1 minute on each side, then remove.","duration":1,"images":[],"step":5},{"description":"Repeat with remaining prawns (you shouldn''t need more butter), then remove. Scrape out excess remaining garlic from pan and add to cooked prawns.","images":[],"step":6},{"description":"Add butter into skillet and let it melt. Add garlic and stir for 30 seconds or until light golden.","duration":0.5,"images":[],"step":7},{"description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the winey smell is gone.","images":[],"step":8},{"description":"Add chicken stock and reduce until mostly gone and just a thin layer remains on base of skillet.","images":[],"step":9},{"description":"Add cream, then simmer on medium heat for 2 minutes until reduced and slightly thickened.","duration":2,"images":[],"step":10},{"description":"Stir through parmesan, then add the prawns back in. Taste sauce and see if more salt and pepper is needed.","images":[],"step":11},{"description":"Serve sprinkled with parsley, over mashed potato or something to soak up that fabulous sauce!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_138af84f0415', 'en', 'US', '8 minute Lebanese Pizzas (Lahmacun!)', 'Recipe video above. Invented in pursuit of more interesting ways to use chicken mince, this is a SOS take on traditional manakish Lebanese pizzas made with flatbreads topped with a thin layer of meat, commonly known by the Turkish name lahmacun. Astoundingly fast to make, and extremely versatile, think of this recipe as a blueprint rather than a rule book. Use any ground meat, add shredded vegetables - and topping options are endless! Don''t skip the feta and olive oil for toppings. It really makes it. :)', 'https://www.recipetineats.com/tachyon/2025/01/Quick-Lebanese-pizza_1.jpg', 5, 3, 8, 1, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.125, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 0.013, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 x ~30cm/12\" Lebanese bread (, (sub other thin flatbreads, Note 1))"]},{"ingredients":["125g / 4 oz chicken mince (ground chicken) (Note 2)","2 tsp tomato paste","1 tsp Baharat spice mix (aka Lebanese 7 spice) (Note 3 subs)","1/2 tsp paprika (, sweet (or smoked))","1 garlic clove (, crushed using garlic press)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1 tbsp finely chopped parsley (or coriander/cilantro, totally optional (sub 1 tsp dried oregano))","1 1/2 tbsp extra virgin olive oil (, for cooking (or regular olive oil))"],"purpose":"Spiced Chicken Mince spread:"},{"ingredients":["Extra virgin olive oil","2 tbsp Danish feta or goats cheese (, crumbled (or regular feta))"],"purpose":"Toppings – essential! (Note 4)"},{"ingredients":["Lemon juice (, just a light drizzle)","Dried chilli flakes / red pepper flakes","~1 tbsp toasted pine nuts (, roughly chopped (sub pistachios, almonds, sesame seeds))","1 tsp finely chopped parsley (or coriander/cilantro)"],"purpose":"Toppings – optional (makes it even better!)"}]', '[{"description":"Trim bread to fit pan, mix filling, smear on bread. Heat oil on high, pan fry 90 seconds meat side down, then bread side 90 seconds until crispy. Top, cut, eat!","images":[],"step":1},{"description":"Use a large 30cm/12\" non-stick pan. If needed, use scissors to cut one side of the Lebanese bread so it fits in your pan (Note 1 & 5)","images":[],"step":2},{"description":"Mix the Chicken Spread ingredients in a bowl. Spread all across the surface of one side of the bread like peanut butter, smearing and pressing it onto the bread well so it sticks. Use it all! (It will be a fairly thin layer.)","images":[],"step":3},{"title":"Cook meat side","description":"Heat 1 tablespoon of oil in the pan over high heat. Place the bread in meat side down and cook for 90 seconds, pressing down lightly to encourage colour. The meat will stick to the bread!","duration":1.5,"images":[],"step":4},{"title":"Crisp bread","description":"Turn with tongs (there should be some golden patches) and cook the bread side for 90 seconds until golden and crispy (lower heat if browning too quickly).","duration":1.5,"images":[],"step":5},{"title":"Toppings","description":"Slide onto cutting board, sprinkle with feta, drizzle with extra virgin olive oil. Sprinkle with other toppings you choose. Cut into 8 like pizza, enjoy!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_665ad93fc3ad', 'en', 'US', 'Cowboy Butter - for steak, and so much more!', 'This goes phenomenally well with steak (try it with Tomahawk!), though I''ve been using it with everything from chicken to toast, vegetables to hot steamed rice.Most recipes just mix raw garlic in, but honestly, doing a mini sauté is so worth it - the garlic flavour is much nicer.', 'https://www.recipetineats.com/tachyon/2025/05/Cowboy-butter.jpg', 5, 1, 6, 2, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.013, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened, divided)","1 large garlic clove (, finely minced (1 tsp) - knife best (Note 1))","1 tbsp Dijon mustard","1 tsp smoked paprika (sub regular paprika)","1 tsp chilli flakes / red pepper flakes","1/4 tsp cooking salt / kosher salt (halve for table salt)"]}]', '[{"title":"Sauté garlic","description":"In a small frying pan, melt 1 tbsp (15g) of butter over medium heat until it starts foaming then add the garlic and cook for 30 seconds while stirring until it becomes very, very light golden. Remove from the stove and let it cool for 3 minutes (the garlic will go more golden).","duration":0.5,"images":[],"step":1},{"title":"Mix","description":"Put the rest of the butter and remaining ingredients in a small mixing bowl. Pour the garlic butter over. Mix until combined.","images":[],"step":2},{"description":"Serve with steak! It''s also excellent with other cooked meats, seafood and even vegetables.","images":[],"step":3},{"description":"How to use Cowboy Butter:","images":[],"step":4},{"description":"I like to use it softened as it melts thicker over hot steak. You can also melt gently then dip bites of steak in, or roll it into a log using cling wrap, refrigerate then cut slices off on an as-need basis (you can place the coins on the steak to let it melt).","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0cb49661606c', 'en', 'US', 'Christmas Leftovers Toasted Bread Bowl', 'Recipe video above. This isn''t really a recipe, it''s more of an idea you can make your own. A way to completely transform leftovers into an epic sandwich for sharing! Use leftover ham, cooked meats, roasted veg, cheese platter leftovers. Imagine the possibilities! Great served fresh AND travels well!', 'https://www.recipetineats.com/tachyon/2018/12/Bread-Bowl-Sandwich-Christmas-Leftover-Ham-Turkey_6.jpg', 15, 30, 45, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_ham_turkey_and_other_meat_slices", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_antipasto_things", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 round or oval bread loaf (Note 1)","300 g / 10 oz ham, turkey and other cooked meat slices","1 cup roughly chopped antipasto things (olives, sun dried tomato, chargrilled peppers, artichokes, feta etc)","4 - 6 slices cheese of choice (I used Swiss in the video)","3 big handfuls baby spinach (~75g / 2.5oz)"]},{"ingredients":["50 g / 3 tbsp salted butter (, melted)","1 garlic clove (, minced)"],"purpose":"Garlic Butter:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix butter and garlic.","images":[],"step":2},{"description":"Cut the top off the bread loaf. Pick out bread from the loaf and the lid, leaving a wall and floor about 1.5cm / 3/5\" thick.","images":[],"step":3},{"description":"Place bread on a large sheet of foil on a baking tray.","images":[],"step":4},{"title":"Dab / brush inside with butter. Layer with","description":"half spinach, turkey, antipasto things, remaining spinach, ham, cheese.","images":[],"step":5},{"description":"Tuck flappy bits inside the loaf, top with lid.","images":[],"step":6},{"description":"Brush with butter all over. Wrap with foil.","images":[],"step":7},{"title":"Weigh down with something flat and heavy","description":"cast iron skillet is ideal.","images":[],"step":8},{"description":"Bake for 20 minutes. Remove skillet and foil.","duration":20,"images":[],"step":9},{"description":"Bake for a further 10 minutes until golden.","images":[],"step":10},{"description":"Cut into thick slices and serve immediately!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_213b9d603866', 'en', 'US', 'Crispy marinated baby octopus', 'Recipe video above. Here''s an easy, outrageously delicious way to cook baby octopus: simmered until tender, marinated in bold Mediterranean flavours, seared until crispy. Add a Greek Salad, bread for mopping and a glass of chilled wine for the perfect summer meal!2 kg / 4 lb raw baby octopus will serve 5 to 6 people as a main - it shrinks quite substantially. It might even be better the next day, so look forward to leftovers!', 'https://www.recipetineats.com/tachyon/2023/02/Crispy-baby-octopus_3.jpg', 10, 75, 85, 6, '[{"id": "ing_baby_octopus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.024, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 0.06, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["2 kg / 4 lb baby octopus (, rinsed (Note 1))"]},{"ingredients":["4 litres / quarts water","1 onion (, halved, skin on)","6 garlic cloves (, smashed (Note 2))","1 tsp black peppercorns (sub 1/2 tsp ground pepper)","2 tsp cooking salt (kosher salt)","3 tbsp lemon juice (or apple cider vinegar)","3 parsley stems (with leaves)","2 bay leaves (, fresh or dried)"],"purpose":"Braising liquid:"},{"ingredients":["1/2 cup extra virgin olive oil","6 garlic cloves (, very finely minced (or use garlic press))","2 tsp lemon zest (one large lemon)","2 tbsp lemon juice","1 tsp dried red chilli flakes ((red pepper flakes), optional)","1/2 tsp each cooking/kosher salt and black pepper"],"purpose":"Marinade:"},{"ingredients":["1 tbsp canola oil (for BBQ or large skillet)","2 tsp parsley (, finely chopped (optional))","1 large red chilli (, finely sliced (optional))","Lemon wedges (highly recommended)"],"purpose":"Cooking & serving:"}]', '[{"title":"Braising","description":"Put all the braising liquid ingredients in a large pot and bring to a boil over high heat. Add octopus, bring back up to the boil, then reduce the heat to low so the water is simmering very, very gently. Scoop off and discard scum off the surface when it accumulates.","images":[],"step":1},{"description":"Braise 1 hour until tender, first checking at the 45 minute mark, or until octopus is tender (take a little nibble to check!).","images":[],"step":2},{"description":"Drain octopus in a colander. Pick out and discard the bay leaves, onion etc. Transfer octopus into a bowl.","images":[],"step":3},{"title":"Marinate","description":"Mix marinade ingredients in a bowl. Pour over the octopus (while still hot). Toss, allow to fully cool, cover with cling wrap then marinate overnight in the fridge. (Note 4)","images":[],"step":4},{"title":"Cook until crispy (BBQ)","description":"Heat a BBQ hot plate on medium high until hot. Spread oil across the hot plate. Use tongs to transfer the octopus onto the BBQ (leave residual oil behind), spread out and cook for 3 to 5 minutes, rotating as needed to brown all over, and most especially ensuring the legs are golden and crispy. (Stove - use a large skillet, cook in 2 or 3 batches).","duration":4,"images":[],"step":5},{"title":"Serve","description":"Pile octopus on a plate. Sprinkle with parsley and chilli, add lemon wedges. EAT and be happy! Serve with bread for mopping or see Note 4 for crushed potatoes pictured in post dressed with residual marinade.","images":[],"step":6}]', '["shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Mediterranean","Western"],"categories":["seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d7a56f7c22f', 'en', 'US', 'Vegetable Beef Soup (Fall apart beef!)', 'Recipe VIDEO above. Melt-in-your-mouth chunks of beef, vegetables and potato in a hearty herb infused broth. You''ll love how the soup broth is slightly thickened and the extra flavour the wine or beer adds to the soup (the secret ingredient!). 20 minutes active cook/prep.', 'https://www.recipetineats.com/tachyon/2019/05/Vegetable-Beef-Soup_3.jpg', 15, 110, 125, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1.5 tbsp olive oil (, separated)","500g/1 lb stewing beef (, cut into 1.75cm / 2/3\" cubes (Note 1))","1/2 tsp salt and pepper","1 onion (, chopped)","3 garlic (, minced (1 tbsp))","2 celery (, cut into 0.8 cm / 1/3\" slices)","3 carrots (, cut into 0.5 cm / 1/5\" thick slices (halve larger ones))","4 tbsp flour","2 1/2 cups (625ml) beef broth/stock (, low sodium)","1 1/2 cups (375ml) dry red wine, Guinness beer or stout (Note 2)","1.5 cups (375ml) water","2 tbsp tomato paste","2 bay leaves","1 tsp thyme dried","1 cup frozen peas","2 potatoes ((any), cut into 1.5cm / 2/3\" cubes)"]},{"ingredients":["1 tbsp (15g) butter or oil","200g/ 6oz small mushrooms (, quartered or halved)"],"purpose":"Buttery mushrooms (optional):"}]', '[{"description":"Heat 1 tbsp oil until very hot in a large, heavy based pot over high heat.","images":[],"step":1},{"description":"Pat beef dry with paper towels, then sprinkle with salt and pepper.","images":[],"step":2},{"description":"Brown beef aggressively in 2 or 3 batches, adding more oil if needed. Remove browned beef into a bowl.","images":[],"step":3},{"description":"If pot looks dry, add a touch more oil.","images":[],"step":4},{"description":"Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add carrot and celery, cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":6},{"description":"Stir in flour, then slowly pour in beef broth while constantly stirring.","images":[],"step":7},{"description":"Add beer, water, tomato paste, bay leaves and thyme, stir well. Then add the beef back in.","images":[],"step":8},{"description":"Cover, adjust heat to medium low so it''s bubbling gently. Simmer 1 hr 15 min or until beef is pretty tender.","images":[],"step":9},{"description":"Add potatoes and peas, simmer for a further 20 minutes without the lid. Add cooked mushrooms in the last 5 minutes.","images":[],"step":10},{"description":"The soup is ready when the potatoes are cooked and beef is very tender (see video).","images":[],"step":11},{"description":"Adjust salt and pepper to taste (I like lots of pepper in this!).","images":[],"step":12},{"description":"Ladle into bowls. Sprinkle with parsley and serve with crusty bread if desired. Try quick Cheesy Garlic Bread or super easy Irish Soda Bread!","images":[],"step":13},{"description":"Buttery Mushrooms (optional):","images":[],"step":14},{"description":"Melt butter in a large skillet over medium high heat. Add mushrooms and cook for 5 minutes until browned. Sprinkle with salt and pepper.","duration":5,"images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["slow-cooker-recipes","soup-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5165fdd50aa0', 'en', 'US', 'Cold Corn Soup for Summer', 'Recipe video above. Corn Soup is one of those rare soups best served cold. For all those days when it''s too hot to even contemplate eating hot food!Sweet summer corn is the star here that makes a simple corn stock that drives home the corn flavour. If you can''t get good fresh corn where you are, use frozen corn instead but prop the flavour up with chicken or vegetable stock.Serve cold as a canape in shot glasses, tea cups as a starter, or bowls as a meal. Serves 6 as a meal.', 'https://www.recipetineats.com/tachyon/2021/06/Cold-Corn-Soup_0.jpg', 15, 45, 60, 6, '[{"id": "ing_corn", "quantity": {"value": 0.02, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_eek", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.8, "unit": "carton of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 ears yellow corn (Note 1 for frozen corn)","3 litres / 3 quarts water"],"purpose":"Corn stock:"},{"ingredients":["100g/ 7 tbsp unsalted butter","2 garlic cloves (, chopped)","1/2 onion (, finely sliced)","1 celery stalk (, sliced)","1/2 leek (, white part only, finely sliced (sub 1/2 onion))","1 tsp salt (, cooking/kosher salt, plus more as needed)","1 cup cream (, full fat)"],"purpose":"Corn soup:"},{"ingredients":["2 sprigs of thyme","1 bay leaf (, preferably fresh otherwise dried)","1 tsp black peppercorns","1 tsp coriander seeds"],"purpose":"Herb Spice Sachet (Note 2):"},{"ingredients":["Extra corn kernels (, sautéed in butter until golden with a pinch of salt and pepper)","1/4 cup green onion (, finely sliced)"],"purpose":"Optional Garnish:"}]', '[{"title":"Cut off kernels","description":"Cut the corn kernels off the cobs and transfer to a bowl.","images":[],"step":1},{"title":"Corn stock","description":"Cut the cobs in half. Place in a large pot with the water. Bring to a boil, then reduce to medium low and simmer for 30 minutes. Strain - it should be 2 litres. If it''s much more , simmer to reduce. If less, top up with water.","duration":30,"images":[],"step":2},{"title":"Sachet","description":"Bundle the bay leaf, thyme, black peppercorns and coriander seeds loosely in a small piece of cheesecloth to create a sachet. Tie with cooking twine to secure.","images":[],"step":3},{"title":"Sauté aromatics","description":"Melt butter in a pot over medium high heat. Add onion, celery, leek and garlic. Cook for 4 - 5 minutes until soft.","duration":4.5,"images":[],"step":4},{"title":"Cook corn","description":"Add corn kernels then cook for 6 to 7 minutes.","duration":6.5,"images":[],"step":5},{"title":"Simmer","description":"Add the corn stock and the sachet. Bring it to a boil and let it simmer for 20 minutes.","duration":20,"images":[],"step":6},{"title":"Cream","description":"Add the cream and cook for 3 minutes.","duration":3,"images":[],"step":7},{"title":"Blend and sieve","description":"Remove the Sachet. Blend in batches in a blender on high speed until smooth. CAUTION! Hot liquid + tightly sealed blender lid = soup explosion! To avoid this, either cool before blending. OR remove the lid of the feeding tube in the blender lid. Cover the exposed hole with a folded tea towel as you blend hot liquid. You will see me do this in the recipe video.","images":[],"step":8},{"title":"Strain","description":"Pass through a fine sieve.","images":[],"step":9},{"title":"Adjust salt","description":"Taste and add more salt if needed.","images":[],"step":10},{"title":"Chill and serve","description":"Cool, then transfer to the fridge to chill completely. Intended to be served chilled or cool, but also great at room temperture or warm!","images":[],"step":11},{"title":"How to serve","description":"In shot glasses as a canape, tea cups as a small starter, or bowls as a meal with hunks of crusty bread. Garnish with kernels sauteed in butter with green onion slices and a drizzle of extra virgin olive oil (basil oil would be even more incredible!).","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dee5246f6808', 'en', 'US', 'Minestrone Soup', 'Recipe video above. The heartiest of all chunky soups, filled with anything your heart desires! While the add ins are endlessly customisable, stick with the soup broth recipe because I''ve made it extra tasty!* Asterix marked items can be substituted with any cookable vegetables, 6 cups in total.', 'https://www.recipetineats.com/tachyon/2020/07/Minestrone-Soup_0.jpg', 20, 45, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.004, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.2, "unit": "pack"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5oz bacon (, finely chopped)","1 onion (, chopped)","2 garlic cloves (, minced)","800g/ 28oz crushed tomato (or 700g passata)","2 cups chicken stock/broth (, low sodium)","2 cups water","3 tbsp tomato paste","2 tsp Worcestershire sauce","400g/ 14oz canned kidney beans (, drained)","1 tsp EACH salt and pepper","1 cup small pasta (, like ditalini, tiny shells, risoni/orzo, baby macaroni, alphabet or star pasta)","1/4 cup parmesan (, grated)"]},{"ingredients":["1 celery rib* (, chopped 1.5cm / 1/2\" pieces)","1 large carrot* (, peeled and diced 1.5cm / 1/2\" pieces)","1 zucchini* (, chopped 1.5cm / 1/2\" pieces)","1 potato* (, cut into 1.5cm / 1/2\" pieces (peel if needed))","100g / 3oz green beans* (, trimmed then cut into 2cm / 3/5\" lengths)","2oz/ 60g baby spinach (or frozen spinach, kale or similar - can leave out)"],"purpose":"Minestrone Vegetables (Note 1):"},{"ingredients":["More parmesan","Chopped parsley","Crusty bread for dunking!"],"purpose":"For serving – optional:"}]', '[{"description":"Heat oil over high heat in a very large pot.","images":[],"step":1},{"description":"Add bacon, cook until starting to turn golden (~2 min) then add garlic and onion.","images":[],"step":2},{"description":"Cook until onion is translucent and bacon is light golden ~ 2minutes.","images":[],"step":3},{"description":"Add carrot, celery and zucchini. Stir for 1 minute to coat in flavour.","duration":1,"images":[],"step":4},{"description":"Add crushed tomato, chicken stock, water, tomato paste, Worcestershire sauce, kidney beans, salt and pepper.","images":[],"step":5},{"description":"Stir, bring to simmer, then place lid on and adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 20 minutes, then add potato and beans.","images":[],"step":7},{"description":"Simmer 5 minutes, then add pasta. Cook for time per pasta packet MINUS 1 1/2 minutes.","images":[],"step":8},{"description":"Remove from stove, stir through parmesan and baby spinach. Taste and adjust for salt and pepper.","images":[],"step":9},{"description":"Serve, garnished with extra parmesan and a sprinkle of parsley if desired. Warm crusty bread on the side would certainly be the cherry on top!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4132fb580ca6', 'en', 'US', 'Chicken Stew (Casserole)', 'Recipe video above. This is the faster way to make a chicken stew (casserole) that''s done in an hour but tastes like it''s been simmering all day! The trick is to use boneless thigh fillets, beef instead of chicken broth, a good slug of red wine and BACON!', 'https://www.recipetineats.com/tachyon/2019/07/Chicken-Stew_5.jpg', 15, 50, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 2.0, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 350.0, "unit": "bag of 2kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 0.3, "unit": "pack"}}]', '[{"ingredients":["0.5 tbsp olive oil","150g/5oz bacon (, chopped)","750g/ 1.5lb boneless skinless chicken thighs (, cut into 3cm / 1.25\" pieces (Note 1))","1/2 tsp salt and pepper (, each)","3 garlic cloves (, minced (1 tbsp))","1 onion (, sliced)","3 carrots (, peeled, halved lengthwise, sliced 1cm / 1/3\" thick)","2 celery stalks (, sliced 1cm / 1/3\" thick)","1 1/2 cups (375ml) red wine (Note 2)","4 tbsp flour","3 cups (750ml) beef stock/broth (, low sodium (or chicken, Note 3))","400g/ 14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1/2 tsp salt and pepper (, each)","1 1/2 tsp dried thyme","2 dried bay leaves","350g/ 12 oz baby potatoes (, halved)","200g/ 6oz mushrooms (, halved (large quartered))","150g/ 5 oz green beans (, trimmed and halved)"]}]', '[{"description":"Place oil and bacon in a large heavy based casserole pot over high heat.","images":[],"step":1},{"description":"When the oil is heated and bacon releases some fat, add chicken.","images":[],"step":2},{"description":"Sprinkle with salt and pepper and cook, until chicken and bacon is browned.","images":[],"step":3},{"description":"Add garlic and onion, cook 1 minute.","images":[],"step":4},{"description":"Add celery and carrot, cook 2 minutes.","images":[],"step":5},{"description":"Add red wine, allow to simmer rapidly 2 minutes until the winey alcohol smell is gone.","images":[],"step":6},{"description":"Add flour, mix until incorporated.","images":[],"step":7},{"description":"Slowly pour in half the beef broth while stirring, then pour the rest in.","images":[],"step":8},{"description":"Add tomato, Worcestershire, thyme, bay leaves, salt, pepper.","images":[],"step":9},{"description":"Stir, add potato.","images":[],"step":10},{"description":"Cover, simmer 30 minutes.","images":[],"step":11},{"description":"Remove lid, add mushrooms and green beans. Simmer without lid* for a further 10 minutes.","images":[],"step":12},{"description":"Serve with crusty bread, sprinkled with parsley if desired!","images":[],"step":13}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f6fee28d7201', 'en', 'US', 'Sweet potato steaks', 'Recipe video above. I know the ingredients looks exorbitantly long for something I describe as "an easy way to turn sweet potatoes into a really tasty meaty dinner"! But actually, it is very straight forward. Thick slices of sweet potato roasted with a simple spice mix, then served on a bed of tahini yogurt topped with a glitter of garlic-sesame-chilli and pine nuts. It''s a fabulous flavour combination!Serve with something crunchy - toasted pita bread is my pick. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/08/Roasted-Sweet-Potato-Steaks_6a.jpg', 10, 60, 70, 2, '[{"id": "ing_sweet_potato", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.013, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.4, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.008, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.037, "unit": "jar of 40g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_pinch_of_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 gigantic sweet potato - to cut 2 x “steaks” (1.8 cm thick, 17 cm long, 7 cm wide (0.7 x 6.5 x 2.75\") - Note 1)","2 - 3 tsp olive oil"]},{"ingredients":["1 1/2 tsp smoked paprika (sub ordinary)","1/2 tsp onion powder (or more garlic powder)","1/2 tsp onion powder (or more garlic powder)","1/4 tsp cumin powder","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Spice mix:"},{"ingredients":["1 cup plain yogurt (250g)","2 1/2 tbsp tahini (Note 2)","1 1/2 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","1 1/2 tbsp eschallot (US: shallot), finely chopped (Note 3)","1 tbsp red cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp green cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp white sesame seeds"],"purpose":"Topping:"},{"ingredients":["2 tbsp pine nuts (, toasted)","2 tbsp coriander/cilantro leaves (, finely chopped)","Pinch of sumac (, optional (or paprika))","Pita or lebanese bread (, toasted (Note 5))"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Bake sweet potato","description":"Rub sweet potato steaks with oil, then sprinkle each side evenly with spice mix (don’t rub, it smears). Bake 45 - 50 minutes until potato is soft. Don’t flip.","images":[],"step":2},{"title":"Tahini yogurt sauce","description":"Whisk ingredients in a medium heat-proof bowl until mostly combined. Microwave for 20 seconds on high. Whisk again - it will be like softly whipped cream! Use warm or at room temp.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Toast pine nuts in a small pan (no oil) preheated over medium heat. Once lightly golden, remove into a bowl.","images":[],"step":4},{"title":"Topping","description":"In the same pan, heat oil (still on medium). Add all Topping ingredients and cook, stirring, until the garlic is golden. Transfer into a bowl immediately.","images":[],"step":5},{"title":"Assemble","description":"Smear most of the yogurt sauce on plate (save some for drizzling). Put sweet potato on top. Sprinkle with Topping, drizzle with yogurt sauce, then sprinkle with pine nuts, coriander and sumac. EAT with crunchy toasted flatbread!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0f1163c1c7b', 'en', 'US', 'Homemade Paneer (Fresh Indian Cottage Cheese)', 'Recipe video above. Homemade paneer is far superior to store bought. It''s softer and creamier, and has much better flavour. It''s easy to make, without special equipment. All it takes is a little patience to let the cheese set in the fridge for 4 hours. Use paneer to make the great Indian classic, Palak Paneer (Spinach Curry with Paneer)', 'https://www.recipetineats.com/tachyon/2021/02/Homemade-Paneer-recipe_3.jpg', 10, 600, 610, 4, '[{"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}]', '[{"ingredients":["2 litres / 2 quarts milk (, full-fat (low-fat won''t work))","4 tbsp lemon juice (sub white vinegar)"]}]', '[{"description":"Heat the milk in a large saucepan over medium high heat until the top becomes foamy, just as looks like it''s about to boil.","images":[],"step":1},{"description":"Turn stove off. Add lemon juice and stir for 1 minute. The milk should begin to curdle. If it doesn’t, turn the stove back on and bring back to a gentle boil until the solids separate.","duration":1,"images":[],"step":2},{"description":"Strain & remove excess water:","images":[],"step":3},{"title":"Line strainer or colander","description":"Place over a deep bowl. Line strainer with 2 layers of cheesecloth (Note 1).","images":[],"step":4},{"title":"Strain","description":"Ladle in half of the curdled milk to begin with, then pour the rest in. Leave until all the liquid drains – this might take 5 to 10 minutes.","images":[],"step":5},{"title":"Rinse","description":"Discard liquid (whey) in the bowl. Bundle the paneer up in the cheesecloth (it will still be quite watery at this stage) then rinse bundle briefly under cold tap water. This helps to remove lemon flavour + cool for easier handling.","images":[],"step":6},{"description":"Squeeze out excess water by twisting the cheesecloth and squeezing the bundle, but not so hard that paneer squeezes out through the cloth. Once liquid no longer comes out, stop. The paneer will still be quite soft at this stage.","images":[],"step":7},{"title":"Weigh cheese down with weights","description":"Shape cheese into a disc around 2cm / ¾\" thick, still wrapped in cheesecloth. Place in a strainer or colander set over a bowl. Top with a small plate then 2 x 400g/14oz cans (or similar weight).","images":[],"step":8},{"description":"Refrigerate for 4 hours. During this time the paneer will set (become firm) and remaining liquid will drain out. (Note 2)","images":[],"step":9},{"description":"Storage / cutting:","images":[],"step":10},{"description":"Remove paneer from fridge and carefully unwrap. There will be a dent in the middle, this is normal (it''s from the draining).","images":[],"step":11},{"description":"At this stage, the paneer is now ready for use. You can either cut it immediately and use in a recipe (such as Palak Paneer!), or store the whole uncut block for another time and just cut when needed.","images":[],"step":12},{"description":"Store in the fridge for up to 2 weeks, or freeze for 3 months.","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a27cf02cc51', 'en', 'US', 'Vietnamese pork noodle bowls (bun thit nuong)', 'Recipe video above. Popular Vietnamese street food! Fabulous combination of contrasting flavours and textures, fresh vegetables with flavourful lemongrass marinated pork, noodles and herbs, all doused in a mild nuoc cham sauce (so you can use lots).Light and fresh yet anything but dull. Excellent DIY spread for gatherings - lay it all out on tables and let everyone put their own bowls together. Chicken version here. Slightly different toppings because chicken is a white meat, pork is richer. :)', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-6.jpg', 30, 10, 40, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 3.0, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 batch lemongrass marinated pork (it''s marinated overnight. 8 pieces, serves 4)","200g/ 7oz dried vermicelli noodles (Note 1)","1 head soft lettuce (like butter lettuce), torn into large bite size pieces (or 4 cups shredded iceberg, cos/romaine)","2 cucumbers (, halved lengthwise then sliced on the diagonal 3mm / 0.15\" thick)","2 cups bean sprouts","Handful mint leaves","Handful cilantro/coriander","1/4 cup finely chopped unsalted peanuts","Sliced red chilli (for garnish - optional)","Lime wedges (to serve - optional but recommended)"]},{"ingredients":["2 medium carrots (, peeled cut into 2-3mm / 1/10″ batons )","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt (kosher salt)","3/4 cup rice vinegar (sub apple cider vinegar)"],"purpose":"Vietnamese pickled vegetables (Note 2)"},{"ingredients":["4 1/2 tbsp white sugar","4 1/2 tbsp fish sauce (Note 3)","3 tbsp rice wine vinegar","3 tbsp lime juice","1/2 cup water","2 birds eye chilli or Thai chilli (, deseeded and finely chopped (Note 4))","5 cloves garlic (, finely chopped)"],"purpose":"Nuoc cham Vietnamese sauce (Note 3):"}]', '[{"description":"Make pickled vegetables:","images":[],"step":1},{"title":"Pickle","description":"In a large bowl, dissolve the salt and sugar in the hot water. Stir in vinegar. Add carrots and daikon – they should just about be covered.","images":[],"step":2},{"title":"2 hours","description":"Leave for 2 hours until slightly floppy. Drain well then use per recipe.","images":[],"step":3},{"title":"Nuoc cham sauce","description":"Mix ingredients together. Until sugar is dissolved.","images":[],"step":4},{"title":"Vermicelli noodles","description":"Soak in boiling water for 5 minutes (or per packet directions). Drain, rinse under tap water, then cool and drain thoroughly (nobody likes watery noodles!).","duration":5,"images":[],"step":5},{"title":"Toppings","description":"Prepare all the other toppings, ready to use.","images":[],"step":6},{"description":"Cook pork per the recipe.","images":[],"step":7},{"title":"Assemble bowls","description":"Place noodles in a bowl. Top with lettuce, pickled vegetables, cucumber and bean sprouts. Slice pork, place 2 steaks on each bowl. Top with herbs, sprinkle with peanuts and sliced chilli. Add a lime wedge.","images":[],"step":8},{"description":"Serve with nuoc cham on the side so everybody can help themselves. Douse generously! Dive in and eat!","images":[],"step":9}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
